const e=[{id:1,code:"FIRE-101",icon:"Flame",accent:"#ea580c",title:"زانستی ئاگر و داینامیکی سووتان",subtitle:"Fire Science & Combustion Dynamics",summary:"شیکردنەوەی کیمیایی و فیزیایی ئاگر: هەرەمی ئاگر، شێوازەکانی گواستنەوەی گەرما، قۆناغەکانی گەشەکردن، و دیاردەکانی Flashover و Backdraft.",blocks:[{body:`دەستپێک: ئاگر تەنها دیاردەیەکی بینراو نییە، بەڵکو لە زانستەکانی ئەندازیاری و کیمیادا وەک پرۆسەیەکی ئۆکسانبوونی خێرا (Rapid Oxidation) دەناسرێت، کە تێیدا وزە بە شێوەی گەرما و ڕووناکی ئازاد دەبێت. مرۆڤایەتی لە سەردەمە کۆنەکانەوە ئاگری بۆ پێشخستنی شارستانییەت بەکارهێناوە، بەڵام ئەگەر ئاگر بە دروستی کۆنتڕۆڵ نەکرێت، دەبێتە هێزێکی وێرانکەر. بۆ ئەندازیارانی سەلامەتی و شارەزایانی بەرگریی شارستانی، تێگەیشتن لە داینامیکی سووتان تەنها پێویستییەک نییە، بەڵکو بنەمای سەرەکیی پاراستنی ژیان و سامانە.

سروشتی زانستیی ئاگر: ئاگر کارلێکێکی کیمیایی ئاڵۆزە لە جۆری گەرما-دەرکەر (Exothermic Reaction). ئەم پرۆسەیە پێویستی بە هاوسەنگییەکی دروست لە نێوان سێ یان چوار توخمی سەرەکیدا هەیە. جیاوازیی نێوان ئاگرێکی کۆنتڕۆڵکراو و کارەساتێکی ئاگر، بەستراوەتەوە بە تێگەیشتنمان لە شێوازی بڵاوبوونەوەی گەرما و گۆڕانکارییە فیزیاییەکانی ماددەکان.

ئامانجی ئەم مۆدیوولە: لە ئاستی ناسینی ئاسایی ئاگرەوە دەپەڕینەوە بەرەو لێکۆڵینەوەیەکی وردتر لەسەر: (١) کیمیای سووتان: چۆن مۆلیکولەکانی ماددە تێک دەشکێن و دەبنە گازی ئاگرگر؛ (٢) فیزیای گواستنەوەی وزە: چۆنیەتیی جووڵەی گەرما لە ڕێگەی گەیاندن، هەڵگرتن و تیشکدانەوە؛ (٣) ڕەفتاری ئاگر لە شوێنە داخراوەکاندا: شیکردنەوەی دیاردە کوشندەکانی وەک Flashover و Backdraft. ئەم زانیارییانە بنەمان بۆ هەر خوێندکارێکی زانکۆ یان ئەندازیارێک کە دەیەوێت بە شێوازێکی زانستی سیستەمەکانی پاراستن و ستراتیژییەکانی کوژاندنەوەی ئاگر دیزاین بکات.`},{heading:"١. تیۆری هەرەمی ئاگر: شیکردنەوەی داینامیکی (The Fire Tetrahedron)",body:"لە ئاستی ئەکادیمی و ئەندازیاریدا، لە چەمکی «سێگۆشەی ئاگر» دەپەڕینەوە و پشت بە «هەرەمی ئاگر» (Fire Tetrahedron) دەبەستین. جیاوازیی سەرەکی ئەوەیە کە هەرەمەکە نیشان دەدات چۆن ئاگری گڕدار (Flaming Combustion) وەک پرۆسەیەکی کیمیایی بەردەوام کار دەکات. ئەگەر یەکێک لەم چوار توخمە لاببرێت، یان هاوسەنگییان تێک بچێت، ئاگرەکە دەکوژێتەوە.",points:["ماددەی سووتەمەنی (Fuel / Reducing Agent): دەتوانێت لە هەر سێ دۆخە فیزیاییەکەدا بێت (ڕەق، شل، گاز). تێبینییەکی زانستیی گرنگ: ماددە ڕەق و شلەکان خۆیان بە گڕ ناسووتێن؛ ماددەی ڕەق پێویستی بە شیبوونەوە بە گەرما (Pyrolysis) هەیە و ماددەی شل پێویستی بە بەهەڵمبوون (Vaporization) هەیە. ڕێژەی ڕووبەر بەرامبەر بارستە (Surface-to-Mass Ratio) زۆر گرنگە: تا ماددەکە وردتر بێت، خێراتر دەچێتە ناو پرۆسەی سووتانەوە.","ماددەی ئۆکسیدکەر (Oxidizing Agent): لە زۆربەی بارودۆخەکاندا، ئۆکسجینی هەوا (نزیکەی ٢١٪) سەرچاوەی سەرەکییە. بە گشتی، ئەگەر ڕێژەی ئۆکسجین لە نزیکەی ١٦٪ کەمتر ببێتەوە، سووتانی گڕدار (Flaming) لاواز دەبێت یان دەوەستێت و دەبێتە سووتانی بێ گڕ (Smoldering). چەمکێکی پێشکەوتوو: هەندێک ماددە (وەک Ammonium Nitrate) خۆیان ماددەی ئۆکسیدکەرن و ئۆکسجین دەدەن بە ئاگرەکە، بۆیە کوژاندنەوەیان زۆر سەختە.","گەرما (Heat / Activation Energy): ئەو وزەیەیە کە سووتان دەست پێ دەکات و بەردەوامی پێ دەدات. گەڕانەوەی گەرما (Thermal Feedback) دیاردەیەکی فیزیاییە کە تێیدا ئاگر گەرما دەگەڕێنێتەوە بۆ ئەو ماددە سووتەمەنییەی کە هێشتا نەسووتاوە. پلەی خۆگڕگرتن (Autoignition Temperature) کەمترین پلەی گەرمایە کە ماددە تێیدا بەبێ پریشک یان گڕ خۆی ئاگر دەگرێت.","کارلێکی زنجیرەیی کیمیایی (Uninhibited Chemical Chain Reaction): ئەم توخمە ئاگر لە گڕێکی کاتییەوە دەگۆڕێت بۆ سووتانێکی بەردەوام. ڕادیکاڵە ئازادەکان (Free Radicals) وەک H و O و OH بە خێراییەکی زۆر لەگەڵ مۆلیکولە نوێیەکان کارلێک دەکەن و وزە ئازاد دەکەن. هەندێک ماددەی کوژاندنەوە (وەک Halon و تۆزی کیمیایی وشک - Dry Chemical) ئەم ڕادیکاڵانە لەناو دەبەن و بەم شێوەیە کارلێکی زنجیرەیی دەپچڕێنن.","تێبینییە زانستییەکان: پەستانی هەڵم (Vapor Pressure): تا بەرزتر بێت، ماددەکە زووتر هەڵم دەردەدات و زووتر ئاگر دەگرێت. سنوورەکانی سووتان (Flammability Limits): ئاگر تەنها لە نێوان ڕێژەیەکی گونجاوی سووتەمەنی و هەوادا دروست دەبێت؛ ئەگەر گاز زۆر زیاد بێت (Rich) یان زۆر کەم بێت (Lean)، ئاگر دروست نابێت."]},{heading:"٢. شێوازەکانی گواستنەوەی گەرما (Heat Transfer Mechanisms)",body:"ئاگر لە شوێنێکی دیاریکراودا نامێنێتەوە، بەڵکو بە سێ ڕێگای جیاواز بڵاو دەبێتەوە و وزە دەگوازێتەوە بۆ ماددەکانی تر. تێگەیشتن لەم میکانیزمانە بۆ ئەندازیاران زۆر گرنگە بۆ ئەوەی بزانن ئاگر چۆن گەورە دەبێت و چۆن دەتوانن ڕێگری لێ بکەن:",points:["گەیاندن (Conduction): گواستنەوەی گەرمایە لە ڕێگەی بەرکەوتنی ڕاستەوخۆ لە ناو ماددە ڕەقەکاندا. بۆ نموونە، ئەگەر لایەکی دەرگایەکی ئاسنین یان دیوارێکی کانزایی بەهۆی ئاگرەوە گەرم ببێت، گەرما لە ناو ماددەکەدا دەگاتە لاکەی تر و دەتوانێت ماددەکانی ئەو لایەش بگەیەنێتە پلەی گڕگرتن. کانزاکان (وەک ئاسن، مس، ئەلەمنیۆم) گەرما زۆر باش دەگەیەنن (Thermal Conductivity ی بەرز)، بەڵام دار، پلاستیک و کۆنکریت کەمتر دەیگەیەنن. ئەمە یەکێکە لە هۆکارەکانی ئەوەی کە دیوارە دژە-ئاگرەکان لە ماددەی کەم-گەیەنەر دروست دەکرێن.","هەڵگرتن (Convection): گواستنەوەی گەرمایە لە ڕێگەی جووڵەی شلەمەنی یان گازەکان. هەوای گەرم و گازەکانی سووتان لە هەوای سارد سووکترن، بۆیە بەرەو سەرەوە دەچن (یاسای Buoyancy). ئەمە یەکێکە لە مەترسیدارترین شێوازەکان لە بینا داخراوەکاندا، چونکە هەوای گەرم، دووکەڵ و گازە ژەهراوییەکان لە ژێر بنمیچدا کۆ دەبنەوە و دەتوانن بگەنە ٦٠٠–٨٠٠ پلەی سیلیزی. کاتێک ئەم چینە گەرمە دەگاتە ماددەکانی سەرەوە، دەیانگەیەنێتە خاڵی گڕگرتن، و دەبێتە هۆی بڵاوبوونەوەی ئاگر بۆ ژوور و نهۆمەکانی تر.","تیشکدانەوە (Radiation): گواستنەوەی وزەی گەرمایە بە شێوەی شەپۆلی ئەلیکترۆموگناتیسی (Electromagnetic Waves)، بە تایبەتی تیشکی ژێر-سوور (Infrared). تیشکدانەوە پێویستی بە بەرکەوتنی ڕاستەوخۆ یان بە هەوا نییە؛ وزە لە بۆشاییشدا (Vacuum) دەگوازرێتەوە. بۆیە ئاگرێکی گەورە دەتوانێت بینایەکی نزیک بگەیەنێتە پلەی گڕگرتن بەبێ ئەوەی گڕ پێی بگات. لەبەر ئەم هۆیە، ئاگرکوژەکان جلوبەرگی پاراستنی تایبەت لەبەر دەکەن و مەودایەکی سەلامەت لە ئاگرەکە دەپارێزن."]},{heading:"٣. قۆناغەکانی گەشەکردنی ئاگر (Stages of Fire Development)",body:"هەر ئاگرێک، لە ئاگرێکی بچووکی سەر سۆبەوە تا ئاگری بینایەکی گەورە، بە گشتی بە چوار قۆناغی ستاندارددا تێدەپەڕێت. ناسینی ئەم قۆناغانە بۆ ئاگرکوژەکان زۆر گرنگە بۆ ئەوەی بزانن کەی و بە کام ستراتیژ دەستێوەردان بکەن:",points:["قۆناغی دەستپێک (Incipient Stage): ئەمە سەرەتاییترین قۆناغی ئاگرە. پلەی گەرما هێشتا نزمە، دووکەڵ هەیە بەڵام کەمە، و ئاگرەکە هێشتا بچووکە و لە شوێنێکی دیاریکراودایە. لەم قۆناغەدا، ئاگر بە ئاسانی بە ئاگرکوژێنەرەوەیەکی دەستی کۆنتڕۆڵ دەکرێت. ڕێژەی ئۆکسجین هێشتا نزیکەی ٢١٪ دەبێت. ئەمە باشترین کاتە بۆ کوژاندنەوە چونکە ئاگرەکە هێشتا بچووکە.","قۆناغی گەشەکردن (Growth Stage): ئاگرەکە بە خێرایی گەورە دەبێت؛ گەرما زیاد دەبێت، دووکەڵ زۆر دەبێت، و گڕ دەگاتە ماددە نزیکەکان. پلەی گەرما دەگاتە چەند سەد پلەی سیلیزی و هەوای گەرم لە ژێر بنمیچدا کۆ دەبێتەوە. لەم قۆناغەدا، مەترسیی Rollover هەیە: گڕگرتنی گازە نەسووتاوەکانی ناو چینە گەرمەکەی ژێر بنمیچ، کە بە شێوەی زمانەی گڕ لە ژێر بنمیچدا بڵاو دەبنەوە. ئەگەر دەستێوەردان نەکرێت، ئاگرەکە بە خێرایی دەچێتە قۆناغی دواتر.","قۆناغی گەشەی تەواو (Fully Developed Stage): گەرمترین و مەترسیدارترین قۆناغە. دوای Flashover، هەموو ماددە سووتەمەنییەکانی ژوورەکە ئاگریان گرتووە و پێکەوە دەسووتێن. پلەی گەرما دەتوانێت لە ١٠٠٠ پلەی سیلیزی تێپەڕێت. گڕ لە دەرگا و پەنجەرەکانەوە دەردەچێت و دووکەڵی ڕەش هەموو شوێنەکە دادەگرێت. چوونە ناو ژوورەکە لەم قۆناغەدا زۆر مەترسیدارە و تەنها بە پاراستنی تەواو و بە پلانێکی تاکتیکی دەکرێت. ئاگرەکە زۆربەی ئۆکسجینی بەردەست بەکاردەهێنێت، بۆیە سووتان بەهۆی هەواوە سنووردار دەبێت (Ventilation-Limited).","قۆناغی دابەزین (Decay Stage): دوای ئەوەی زۆربەی سووتەمەنی سووتا یان ئۆکسجین کەم بووەوە، ئاگرەکە هێدی هێدی لاواز دەبێت و پلەی گەرما دادەبەزێت، بەڵام هێشتا مەترسییەکی گەورە هەیە: Backdraft. ئەگەر ژوورێک پڕ بێت لە گازی ئاگرگری نەسووتاو و کەسێک لەناکاو دەرگاکە بکاتەوە و ئۆکسجین بچێتە ژوورەوە، دەکرێت تەقینەوەیەکی گەورە ڕوو بدات کە هەموو کەسانی نزیک بکوژێت."]},{heading:"٤. دیاردە مەترسیدارەکان (Dangerous Fire Phenomena)",body:"لە زانستی ئاگردا، دوو دیاردەی کوشندە هەن کە هەر ئەندازیار و ئاگرکوژێک پێویستە بە تەواوی ئاگاداریان بێت:",points:["Flashover: گڕگرتنی لەناکاوی هەموو ماددە سووتەمەنییەکانی ژوورێک پێکەوە. بە گشتی کاتێک ڕوو دەدات کە پلەی گەرمای چینی گاز لە ژێر بنمیچدا دەگاتە نزیکەی ٥٠٠–٦٠٠ پلەی سیلیزی، و تیشکدانەوەی گەرما (Radiant Heat) لە بنمیچەوە هەموو ماددەکانی ژوورەکە دەگەیەنێتە خاڵی گڕگرتن. ئەم گۆڕانە لە ماوەیەکی زۆر کورتدا (چەند چرکەیەک) ڕوو دەدات و ژوورەکە دەکاتە کوورەیەکی ئاگر. نیشانەکانی Flashover: دووکەڵی ڕەش و چڕ لە ژێر بنمیچدا، زمانەی گڕ لە ژێر بنمیچدا (Rollover)، دەرچوونی دووکەڵ لە کەلوپەلەکان، و گەرمایەکی لەناکاوی توند. کاتێک ئاگرکوژەکان ئەم نیشانانە دەبینن، پێویستە یەکسەر ژوورەکە جێ بهێڵن یان بە ئاو چینی گازەکە سارد بکەنەوە.","Backdraft: تەقینەوەیەکی ئاگرە کە ڕوو دەدات کاتێک ئۆکسجین لەناکاو دێتە ناو ژوورێکی گەرم کە ئۆکسجینی تێدا کەم بووەتەوە، بەڵام هێشتا گازی ئاگرگر و گەرمای زۆری تێدایە. ئەم ژوورە وەک بۆمبێک وایە کە چاوەڕێی ئۆکسجینە. کاتێک دەرگاکە دەکرێتەوە، هەوای تازە دەچێتە ژوورەوە، گازە ئاگرگرەکان بە یەکجار گڕ دەگرن و تەقینەوە ڕوو دەدات و گڕێکی گەورە بەرەو دەرەوە فڕێ دەدات. نیشانەکانی Backdraft: دووکەڵی زەرد-قاوەیی، پەنجەرەی ڕەشبوو بە دووکەڵ، گەرمبوونی دەرگا، جووڵەی پاڵنان و هەڵمژینی دووکەڵ (Pulsating Smoke)، و دەنگێکی فیکەئاسا لە ژوورەکەوە. لەم حاڵەتانەدا دەرگا بە ئاسانی مەکەرەوە؛ پێویستە سەرەتا لە بەرزترین شوێنەوە هەوا دەربکرێت (Vertical Ventilation) یان دەرگاکە بە شێوەیەکی کۆنتڕۆڵکراو و لە لایەکی پارێزراوەوە بکرێتەوە."]},{heading:"٥. شیبوونەوە بە گەرما (Pyrolysis)",body:"Pyrolysis ئەو پرۆسە کیمیاییەیە کە تێیدا ماددە ڕەقەکان بەهۆی گەرماوە تێک دەشکێن و دەبنە گازی ئاگرگر. بە زمانی زانستی، ماددەی ڕەق خۆی بە گڕ ناسووتێت؛ ئەو گازانەی لە Pyrolysis پەیدا دەبن دەسووتێن. بۆ نموونە، دار خۆی گڕ ناگرێت، بەڵام کاتێک دەگاتە پلەی بەرزی گەرما (نزیکەی ٢٠٠–٣٠٠ پلەی سیلیزی)، مۆلیکولەکانی تێک دەشکێن و هەڵمی ئاگرگر (Volatile Gases) پەیدا دەکەن، و ئەم هەڵمانە گڕ دەگرن و دەسووتێن. پاشماوەی ئەم پرۆسەیە خەڵوزە (Char) کە زۆربەی کاربۆنە.",points:["ماددە پلاستیکییەکان لە کاتی Pyrolysis دا گازی زۆر ژەهراوی بەرهەم دەهێنن، وەک هایدرۆجین سیانید (HCN) و مۆنۆکسیدی کاربۆن (CO).","ماددەکانی وەک ئیسفەنجی کەلوپەلی ناوماڵ (Foam) و پۆلیستایرین زۆر بە خێرایی دەچنە ناو پرۆسەی Pyrolysis ەوە و گازی مەترسیدار بەرهەم دەهێنن.","زانینی پلەی Pyrolysis ی ماددەکان (Pyrolysis Temperature) بۆ دیزاینی ماددەکانی بیناسازی و کەلوپەلی ناوماڵ گرنگە، بۆ ئەوەی بە ئاستەم ئاگر بگرن."]},{heading:"٦. بەرهەمەکانی سووتان و ژەهراویبوون (Products of Combustion)",body:"کاتێک ماددەکان دەسووتێن، گازی جۆراوجۆر بەرهەم دێن کە هەندێکیان کوشندەن:",points:["مۆنۆکسیدی کاربۆن (CO): گازێکی بێ بۆن و بێ ڕەنگە بەڵام زۆر ژەهراوییە. لەگەڵ هیمۆگلۆبینی خوێندا دەبەسترێتەوە و ڕێگری لە گواستنەوەی ئۆکسجین بۆ شانەکان و مێشک دەکات. زۆربەی مردنەکانی ئاگر بەهۆی هەڵمژینی دووکەڵ و گازە ژەهراوییەکانەوە (وەک CO و HCN) ڕوو دەدەن، نەک بەهۆی سووتانی جەستەوە.","دیۆکسیدی کاربۆن (CO₂): لە ڕێژەی کەمدا گازێکی ژەهراوی نییە، بەڵام لە ڕێژەی بەرزدا خۆی ژەهراوی دەبێت و هەروەها دەبێتە هۆی خنکان (Asphyxiation) چونکە جێگەی ئۆکسجین دەگرێتەوە.","هایدرۆجین سیانید (HCN): گازێکی زۆر کوشندەیە کە لە سووتانی پلاستیک، ئیسفەنج و هەندێک قوماش بەرهەم دێت. لە چڕیی بەرزدا دەتوانێت لە ماوەیەکی زۆر کورتدا بکوژێت.","هایدرۆجین کلۆراید (HCl): گازێکی داخورێنەرە (Corrosive) کە لە سووتانی PVC (پلاستیکی بۆری و وایەرەکان) بەرهەم دێت و زیان بە سییەکان و چاوەکان دەگەیەنێت.","دووکەڵ (Smoke): دووکەڵ تەنها ڕەنگێک نییە؛ پڕە لە تەنۆلکەی ورد (Particulates)، گاز و ماددەی کیمیایی. دووکەڵ دەتوانێت ببێتە هۆی خنکان، کوێربوونی کاتی و زیانی سییەکان."]},{heading:"٧. پۆلێنکردنی ئاگر: سیستەمی NFPA و سیستەمی ئەورووپی EN 2",body:"بۆ هەڵبژاردنی ئاگرکوژێنەرەوەی دروست، پێویستە پۆلێنکردنی ئاگر بزانیت. لێرەدا سیستەمی ئەمریکی NFPA (NFPA 10) بەکاردەهێنرێت، و جیاوازییەکانی سیستەمی ئەورووپی EN 2 لە هەر خاڵێکدا دیاری کراون. هەر پۆلێک پێویستی بە شێوازێکی تایبەتی کوژاندنەوە هەیە:",points:["Class A (هەردوو سیستەم) - ماددە ڕەقەکان: دار، کاغەز، قوماش، پلاستیکی ئاسایی. کوژاندنەوە: ساردکردنەوە بە ئاو (Cooling). ئاگرکوژێنەرەوەکانی ئاو، کەف (Foam) و تۆزی ABC گونجاون.","Class B - شلەمەنییە ئاگرگرەکان: بەنزین، نەوت، بۆیە، سۆڵڤێنت (لە NFPA دا گازە ئاگرگرەکانیش لە ناو پۆلی B دان؛ لە EN 2 دا گاز پۆلی C ە). کوژاندنەوە: خنکاندن (Smothering) بە کەف یان CO₂ یان تۆزی ABC. پڕژاندنی ئاو بە ستوونێکی ڕاستەوخۆ گونجاو نییە چونکە شلەمەنییە سووتاوەکە بڵاو دەکاتەوە.","Class C (NFPA) - ئاگری ئامێرە کارەباییەکانی بەستراو بە کارەباوە: پانێڵ، وایەر، ئامێر. کوژاندنەوە: ماددەی نەگەیەنەری کارەبا (Non-conductive) وەک CO₂ یان تۆزی کیمیایی. ئەگەر سەلامەت بوو، سەرەتا کارەبا بپچڕێنە. لە سیستەمی EN 2 دا، کارەبا پۆلێکی جیاواز نییە و پۆلی C بۆ گازە ئاگرگرەکانە.","Class D (هەردوو سیستەم) - کانزا ئاگرگرەکان: مەگنیسیۆم، تیتانیۆم، سۆدیۆم، پۆتاسیۆم، لیتیۆم (کانزا). کوژاندنەوە: تۆزی تایبەتی پۆلی D (وەک تۆزی لەسەر بنەمای گرافیت یان سۆدیۆم کلۆراید) یان لمی وشک. ئاو زۆر مەترسیدارە چونکە دەتوانێت کارلێکێکی توند و تەقینەوە دروست بکات. تێبینی: پاترییەکانی لیتیۆم-ئایۆن (Lithium-ion) لیتیۆمی کانزاییان تێدا نییە؛ بۆ ئاگرەکەیان ئاو و ساردکردنەوەی بەردەوام پێشنیار دەکرێت.","Class K (NFPA) / Class F (EN 2) - ڕۆن و چەورییەکانی چێشتلێنان: لە چێشتخانەی ڕێستۆرانتەکان و ماڵەکاندا. کوژاندنەوە: ئاگرکوژێنەرەوەی Wet Chemical کە پرۆسەی سابوونبوون (Saponification) دروست دەکات: ڕۆنەکە دەبێتە چینێکی وەک سابوون کە ئۆکسجین دوور دەخاتەوە و ئاگرەکە دەکوژێنێتەوە. هەرگیز ئاو مەکە سەر ڕۆنی سووتاو."]},{heading:"٨. تێبینییەکی گرنگ بۆ خوێندکاران",body:"تێگەیشتن لە هەرەمی ئاگر کلیلی سەرەکییە بۆ هەڵبژاردنی ماددەی کوژاندنەوەی دروست. هەر توخمێک لە چوار توخمەکەی هەرەمەکە بشکێنرێت، ئاگرەکە دەکوژێتەوە:",points:["لابردنی سووتەمەنی (Remove Fuel): دوورخستنەوەی ماددە ئاگرگرەکان لە ناوچەی ئاگرەکە، یان داخستنی سەرچاوەی گاز.","لابردنی گەرما (Remove Heat): ساردکردنەوە بە ئاو یان بە ماددەی ساردکەرەوە.","لابردنی ئۆکسجین (Remove Oxygen): خنکاندن و داپۆشینی ئاگرەکە (وەک کەف یان بەتانیی ئاگر).","پچڕاندنی کارلێکی زنجیرەیی (Break Chain Reaction): بەکارهێنانی تۆزی کیمیایی یان ماددەی تایبەت."]}],media:[{kind:"video",src:"media/videos/uni_01_fire_dynamics.mp4",title:"داینامیکی ئاگر",description:"ڕوونکردنەوەیەکی تەواو لەسەر قۆناغەکانی گەشەکردنی ئاگر و چۆنیەتیی بڵاوبوونەوەی"},{kind:"image",src:"media/images/uni_01_tetrahedron.png",title:"هەرەمی ئاگر",description:"دیاگرامی تەواوی هەرەمی ئاگر و چوار توخمە سەرەکییەکەی"},{kind:"video",src:"media/videos/uni_01_flashover.mp4",title:"دیاردەی Flashover",description:"تاقیکردنەوەیەکی تاقیگەیی کە Flashover نیشان دەدات"},{kind:"image",src:"media/images/uni_01_heat_transfer.png",title:"شێوازەکانی گواستنەوەی گەرما",description:"Conduction، Convection و Radiation بە وێنە"},{kind:"video",src:"media/videos/uni_01_backdraft.mp4",title:"مەترسیی Backdraft",description:"چۆنیەتیی ناسینەوەی نیشانەکانی مەترسی"},{kind:"image",src:"media/images/uni_01_fire_classes.png",title:"پۆلێنکردنی ئاگر",description:"خشتەی پۆلەکانی ئاگر بەپێی NFPA و EN 2، بە ڕەنگ و نیشانە"},{kind:"video",src:"media/videos/uni_01_extinguisher_types.mp4",title:"جۆرەکانی ئاگرکوژێنەرەوە",description:"چۆنیەتیی هەڵبژاردن و بەکارهێنانی ئاگرکوژێنەرەوەی دروست"}],quiz:[{question:"کام توخم دەخرێتە سەر سێگۆشەی ئاگر بۆ ئەوەی ببێتە هەرەمی ئاگر؟",options:[{text:"گەرما",correct:!1},{text:"کارلێکی زنجیرەیی کیمیایی",correct:!0},{text:"ئۆکسجین",correct:!1},{text:"سووتەمەنی",correct:!1}],explanation:"کارلێکی زنجیرەیی کیمیایی (Chemical Chain Reaction) توخمی چوارەمە کە هەرەمی ئاگری پێ تەواو دەبێت. ئەم پرۆسەیە ئاگرەکە بەردەوام دەکات و ڕێگە دەدات خۆی بڵاو ببێتەوە."},{question:"Flashover زۆربەی جار لە کام قۆناغی ئاگردا ڕوو دەدات؟",options:[{text:"Incipient",correct:!1},{text:"Growth",correct:!0},{text:"Fully Developed",correct:!1},{text:"Decay",correct:!1}],explanation:"Flashover بە گشتی لە کۆتایی قۆناغی Growth دا ڕوو دەدات و ئاگرەکە دەباتە قۆناغی Fully Developed؛ کاتێک پلەی گەرما بەرز دەبێتەوە و هەموو ماددەکان لە خاڵی گڕگرتن نزیک دەبنەوە."},{question:"کام گاز زۆرترین کەس لە ئاگرەکاندا دەکوژێت؟",options:[{text:"ئۆکسجین",correct:!1},{text:"مۆنۆکسیدی کاربۆن (CO)",correct:!0},{text:"نایترۆجین",correct:!1},{text:"هایدرۆجین",correct:!1}],explanation:"مۆنۆکسیدی کاربۆن (CO) سەرەکیترین گازی کوشندەیە لە ئاگرەکاندا، چونکە بێ بۆن و بێ ڕەنگە و بە خێرایی گواستنەوەی ئۆکسجین لە خوێندا ڕادەگرێت."},{question:"Pyrolysis چییە؟",options:[{text:"کوژاندنەوەی ئاگر",correct:!1},{text:"شیبوونەوەی ماددە بە گەرما بۆ هەڵمی ئاگرگر",correct:!0},{text:"تەقینەوە",correct:!1},{text:"ساردکردنەوە",correct:!1}],explanation:"Pyrolysis پرۆسەیەکی کیمیاییە کە تێیدا ماددەکان بەهۆی گەرماوە تێک دەشکێن و دەبنە گازی ئاگرگر؛ ئەم گازانە گڕ دەگرن و دەسووتێن."},{question:"بۆ ئاگری Class B (شلەمەنییە ئاگرگرەکان)، کام ئاگرکوژێنەرەوە باشترە؟",options:[{text:"ئاو",correct:!1},{text:"کەف (Foam) یان CO₂",correct:!0},{text:"خۆڵ",correct:!1},{text:"هەوا",correct:!1}],explanation:"ئاگری شلەمەنییە ئاگرگرەکان (Class B) پێویستی بە خنکاندن هەیە. کەف یان CO₂ گونجاون چونکە ئۆکسجینی لێ دەبڕن. ئاو گونجاو نییە چونکە شلەمەنییە سووتاوەکە بڵاو دەکاتەوە."},{question:"کام لەمانە نیشانەیەکی Backdraft ە؟",options:[{text:"دووکەڵی سپی",correct:!1},{text:"دووکەڵی زەرد-قاوەیی و گەرمبوونی دەرگا",correct:!0},{text:"ساردبوونی ژوورەکە",correct:!1},{text:"ڕووناکی",correct:!1}],explanation:"Backdraft نیشانەی تایبەتی هەیە: دووکەڵی زەرد-قاوەیی، گەرمبوونی دەرگا، و جووڵەی پاڵنان و هەڵمژینی دووکەڵ. ئەمە نیشان دەدات کە گازی ئاگرگر لە ژوورەکەدا هەیە و چاوەڕێی ئۆکسجینە."}]},{id:2,code:"CHEM-202",icon:"FlaskConical",accent:"#9333ea",title:"سەلامەتیی ماددە کیمیاییەکان (HazMat)",subtitle:"Hazardous Materials Management & Chemical Safety",summary:"ناسینەوەی ماددە مەترسیدارەکان، سیستەمی جیهانیی GHS، ئەڵماسی NFPA 704، وەڵامدانەوەی ڕژانی کیمیایی لە تاقیگە و کارگەکاندا، و خۆپاراستن.",blocks:[{body:`لە جیهانی ئەمڕۆدا، ڕۆژانە هەزاران ماددەی کیمیایی بەکاردەهێنین: لە تاقیگەکان، کارگەکان، نەخۆشخانەکان و تەنانەت لە ماڵەکاندا. بەڵام زۆرێک لەم ماددانە مەترسیدارن ئەگەر بە شێوەیەکی نادروست بەکاربهێنرێن یان هەڵبگیرێن. ماددە کیمیاییەکان دەتوانن ژەهراوی بکەن، بسووتێنن، بتەقنەوە، یان ماددەکانی تر بخۆن و داخوران دروست بکەن (Corrosion). بۆیە هەر کەسێک لەگەڵ ماددە کیمیاییەکاندا کار دەکات، چ خوێندکاری تاقیگە بێت، چ کارمەندی کارگە یان ئەندازیار، پێویستە بە تەواوی ئاگاداری مەترسییەکان و ڕێگاکانی خۆپاراستن بێت.

لەم مۆدیوولەدا، دەچینە ناو بابەتی سەلامەتیی کیمیایی (Chemical Safety). فێر دەبین چۆن ماددەکان بە سیستەمە ستانداردەکانی وەک GHS و NFPA 704 بناسینەوە، چۆن پەڕەی زانیارییەکانی سەلامەتی (SDS) بخوێنینەوە، و لە کاتی ڕژانی کیمیایی یان ڕووداوێکدا چ هەنگاوێک بنێین.`},{heading:"١. سیستەمی جیهانیی ناسینەوەی مەترسییەکان - GHS",body:"GHS سیستەمێکی نێودەوڵەتییە کە لە ژێر سەرپەرشتیی نەتەوە یەکگرتووەکان (UN) دانراوە بۆ پۆلێنکردن و نیشانەکردنی ماددە مەترسیدارەکان بە یەک شێوە لە سەرانسەری جیهاندا. نۆ هێماکەی (Pictograms) ئەمانەن:",points:["Flame (گڕ): ماددە ئاگرگرەکان (Flammable) وەک ئەسیتۆن، بەنزین و ئەلکهول.","Skull and Crossbones (کەللەسەر): ماددە زۆر ژەهراوییەکان (Acute Toxicity).","Corrosion (داخوران): ترش و بنچینەکان (ئەسید و باز) کە پێست دەسووتێنن و کانزاکان دەخۆن.","Exploding Bomb (بۆمبی تەقیو): ماددە تەقەمەنییەکان یان ناجێگیرەکان.","Exclamation Mark (نیشانەی ئاگادارکردنەوە): مەترسییە تەندروستییە سووکترەکان (وەک وروژاندنی پێست).","Environment (ژینگە): زیان بە ژینگەی ئاو و زیندەوەران.","Health Hazard (مەترسیی تەندروستی): مەترسییە درێژخایەنەکان (وەک شێرپەنجە و زیانی سییەکان).","Gas Under Pressure: گازی ژێر پەستان (سلیندەر).","Oxidizer: ماددە ئۆکسیدکەرەکان کە ئاگر توندتر دەکەن."]},{heading:"٢. ئەڵماسی NFPA 704 (Fire Diamond)",body:"سیستەمێکی بینراوە بۆ ناسینەوەی خێرای مەترسییەکان لەسەر دەرگا و کۆگاکان. هەریەک لە ڕەنگەکانی شین، سوور و زەرد ژمارەیەکی لە ٠ تا ٤ هەیە (٤ = بەرزترین مەترسی):",points:["شین - Health Hazard (٠–٤): مەترسیی تەندروستی.","سوور - Flammability (٠–٤): مەترسیی گڕگرتن.","زەرد - Instability (٠–٤): ناجێگیری و کارلێککردن.","سپی - Special Hazards: W (لەگەڵ ئاودا کارلێکێکی مەترسیدار دەکات)، OX (ئۆکسیدکەر)، SA (گازی خنکێنەری سادە - Simple Asphyxiant)."]},{heading:"٣. پەڕەی زانیارییەکانی سەلامەتی - SDS (١٦ بەش)",body:"هەر ماددەیەکی کیمیایی مەترسیدار پێویستە SDS ی تایبەت بە خۆی هەبێت. گرنگترین بەشەکانی بۆ وەڵامدانەوەی تەنگانە:",points:["بەشی ١: ناسینەوەی ماددە (Identification).","بەشی ٢: ناسینەوەی مەترسییەکان (Hazard Identification).","بەشی ٣: پێکهاتە (Composition).","بەشی ٤: فریاکەوتنی سەرەتایی (First Aid).","بەشی ٥: ڕێکارەکانی کوژاندنەوەی ئاگر (Fire-fighting Measures).","بەشی ٦: ڕێکارەکانی ڕژانی نەخوازراو (Accidental Release).","بەشی ٧: هەڵگرتن و بەکارهێنان (Handling and Storage).","بەشی ٨: کۆنتڕۆڵی بەرکەوتن و کەرەستەکانی خۆپاراستن (PPE)."]},{heading:"٤. هەنگاوەکانی ڕژانێکی کیمیایی بچووک",body:"هەنگاوە ڕێکخراوەکان بۆ کۆنتڕۆڵکردنی ڕژانێکی بچووک، تەنها بۆ کەسانی ڕاهێنراو لە تاقیگەدا؛ پێش ئەوەی لە ڕژانەکە نزیک ببیتەوە، ماددەکە بناسە و PPE لەبەر بکە. تێبینیی گرنگ: ئەگەر ڕژانەکە گەورە بوو، ماددەکە نەناسراو یان زۆر ژەهراوی بوو، یان بۆن یان ئاگر هەبوو، خۆت کۆنتڕۆڵی مەکە: شوێنەکە چۆڵ بکە و پەیوەندی بکە بە ١١٥.",points:["١. ڕاوەستە و کەسانی نزیک ئاگادار بکەرەوە؛ دووریان بخەرەوە.","٢. لە دوورەوە، لە ڕێگەی لەیبڵ یان SDS ماددەکە بناسە.","٣. هەڵسەنگاندن: تەنها ئەگەر ڕژانەکە بچووک بوو، ماددەکە ناسراو و کەم مەترسی بوو و تۆ بۆ ئەم کارە ڕاهێنراو بوویت، خۆت پاکی بکەرەوە؛ ئەگەر نا، دەربچۆ، دەرگاکە لە دوای خۆتەوە دابخە و پەیوەندی بکە بە ١١٥.","٤. ئەو PPE یەی SDS دیاری دەکات لەبەر بکە و سندووقی ڕژان (Spill Kit) ئامادە بکە.","٥. ڕژانەکە لە لێوارەکانەوە بەرەو ناوەڕاست کۆنتڕۆڵ بکە و بە سندووقی ڕژان پاکی بکەرەوە.","٦. بەرپرس ئاگادار بکەرەوە و ڕووداوەکە تۆمار بکە."]},{heading:"٥. کەرەستەکانی پاراستنی کەسی (PPE)",body:"جۆرەکانی PPE بۆ کارکردن لەگەڵ ماددە کیمیاییەکاندا؛ هەڵبژاردنی دروست بەپێی بەشی ٨ لە SDS دەبێت:",points:["دەستکێش: نایتریل یان نیۆپرین بۆ زۆربەی ماددە کیمیاییەکان؛ جۆری دروست بەپێی SDS و خشتەی گونجان (Chemical Resistance Chart).","چاویلکەی سەلامەتی لەگەڵ پاراستنی لاتەنیشتەکان (Side Shields)، یان چاویلکەی داخراو (Goggles) بۆ مەترسیی پڕژان.","پاراستنی کۆئەندامی هەناسە: دەمامکی N95 تەنها تەنۆلکە وردەکان ڕادەگرێت و هیچ پاراستنێک لە هەڵم و گازە کیمیاییەکان نادات. بۆ هەڵم و گازەکان، دەمامکێکی فلتەردار (Respirator) بە فلتەری (Cartridges) گونجاو بۆ ئەو ماددەیە بەپێی SDS پێویستە؛ بۆ ماددە نەناسراوەکان، چڕیی بەرز یان کەمیی ئۆکسجین، تەنها ئامێری هەناسەدانی سەربەخۆ (SCBA).","کراسی تاقیگە: دژە-ئاگر (Flame-resistant) لە شوێنی ماددە ئاگرگرەکاندا.","پێڵاوی داخراو کە هەموو پێ بپارێزێت."]},{heading:"٦. هەڵگرتنی ماددە کیمیاییەکان (Chemical Storage)",body:"ڕێساکانی هەڵگرتنی سەلامەت:",points:["جیاکردنەوە: ترشەکان (ئەسید) دوور لە بنچینەکان (باز)، و ماددە ئۆکسیدکەرەکان دوور لە ماددە ئاگرگرەکان.","پلەی گەرما: ئەگەر ماددە ئاگرگرەکان پێویستیان بە ساردکردنەوە هەبوو، تەنها لە سەلاجەی تایبەتی دژە-تەقینەوەدا هەڵبگیرێن، نەک لە سەلاجەی ئاسایی.","قفڵکردن: ماددە ژەهراوییەکان لە دۆڵابی قفڵکراودا.","نیشانەکردن: هەموو شووشە و دەفرەکان بە ناو و هێماکانی GHS.","ڕەفەکانی خوارەوە: ماددە قورسەکان و دەفرە شووشەییەکان لە ڕەفە نزمەکاندا."]}],media:[{kind:"image",src:"media/images/uni_02_ghs_symbols.png",title:"هێماکانی GHS",description:"لیستی تەواوی هێما جیهانییەکان"},{kind:"video",src:"media/videos/uni_02_spill_cleanup.mp4",title:"پاککردنەوەی ڕژان",description:"بەکارهێنانی سندووقی ڕژان (Spill Kit)"},{kind:"image",src:"media/images/uni_02_nfpa704.png",title:"NFPA 704",description:"ڕوونکردنەوەی ڕەنگ و ژمارەکان"},{kind:"video",src:"media/videos/uni_02_ppe_demo.mp4",title:"لەبەرکردنی PPE",description:"ڕێگای دروستی لەبەرکردن و داکەندن"}],quiz:[{question:"لە NFPA 704 دا، ڕەنگی شین نیشانەی چییە؟",options:[{text:"ئاگر",correct:!1},{text:"کارلێککردن",correct:!1},{text:"تەندروستی",correct:!0},{text:"مەترسییە تایبەتەکان",correct:!1}],explanation:"شین نیشانەی مەترسییە تەندروستییەکانە (Health Hazard)."},{question:"کام بەشی SDS باسی فریاکەوتنی سەرەتایی دەکات؟",options:[{text:"بەشی ١",correct:!1},{text:"بەشی ٤",correct:!0},{text:"بەشی ٩",correct:!1},{text:"بەشی ١١",correct:!1}],explanation:"بەشی ٤ (Section 4) تایبەتە بە ڕێکارەکانی فریاکەوتنی سەرەتایی (First Aid Measures)."},{question:"پێش ئەوەی لە ڕژانێکی کیمیایی بچووک نزیک ببیتەوە، دەبێت چی بکەیت؟",options:[{text:"یەکسەر دەستکردن بە پاککردنەوە",correct:!1},{text:"ناسینەوەی ماددەکە لە ڕێگەی لەیبڵ یان SDS و لەبەرکردنی ئەو PPE یەی دیاری دەکات",correct:!0},{text:"بۆنکردنی ماددەکە بۆ زانینی جۆرەکەی",correct:!1},{text:"پاککردنەوەی بە دەستەسڕی کاغەز",correct:!1}],explanation:"سەرەتا لە دوورەوە ماددەکە بناسە و PPE ی گونجاو لەبەر بکە. ئەگەر ڕژانەکە گەورە، نەناسراو یان مەترسیدار بوو، دەربچۆ، دەرگاکە لە دوای خۆتەوە دابخە و پەیوەندی بکە بە ١١٥."},{question:"بۆ کاری گشتیی تاقیگە لەگەڵ زۆربەی ماددە کیمیاییەکاندا، کام دەستکێش باشترین هەڵبژاردنە؟",options:[{text:"لاتێکس",correct:!1},{text:"نایتریل",correct:!0},{text:"لۆکە",correct:!1},{text:"هیچ دەستکێشێک",correct:!1}],explanation:"دەستکێشی نایتریل بۆ زۆربەی ماددە کیمیاییەکان هەڵبژاردنێکی گشتیی باشە؛ بەڵام بۆ هەر ماددەیەکی تایبەت، جۆری دروست بەپێی SDS و خشتەی گونجان هەڵدەبژێردرێت."}]},{id:3,code:"ELEC-305",icon:"Zap",accent:"#ca8a04",title:"سەلامەتیی کارەبا و ڤۆڵتیەی بەرز",subtitle:"Electrical Safety, Arc Flash & High Voltage",summary:"شیکردنەوەی مەترسییەکانی کارەبا، کاریگەریی تەزوو لەسەر لەشی مرۆڤ، دیاردەی Arc Flash، ستانداردی LOTO، و یاسای Ohm بۆ پاراستن.",blocks:[{body:"کارەبا یەکێکە لە گەورەترین دەستکەوتەکانی مرۆڤایەتی، بەڵام لە هەمان کاتدا هێزێکی بێدەنگ و مەترسیدارە. هەموو ساڵێک لە سەرانسەری جیهاندا زۆر کەس بەهۆی شۆکی کارەباوە گیانیان لەدەست دەدەن یان بریندار دەبن. زۆربەی ئەم ڕووداوانە لە کارگەکان، پرۆژەکانی بیناسازی و تەنانەت لە ماڵەکانیشدا ڕوو دەدەن، بەهۆی کەمتەرخەمی یان نەزانینەوە."},{heading:"١. بنەما فیزیاییەکان و یاسای Ohm",body:"یاسای Ohm بنەمای سەرەکیی شیکردنەوەی کارەبایە:",points:["I = V / R (تەزوو = ڤۆڵتیە ÷ بەرگری).","ڤۆڵتیە: هێزی پاڵنانی ئەلیکترۆنەکان.","بەرگری: لەشی تەڕ = بەرگریی کەمتر = تەزوو و مەترسیی زیاتر.","ئەمپێر (تەزوو): ئەوەیە کە مرۆڤ دەکوژێت، نەک تەنها ڤۆڵتیە."]},{heading:"٢. کاریگەریی بایۆلۆجیی تەزوو",body:"کاریگەریی تەزوو لەسەر لەش (نزیکەیی، بۆ کارەبای AC ی ٥٠–٦٠ Hz):",points:["١ mA: هەستپێکردن.","١٠–٢٠ mA: سنووری بەردان (Let-go Threshold): مرۆڤ ناتوانێت دەستی لە سەرچاوەکە بەربدات.","٥٠–١٠٠ mA: ئەگەری لێدانی نائاسایی و ناڕێکی دڵ (Ventricular Fibrillation).","١٠٠+ mA: وەستانی دڵ و سووتانی ناوەکی بە ئەگەرێکی بەرزتر."]},{heading:"٣. دیاردەی Arc Flash",body:"تەقینەوەیەکی وزەیە لە نێوان گەیەنەرەکاندا:",points:["گەرما: دەتوانێت بگاتە نزیکەی ١٩٬٤٠٠ پلەی سیلیزی (نزیکەی چوار هێندە گەرمتر لە ڕووی خۆر).","Arc Blast: شەپۆلی پەستانی هەوا و پارچەی فڕیو.","تیشکدانەوە و ڕووناکیی توند: زیانی چاو، کوێربوونی کاتی یان هەمیشەیی.","هۆکارە سەرەکییەکانی برینداربوون: کارکردن لەسەر ئامێری بەستراو بە کارەباوە، کەرەستەی کەوتوو، و نەبوونی PPE ی گونجاو."]},{heading:"٤. ستانداردی LOTO (Lockout/Tagout)",body:"پرۆتۆکۆڵی سەلامەتی لە کاتی چاککردنەوەدا (بەپێی OSHA 1910.147):",points:["Lockout: قفڵکردنی سەرچاوەی وزە.","Tagout: کارتی ئاگادارکردنەوە (ناو، کات، هۆکار).","Zero Energy: دڵنیابوونەوە بە ئامێری پێوانەی ڤۆڵتیە (Voltmeter) کە هیچ وزەیەک نەماوە."]},{heading:"٥. کەرەستەکانی پاراستنی کەسی (Electrical PPE)",body:"کەرەستەکانی پاراستنی کەسی بۆ کاری کارەبا:",points:["دەستکێشی عازل (Class 0/1).","ڕووپۆشی دژە-کەوانەی کارەبا (Arc-Rated Face Shield).","جلوبەرگی دژە-کەوانەی کارەبا (Arc-Rated).","پێڵاوی عازل (EH Rated)."]},{heading:"٦. فریاکەوتنی سەرەتایی بۆ شۆکی کارەبا",body:"هەنگاوەکانی فریاکەوتن:",points:["سەرەتا سەرچاوەی کارەبا بپچڕێنە؛ تا کارەبا نەپچڕێنرێت، دەست لە کەسی بریندار مەدە.","پەیوەندی بکە بە ١٢٢ (ئەمبولانس)؛ ئەگەر وایەری کەوتوو یان ئاگر هەبوو، هەروەها پەیوەندی بکە بە ١١٥.","ئەگەر کەسەکە بێهۆش بوو و هەناسەی ئاسایی نەبوو، یەکسەر زیندووکردنەوەی دڵ و سییەکان (CPR) دەست پێ بکە و AED بەکاربهێنە.","سووتانەکان بە ئاوی ڕەوانی فێنک بۆ ماوەی ٢٠ خولەک سارد بکەرەوە؛ هەر کەسێک شۆکی کارەبای لێ درابێت پێویستە لەلایەن پزیشکەوە بپشکنرێت."]}],media:[{kind:"video",src:"media/videos/uni_03_loto_steps.mp4",title:"هەنگاوەکانی LOTO",description:"قفڵکردن و نیشانەکردن"},{kind:"image",src:"media/images/uni_03_arc_flash.png",title:"سنوورەکانی Arc Flash",description:"مەوداکانی سەلامەتی"},{kind:"video",src:"media/videos/uni_03_grounding.mp4",title:"Grounding",description:"گرنگیی وایەری زەوی"}],quiz:[{question:"کەمترین ڕێژەی تەزوو کە دەتوانێت ببێتە هۆی Ventricular Fibrillation چەندە؟",options:[{text:"١ mA",correct:!1},{text:"١٠ mA",correct:!1},{text:"٥٠–١٠٠ mA",correct:!0},{text:"٥٠٠٠ mA",correct:!1}],explanation:"٥٠–١٠٠ میلی ئەمپێر دەتوانێت ببێتە هۆی لێدانی نائاسایی و ناڕێکی دڵ."},{question:"ئامانجی LOTO چییە؟",options:[{text:"کەمکردنەوەی خەرجییەکان",correct:!1},{text:"بڕینی وزە و ڕێگرتن لە گەڕانەوەی",correct:!0},{text:"زیادکردنی ڤۆڵتیە",correct:!1},{text:"پاککردنەوە",correct:!1}],explanation:"LOTO دڵنیا دەکاتەوە کە لە کاتی چاککردنەوەدا هیچ وزەیەک لە ئامێرەکەدا نەماوە."},{question:"بەرگریی لەش چۆن دەگۆڕێت؟",options:[{text:"هەمیشە وەک خۆی دەمێنێتەوە",correct:!1},{text:"بە تەڕبوون زیاد دەبێت",correct:!1},{text:"بە تەڕبوون کەم دەبێتەوە",correct:!0},{text:"هیچ پەیوەندییەکی نییە",correct:!1}],explanation:"کاتێک پێست تەڕ دەبێت، بەرگری کەم دەبێتەوە و تەزوو و مەترسی زیاد دەبن."}]},{id:4,code:"MED-401",icon:"HeartPulse",accent:"#e11d48",title:"فریاکەوتنی سەرەتایی پێشکەوتوو و زیندووکردنەوەی دڵ و سییەکان (CPR)",subtitle:"Advanced First Aid, CPR & Trauma Management",summary:"پرۆتۆکۆڵی DRABCDE، زیندووکردنەوەی دڵ و سییەکان (CPR) بەپێی ڕێنماییەکانی AHA 2025، بەکارهێنانی ئامێری AED، ڕاگرتنی خوێنبەربوونی مەترسیدار (Stop the Bleed)، و پۆلێنکردنی بریندارەکان (Triage).",blocks:[{body:"فریاکەوتنی سەرەتایی تەنها کارێکی مرۆڤدۆستانە نییە، بەڵکو زانستێکی وردە کە لە نێوان ژیان و مردندا بڕیار دەدات. لە بواری تەنگانەدا، باسی «کاتژمێری زێڕین» (Golden Hour) و «دە خولەکە پلاتینییەکە» (Platinum Ten Minutes) دەکەین: تا بریندار زووتر بگاتە چارەسەر، ئەگەری ڕزگاربوونی زیاتر دەبێت. لە هەموو حاڵەتە پزیشکییەکاندا، پەیوەندی بکە بە ١٢٢ (ئەمبولانس)."},{heading:"١. پرۆتۆکۆڵی DRABCDE",body:"زنجیرەی سەرەکیی هەڵسەنگاندنی بریندار:",points:["D - Danger: پشکنینی مەترسی بۆ خۆت و بۆ بریندارەکە.","R - Response: ئاستی هۆشیاری (AVPU).","A - Airway: کردنەوەی ڕێڕەوی هەناسە بە Head Tilt یان Jaw Thrust.","B - Breathing: پشکنینی هەناسەدانی ئاسایی، نەک زیاتر لە ١٠ چرکە؛ ئەگەر کەسەکە بێهۆش بوو و هەناسەی ئاسایی نەبوو، یەکسەر CPR بە پەستانی سنگ دەست پێ بکە (ڕیزبەندیی C-A-B).","C - Circulation: پشکنینی خوێنبەربوونی مەترسیدار و نیشانەکانی شۆک (پشکنینی لێدانی دەماری Carotid بۆ کارمەندانی پزیشکی).","D - Disability: پشکنینی ئاستی هۆشیاری، چاوەکان و جووڵەی دەست و پێیەکان.","E - Exposure: پشکنینی گشتیی لەش و داپۆشین بۆ پاراستن لە سەرما."]},{heading:"٢. CPR بە کوالیتییەکی بەرز",body:"ڕێنماییەکانی AHA 2025:",points:["شوێن: نیوەی خوارەوەی ئێسکی سنگ.","قووڵی: ٥–٦ سم بۆ هەموو گەورەکان؛ نزیکەی ٥ سم بۆ منداڵان؛ نزیکەی ٤ سم بۆ ساوایان (یەک لەسەر سێی قووڵیی سنگ). بۆ ساوایان: هەردوو پەنجە گەورە لەگەڵ دەورەدانی سنگ، یان بنی یەک دەست؛ ڕێگای دوو پەنجە چیتر پێشنیار ناکرێت.","خێرایی: ١٠٠–١٢٠ پەستان لە خولەکێکدا.","Recoil: دوای هەر پەستانێک، ڕێگە بدە سنگ بە تەواوی بگەڕێتەوە شوێنی خۆی.","ڕێژە: ٣٠:٢ (پەستان:هەناسە)؛ بۆ منداڵ و ساوایان لەگەڵ دوو ڕزگارکەر ١٥:٢."]},{heading:"٣. بەکارهێنانی AED",body:"ئامێری دیفیبریلاتۆری ئۆتۆماتیکیی دەرەکی:",points:["ئامێرەکە بکەرەوە و گوێ لە ڕێنماییەکانی بگرە.","«Stand Clear»: هیچ کەسێک دەست لە بریندارەکە نەدات.","شۆکەکە بدە، و یەکسەر CPR دووبارە دەست پێ بکەرەوە."]},{heading:"٤. ڕاگرتنی خوێنبەربوونی مەترسیدار (Stop the Bleed)",body:"سەرەتا دڵنیا ببەوە لە سەلامەتیی شوێنەکە و پەیوەندی بکە بە ١٢٢، پاشان بەم ڕیزبەندییە:",points:["پەستانی ڕاستەوخۆ: بە هەردوو دەست پەستانێکی بەهێز و بەردەوام لەسەر برینەکە دابنێ. ئەگەر برینەکە قووڵ بوو، برینەکە بە گاز یان قوماشێکی پاک پڕ بکەرەوە (Wound Packing) و پەستانەکە بەردەوام بکە. ئەگەر پێچانەکە بە خوێن تەڕ بوو، لای مەبە؛ پێچانێکی تر بخەرە سەری.","تۆرنیکێت (Tourniquet): بۆ خوێنبەربوونی مەترسیداری دەست و پێیەکان زوو بەکاری بهێنە، ٥–٧ سم لە سەرووی برینەکەوە (نەک لەسەر جومگە)؛ ئەوەندە توندی بکە تا خوێنەکە دەوەستێت، کاتی دانانەکەی بنووسە، و هەرگیز شلی مەکەرەوە.","شۆک: بریندارەکە لەسەر پشت پاڵی بخە، بە گەرمی دایپۆشە، و هیچ خواردن یان خواردنەوەیەکی پێ مەدە؛ لە حاڵەتەکانی برینداربووندا (Trauma) پێیەکانی بەرز مەکەرەوە."]},{heading:"٥. START Triage",body:"پۆلێنکردنی بریندارەکان لەو کارەساتانەی ژمارەیەکی زۆری برینداریان تێدایە:",points:["سوور (Immediate): ژیان لە مەترسیدایە - یەکەم پێشینە.","زەرد (Delayed): برینی سەخت بەڵام دەتوانێت کەمێک چاوەڕێ بکات.","سەوز (Minor): برینی سووک - دەتوانێت بە پێی خۆی بڕوات.","ڕەش (Expectant/Deceased): تەنانەت دوای کردنەوەی ڕێڕەوی هەناسەش هەناسە نادات."]}],media:[{kind:"video",src:"media/videos/uni_04_cpr_full.mp4",title:"CPR",description:"ڕێنماییەکانی AHA 2025"},{kind:"image",src:"media/images/uni_04_jaw_thrust.png",title:"Jaw Thrust",description:"بۆ گومانی برینداربوونی مل و بڕبڕەی پشت"},{kind:"video",src:"media/videos/uni_04_triage_sim.mp4",title:"Triage",description:"پۆلێنکردنی بریندارەکان"},{kind:"image",src:"media/images/uni_04_tourniquet.png",title:"تۆرنیکێت",description:"شوێن و شێوازی دانان (٥–٧ سم لە سەرووی برینەکەوە)"}],quiz:[{question:"لە کاتی گومانی برینداربوونی ملدا، چۆن ڕێڕەوی هەناسە دەکەیتەوە؟",options:[{text:"Head Tilt",correct:!1},{text:"Jaw Thrust",correct:!0},{text:"جووڵاندنی سەر",correct:!1},{text:"هیچ شتێک",correct:!1}],explanation:"Jaw Thrust ڕێڕەوی هەناسە دەکاتەوە بەبێ ئەوەی مل بجووڵێت."},{question:"ڕێژەی پەستان بەرامبەر هەناسە لە CPR ی گەورەکاندا چەندە؟",options:[{text:"١٥:٢",correct:!1},{text:"٣٠:٢",correct:!0},{text:"١٠٠:٥",correct:!1},{text:"٣٠:١",correct:!1}],explanation:"ستاندارد بۆ گەورەکان: ٣٠ پەستان بەرامبەر ٢ هەناسە (١٥:٢ بۆ منداڵ و ساوایان لەگەڵ دوو ڕزگارکەر)."},{question:"لە START Triage دا، ئەو کەسەی تەنانەت دوای کردنەوەی ڕێڕەوی هەناسەش هەناسە نادات، کام ڕەنگ وەردەگرێت؟",options:[{text:"سوور",correct:!1},{text:"زەرد",correct:!1},{text:"ڕەش",correct:!0},{text:"سەوز",correct:!1}],explanation:"ڕەش (Expectant/Deceased): ئەگەر تەنانەت دوای کردنەوەی ڕێڕەوی هەناسەش هەناسەی نەدا."},{question:"خێرایی پەستانی سنگ لە CPR دا چەندە؟",options:[{text:"٦٠–٨٠",correct:!1},{text:"٨٠–١٠٠",correct:!1},{text:"١٠٠–١٢٠",correct:!0},{text:"١٤٠–١٦٠",correct:!1}],explanation:"١٠٠–١٢٠ پەستان لە خولەکێکدا."}]},{id:5,code:"STRUC-500",icon:"Building2",accent:"#0891b2",title:"ئەندازیاریی سەلامەتیی بیناکان",subtitle:"Building Safety, Fire Codes & Life Safety Systems",summary:"کۆدە ئەندازیارییەکان (IBC/NFPA)، سیستەمەکانی ئاگادارکردنەوە و کوژاندنەوەی ئاگر، دەرگا دژە-ئاگرەکان، و دیزاینی ڕێڕەوەکانی دەرچوونی تەنگانە.",blocks:[{body:"بینا تەنها شوێنی ژیان و کار نییە، بەڵکو پێویستە وەک «سیستەمێکی پاراستنی ژیان» دیزاین بکرێت. زۆرێک لە کارەساتەکانی ئاگر نیشان دەدەن کە کەموکوڕییە ئەندازیارییەکان، وەک دەرچوونی داخراو یان نەبوونی دابەشکردنی ئاگر، ڕێگری لە دەرچوونی خێرا دەکەن و ژمارەی قوربانییان زیاد دەکەن. بۆیە دیزاینێکی دروست کە سیستەمەکانی ئاگادارکردنەوە، کوژاندنەوەی ئۆتۆماتیکیی ئاگر و ماددەی دژە-ئاگر لەخۆ بگرێت، دەتوانێت لە نێوان ژیان و مردندا جیاوازی دروست بکات. لەم مۆدیوولەدا، باسی کۆدە نێودەوڵەتییەکانی وەک NFPA 101 و IBC دەکەین."},{heading:"١. کۆدەکانی بیناسازی و سەلامەتیی جیهانی",body:"کۆد (Code) زنجیرەیەک ڕێسای تەکنیکییە کە ستانداردەکانی دیزاین و دروستکردن دیاری دەکات. دوو کۆدی سەرەکی لە زۆر وڵاتدا پەیڕەو دەکرێن:",points:["IBC (International Building Code): کۆدی نێودەوڵەتیی بیناسازییە کە لایەنە پێکهاتەییەکان (ستراکچەر)، پاراستن لە ئاگر و سەلامەتیی ژیان لەخۆ دەگرێت (کارەبا و میکانیک بە کۆدی جیاوازی وەک NEC و IMC ڕێک دەخرێن). ئەم کۆدە دیاری دەکات کە ستوون و دیوارەکانی بینا پێویستە چەند کاتژمێر بەرگری لە بەرامبەر ئاگردا بکەن (Fire-Resistance Rating).","NFPA 101 (Life Safety Code): تایبەتە بە پاراستنی ژیانی مرۆڤ. ئەم ستانداردە ڕێنمایی لەسەر پانیی دەرگاکان، درێژیی ڕاڕەوەکان و ڕووناکیی تەنگانە (Emergency Lighting) دەدات.","جۆرەکانی دروستکردن (Construction Types): IBC بیناکان دابەش دەکات بۆ پێنج جۆر. جۆری یەکەم (Type I) کە لە کۆنکریت و ئاسنی پارێزراو دروست کراوە، بەرزترین بەرگریی هەیە، و جۆری پێنجەم (Type V) کە لە دار دروست کراوە، کەمترین بەرگریی هەیە.","باری نیشتەجێبوون (Occupant Load): هەژمارکردنی زۆرترین ژمارەی ئەو کەسانەی دەتوانن لە یەک کاتدا لە بیناکەدا بن، بۆ ئەوەی بزانرێت چەند دەرچوون (Exits) و چەند پانی پێویستە."]},{heading:"٢. دابەشکردنی ئاگر و دیوارە دژە-ئاگرەکان (Compartmentation)",body:"ئامانجی ئەم ستراتیژە ئەوەیە کە بینا دابەش بکرێت بۆ چەند بەشێکی جیاواز (Fire Compartments) بۆ ئەوەی ئاگر نەتوانێت بە ئاسانی لە بەشێکەوە بچێتە بەشێکی تر:",points:["Fire Walls: دیواری تایبەتن کە بەپێی کاتژمێر هەڵدەسەنگێنرێن (بە گشتی ٢ تا ٤ کاتژمێر). ئەم دیوارانە ڕێگە نادەن گەرما و گازە ئاگرگرەکان لە نێوان بەشەکانی بینادا بجووڵێن.","Fire Doors: دەرگای دژە-ئاگرن کە پێویستە خۆکار دابخرێن (Self-closing) و هەرگیز بە بەربەستێک کراوە نەهێڵرێنەوە. ئەم دەرگایانە ڕێگری لە چوونی دووکەڵ بۆ ناو پلیکانەکان (Stairwells) دەکەن.","Fire Dampers: دەریچەی ئۆتۆماتیکین لە ناو بۆرییەکانی گۆڕینی هەوادا (HVAC)، کە لە کاتی بەرزبوونەوەی گەرمادا خۆکار دادەخرێن بۆ ئەوەی ئاگر لە ڕێگەی بۆرییەکانەوە بڵاو نەبێتەوە.","Firestopping: داخستنی هەموو کون و درزەکانی ناو دیوار و زەوییەکان، کە کێبڵی کارەبا یان بۆری پێیاندا تێدەپەڕن، بە ماددەی دژە-ئاگر."]},{heading:"٣. سیستەمەکانی کوژاندنەوەی ئۆتۆماتیکیی ئاگر (Suppression Systems)",body:"ئەم سیستەمانە بەبێ دەستێوەردانی مرۆڤ کار دەکەن و دەبنە هۆی کۆنتڕۆڵکردنی خێرای ئاگر:",points:["Automatic Sprinklers: یەکێکە لە کاریگەرترین سیستەمەکان؛ بەپێی ڕاپۆرتی NFPA (U.S. Experience with Sprinklers)، لەو ماڵانەی Sprinkler تێیاندا هەیە ڕێژەی مردن لە ئاگرەکاندا نزیکەی ٨٩٪ کەمتر بووە. تەنها ئەو سەرانە (Heads) کار دەکەن کە گەرمایان پێ گەیشتووە.","Sprinkler Bulbs: ڕەنگی شلەمەنیی ناو بڵبە شووشەییەکە پلەی گەرمای شکانی دیاری دەکات (سوور = ٦٨ پلەی سیلیزی، کە باوترین جۆرە).","Dry Pipe و Wet Pipe: لە شوێنە زۆر ساردەکاندا (وەک کۆگا ساردکراوەکان) سیستەمی Dry Pipe بەکاردەهێنرێت بۆ ئەوەی ئاو لە ناو بۆرییەکاندا نەبەستێت.","Clean Agent Systems: بەکارهێنانی گازی وەک FM-200 (HFC-227ea) یان FK-5-1-12 (ناوی بازرگانی Novec 1230) لە ژووری سێرڤەر و مۆزەخانەکاندا، بۆ ئەوەی ئاو زیان بە ئامێر و بەڵگەنامەکان نەگەیەنێت."]},{heading:"٤. سیستەمەکانی ئاگادارکردنەوە (Fire Alarm Systems)",body:"ئەمە مێشکی سەلامەتیی بینایە، و ئەرکەکەی دۆزینەوەی ئاگر و ئاگادارکردنەوەی خەڵکە (NFPA 72):",points:["FACP (Control Panel): ناوەندی کۆنتڕۆڵە کە ئاماژەکان (Signals) لە هەستەوەرەکانەوە وەردەگرێت و فەرمانی لێدانی زەنگەکان و ئاگادارکردنەوەی ناوەندی کوژاندنەوەی ئاگر دەدات.","Smoke Detectors: دوو جۆری سەرەکی هەن: Photoelectric کە بۆ ئاگری هێواش و دووکەڵاوی باشترە، و Ionization کە بۆ ئاگری خێرا و گڕدار باشترە.","Notification: بەکارهێنانی زەنگی دەنگبەرز (Horns) لەگەڵ ڕووناکیی فلاشدار (Strobes) بۆ ئەو کەسانەی کێشەی بیستنیان هەیە.","Emergency Power: لە کاتی پچڕانی کارەبادا، سیستەمەکە پێویستە لەسەر پاتری کار بکات: ٢٤ کاتژمێر لە دۆخی ئامادەباشیدا و پاشان ٥ خولەک لە دۆخی زەنگلێداندا (NFPA 72)."]},{heading:"٥. ڕێڕەوەکانی دەرچوونی تەنگانە (Means of Egress)",body:"دیزاینکردنی ڕێگای دەرچوون لە هەر خاڵێکی بیناوە بۆ دەرەوە پێویستی بە پەیڕەوکردنی ئەم خاڵانە هەیە:",points:["Exit Access: ڕێگا لە ناو ژوورەوە تا دەرگای دەرچوون. پێویستە هیچ ڕێگرییەک (کورسی، مێز، کەلوپەل) لەم ڕێڕەوانەدا نەبێت.","Exit Capacity: پانیی دەرگا و پلیکانەکان پێویستە بەپێی ژمارەی خەڵک بێت. بە گشتی پانیی ڕاڕەوەکان لانیکەم ١.١٢ مەترە (٤٤ ئینج)، و ٠.٩١ مەتر (٣٦ ئینج) تەنها بۆ ئەو شوێنانەیە کە کەمتر لە ٥٠ کەسیان تێدایە (IBC).","Direction of Travel: ئەو دەرگایانەی دەرچوون کە ٥٠ کەس یان زیاتر بەکاریان دەهێنن (و شوێنە زۆر مەترسیدارەکان) پێویستە بەرەو ئاراستەی دەرچوون (Outward) بکرێنەوە بۆ ئەوەی پاڵەپەستۆی خەڵک دەرگاکە دانەخات. هەموو دەرگاکانی دەرچوون پێویستە لە ناوەوە بەبێ کلیل بکرێنەوە.","Exit Signs: نیشانەی ڕووناککراوەی دەرچوون کە لە تاریکیشدا دیار بن، و پێویستە لە هەموو ئاراستەکانەوە ببینرێن.","Dead-end Corridors: درێژیی ڕاڕەوە داخراوەکان (کە ناگەنە هیچ دەرچوونێک) بە گشتی نابێت لە ٦ مەتر (٢٠ پێ) زیاتر بێت؛ لە هەندێک بینای خاوەن Sprinkler دەکرێت زیاتر بێت."]},{heading:"٦. سەلامەتی لە بینا بەرزەکاندا (High-Rise Safety)",body:"ئەو بینایانەی نهۆمی نیشتەجێبوونیان لە ٢٣ مەتر (٧٥ پێ) بەرزترە، مەترسیی تایبەتیان هەیە، بۆیە پێویستیان بەم سیستەمانە هەیە:",points:["Smoke Control: سیستەمی پەستانی هەوا (Pressurization) لە ناو پلیکانەکاندا، بۆ ئەوەی دووکەڵ نەچێتە ژوورەوە و خەڵک نەخنکێن.","Fire Command Center: ژوورێکی تایبەت لە نهۆمی سەر زەوی کە تیمەکانی کوژاندنەوەی ئاگر بۆ کۆنتڕۆڵکردنی سیستەمەکانی هەموو بیناکە بەکاری دەهێنن.","Fire Service Access Elevator: ئاسانسۆری تایبەت کە لە کاتی تەنگانەدا تەنها ئاگرکوژەکان دەتوانن بەکاری بهێنن.","Area of Refuge: شوێنی پارێزراو لە نهۆمە بەرزەکاندا بۆ ئەو کەسانەی پێداویستیی تایبەتیان هەیە و ناتوانن بە پلیکانەدا دابەزن."]}],media:[{kind:"video",src:"media/videos/uni_05_sprinkler_test.mp4",title:"تاقیکردنەوەی Sprinkler",description:"چۆنیەتیی شکانی بڵبە شووشەییەکە لە ژێر کاریگەریی گەرمادا"},{kind:"image",src:"media/images/uni_05_egress_plan.png",title:"پلانی دەرچوون",description:"دیزاینی ستاندارد بۆ ڕێڕەوەکانی دەرچوون بەپێی NFPA"},{kind:"video",src:"media/videos/uni_05_fire_damper.mp4",title:"کارکردنی Fire Damper",description:"ڕێگرتن لە بڵاوبوونەوەی ئاگر لە ناو بۆرییەکانی گۆڕینی هەوادا"}],quiz:[{question:"بەپێی کۆدە ئەندازیارییەکان، دەرگاکانی دەرچوونی تەنگانە (Exit Doors) لە شوێنە قەرەباڵغەکاندا پێویستە بەرەو کام لا بکرێنەوە؟",options:[{text:"بەرەو ناوەوە",correct:!1},{text:"بەرەو دەرەوە (ئاراستەی دەرچوون)",correct:!0},{text:"بە شێوەی خلیسکێن (Sliding)",correct:!1},{text:"هیچ جیاوازییەکی نییە",correct:!1}],explanation:"پێویستە بەرەو دەرەوە (ئاراستەی دەرچوون) بکرێنەوە بۆ ئەوەی ئەگەر پاڵەپەستۆی خەڵک هەبوو، دەرگاکە بە ئاسانی بکرێتەوە و نەبێتە ڕێگری. دەرگا پێویستە لە ناوەوە بەبێ کلیل بکرێتەوە."},{question:"ئامانجی سەرەکیی سیستەمی Pressurization لە ناو پلیکانەکاندا (Stairwells) چییە؟",options:[{text:"ساردکردنەوەی بیناکە",correct:!1},{text:"ڕێگرتن لە چوونی دووکەڵ بۆ ناو ڕێگای دەرچوون",correct:!0},{text:"زیادکردنی ڕووناکی",correct:!1},{text:"کوژاندنەوەی ئاگر بە هەوا",correct:!1}],explanation:"ئەم سیستەمە لە ناو پلیکانەکاندا پەستانێکی بەرزتری هەوا دروست دەکات بۆ ئەوەی دووکەڵ نەتوانێت بچێتە ژوورەوە، و بەم شێوەیە ڕێگای دەرچوون پاک دەمێنێتەوە."},{question:"ڕەنگی سوور لە بڵبە شووشەییەکەی Sprinkler دا نیشانەی چییە؟",options:[{text:"پلەی گەرمای ٦٨ پلەی سیلیزی",correct:!0},{text:"پلەی گەرمای ١٤١ پلەی سیلیزی",correct:!1},{text:"تەنها بۆ جوانییە",correct:!1},{text:"نیشانەی بوونی گازە",correct:!1}],explanation:"ڕەنگی سوور باوترین جۆرە و لە پلەی ٦٨ پلەی سیلیزیدا دەشکێت و ئاو دەپڕژێنێت."},{question:"بەپێی IBC، کام جۆری دروستکردن (Construction Type) بەرزترین بەرگریی دژی ئاگری هەیە؟",options:[{text:"Type V (Wood Frame)",correct:!1},{text:"Type III (Ordinary)",correct:!1},{text:"Type I (Fire-Resistive)",correct:!0},{text:"Type IV (Heavy Timber)",correct:!1}],explanation:"Type I لە کۆنکریت و ئاسنی پارێزراو دروست دەکرێت و بە شێوەیەک دیزاین دەکرێت کە چەند کاتژمێر لە بەرامبەر ئاگرێکی تونددا بەرگری بکات بەبێ ئەوەی بڕووخێت."}]},{id:6,code:"LAW-600",icon:"Scale",accent:"#475569",title:"یاسا و بەرپرسیارێتیی یاسایی",subtitle:"Legal Responsibilities, Liability & Compliance",summary:"شیکردنەوەی ئەرک و مافە یاساییەکان، سزاکانی کەمتەرخەمی، یاسای بەرگریی شارستانی لە عێراق، و بەرپرسیارێتیی دامەزراوەکان لە بەرامبەر کارەساتەکاندا.",blocks:[{body:`سەلامەتی تەنها ئەرکێکی ئەخلاقی نییە، بەڵکو ئەرکێکی یاسایی گرنگە. لە زۆربەی وڵاتاندا، یاسا بە ڕوونی دیاری دەکات کە خاوەنی بیناکان، بەڕێوەبەران، ئەندازیاران و تەنانەت کارمەندانی ئاساییش بەرپرسیارێتیی یاساییان هەیە بۆ دڵنیابوونەوە لە بوونی ژینگەیەکی سەلامەت. ئەگەر کەمتەرخەمی ڕوو بدات و ببێتە هۆی زیان بە کەسێک، دەکرێت ببێتە هۆی سزای یاسایی گەورە (مەدەنی و تاوانکاری)، لە قەرەبووکردنەوەی داراییەوە تا زیندانیکردن.

لەم مۆدیوولەدا، باسی بنەما یاساییەکانی سەلامەتی دەکەین، یاسای بەرگریی شارستانیی عێراق دەناسین، و تێدەگەین کە مرۆڤ چۆن دەتوانێت لە ڕێگەی پەیڕەوکردنی ستانداردەکانەوە خۆی و دامەزراوەکەی لە داواکارییە یاساییەکان بپارێزێت. تێبینی: ئەم مۆدیوولە ڕاوێژکاریی یاسایی نییە؛ بۆ هەر پرسێکی یاسایی بگەڕێوە بۆ نووسینگەی یاسایی بەڕێوەبەرایەتیی بەرگریی شارستانی.`},{heading:"١. ئەرکی چاودێری (Duty of Care)",body:"بنەمای «ئەرکی چاودێری» (Duty of Care) یەکێکە لە کۆڵەکە سەرەکییەکانی یاساکانی بەرپرسیارێتی. بەپێی ئەم بنەمایە، هەر کەسێک یان لایەنێک کە کۆنتڕۆڵی شوێنێک یان چالاکییەکی هەبێت، بەرپرسە لە پاراستنی سەلامەتیی ئەو کەسانەی دێنە ئەو شوێنە یان بەشداری لەو چالاکییەدا دەکەن:",points:["خاوەنی بیناکان: بەرپرسن لە دابینکردنی سیستەمەکانی کوژاندنەوەی ئاگر و ئاگادارکردنەوە، و دیاریکردنی ڕێڕەوەکانی دەرچوونی تەنگانە.","بەڕێوەبەران و سەرپەرشتیاران: پێویستە ڕاهێنانی سەلامەتی بۆ کارمەندان دابین بکەن و دڵنیا ببنەوە کە کەرەستەکانی پاراستنی کەسی (PPE) بە دروستی بەکاردەهێنرێن.","ئەندازیاران و تەکنیسیەنان: بەرپرسن لە دیزاینی سەلامەت و ئەنجامدانی پشکنینی خولی (Inspections) بۆ هەموو ئامێرەکان بەپێی کۆد و ستانداردە پەسەندکراوەکان.","مەرجەکانی ئەرک: بۆ ئەوەی ئەم ئەرکە لەسەر تۆ بچەسپێنرێت، بە گشتی سێ خاڵ پێویستن: ١. مەترسییەکە پێشبینیکراو بێت؛ ٢. پەیوەندییەکی نزیک لە نێوان تۆ و کەسی زیانلێکەوتوودا هەبێت؛ ٣. سەپاندنی ئەم ئەرکە بەسەر تۆدا دادپەروەرانە و گونجاو بێت (Fair, Just and Reasonable)."]},{heading:"٢. کەمتەرخەمی و پێشێلکردنی یاسا (Negligence)",body:"کەمتەرخەمی ئەو حاڵەتەیە کە تێیدا کەسێک ئەرکی یاسایی خۆی بۆ پاراستن جێبەجێ ناکات و بەهۆیەوە کەسێکی تر زیان دەبینێت. بەپێی یاسای هاوبەش (Common Law)، بۆ سەلماندنی کەمتەرخەمی لە دادگادا، چوار توخم پێویستن. لە یاسای مەدەنیی عێراقیشدا هەمان بنەما بە سێ توخم دیاری دەکرێت: هەڵە (تەعەدی)، زیان، و پەیوەندیی هۆکاری لە نێوانیاندا:",points:["١. بوونی ئەرک (Duty): پێویستە بسەلمێنرێت کە تۆ ئەرکێکی یاساییت بەرامبەر بەو کەسە هەبووە.","٢. پێشێلکردنی ئەرک (Breach): کاری پێویستت ئەنجام نەداوە (بۆ نموونە: پشکنینی ئاگرکوژێنەرەوەکانت نەکردووە).","٣. زیان (Harm/Damage): پێویستە زیانێکی ڕاستەقینە ڕووی دابێت (جەستەیی، دارایی یان دەروونی).","٤. پەیوەندیی هۆکاری (Causation): پێویستە پێشێلکردنی ئەرکەکەت ڕاستەوخۆ ببێتە هۆی ئەو زیانە (بۆ نموونە: ئەگەر سیستەمی ئاگادارکردنەوەکەت چاک کردبایە، بریندارەکە دەیتوانی دەربچێت).","بەرگریی یاسایی: کەسی تۆمەتبار دەتوانێت بەرگری لە خۆی بکات ئەگەر بیسەلمێنێت کە زیانلێکەوتوو خۆی مەترسییەکەی قبووڵ کردبوو (Assumption of Risk)، یان کە زیانەکە لە هۆکارێکی چاوەڕواننەکراوی دەرەوەی دەسەڵاتی مرۆڤەوە پەیدا بووە (Force Majeure)."]},{heading:"٣. یاسای بەرگریی شارستانی لە عێراق و هەرێمی کوردستان",body:"سیستەمی یاسایی سەلامەتی بە چەند یاسا و ڕێنماییەکی فەرمی ڕێک دەخرێت:",points:["یاسای بەرگریی شارستانیی عێراقی ژمارە (٤٤)ی ساڵی ٢٠١٣: یاسای سەرەکیی بەرگریی شارستانییە لە عێراق و جێگەی یاسا کۆنەکەی ژمارە (٦٤)ی ساڵی ١٩٧٨ی گرتووەتەوە. ئەم یاسایە ئەرکی پشکنینی شوێنەکان و چاودێریکردنی پەیڕەوکردنی ڕێکارەکانی سەلامەتی دەداتە بەڕێوەبەرایەتیی گشتیی بەرگریی شارستانی. جێبەجێکردنی لە هەرێمی کوردستان پێویستە لەگەڵ نووسینگەی یاسایی بەڕێوەبەرایەتییەکەدا پشتڕاست بکرێتەوە.","ڕەزامەندیی نەخشەی بیناکان: بەپێی یاسا، شارەوانی نەخشەی بیناکان بۆ بەرگریی شارستانی دەنێرێت بۆ ئەوەی ڕێکارەکانی پێشگرتن و کوژاندنەوەی ئاگر پێش مۆڵەتی بیناسازی بپشکنرێن.","پشکنین و سزا: بەڕێوەبەرایەتیی بەرگریی شارستانیی دهۆک پشکنین بۆ پرۆژە نیشتەجێبوون و بازرگانییەکان دەکات؛ سەرپێچی دەتوانێت ببێتە هۆی داخستنی شوێنەکە و سزای دارایی یان زیندانی بەپێی یاسا.","مۆڵەتی سەلامەتی: بەپێی یاسا، پێش پێدانی مۆڵەتی چالاکیی بازرگانی یان پیشەسازی (بە تایبەتی هەڵگرتن و بەکارهێنانی ماددە مەترسیدارەکان)، ڕەزامەندیی بەرگریی شارستانی پێویستە."]},{heading:"٤. بەرپرسیارێتیی یاسایی دامەزراوەکان (Corporate Liability)",body:"کۆمپانیا وەک «کەسایەتییەکی یاسایی» بەرپرسە لە بەرامبەر ئەو ڕووداوانەی لە پرۆژەکانیدا ڕوو دەدەن:",points:["بەرپرسیارێتی لە جێگەی کەسێکی تر (Vicarious Liability): کۆمپانیا بەرپرسە لە هەڵەکانی کارمەندەکانی ئەگەر لە کاتی دەوام و لە ناو کاری فەرمیدا بن.","بەرپرسیارێتیی ڕاستەوخۆ: ئەگەر کۆمپانیا ڕاهێنانی پێویستی نەدابێتە کارمەندان یان ئامێری کۆن و ناسەلامەتی بەکارهێنابێت، بە شێوەیەکی ڕاستەوخۆ تۆمەتبار دەبێت.","زیانە داراییەکان: جگە لە قەرەبووکردنەوەی زیانلێکەوتووان، کۆمپانیا تووشی زیانی ناوبانگ (Reputation) و بەرزبوونەوەی نرخی بیمە (Insurance) دەبێت."]},{heading:"٥. ستراتیژییەکانی پاراستنی یاسایی (Protection Strategies)",body:"بۆ پاراستنی ژیان و پاراستنی یاسایی، پێویستە ئەندازیاران و بەڕێوەبەران ئەم خاڵانە جێبەجێ بکەن:",points:["تۆمارکردن (Documentation): ڕێسای زێڕین دەڵێت: «ئەگەر نەنووسرابێت، واتە ڕووی نەداوە». هەموو پشکنین، چاککردنەوە و ڕاهێنانەکان بە بەروار و واژۆ تۆمار بکە.","ڕاهێنانی بەردەوام: دڵنیا ببەوە کە هەموو کارمەندان جۆرەکانی ئاگرکوژێنەرەوە دەناسن و پرۆتۆکۆڵی دەرچوون دەزانن.","پشکنینی ناوخۆیی: پێش هاتنی تیمە حکومییەکان، خۆت پشکنینی خولی ئەنجام بدە بۆ دۆزینەوەی کەموکوڕییەکانی سەلامەتی.","گرێبەستی فەرمی: لە نێوان خاوەن و بەڵێندەراندا، پێویستە بەرپرسیارێتیی هەر لایەنێک لەسەر بابەتی سەلامەتی بە ڕوونی نووسرابێت."]},{heading:"٦. ئەخلاق و بەرپرسیارێتیی پیشەیی",body:"جگە لە یاسا، ئەندازیار ئەرکێکی ئەخلاقیی هەیە کە نابێت لەبیر بکرێت:",points:["ئەخلاقی ئەندازیاری: پاراستنی ژیانی مرۆڤەکان لە پێش قازانجی ماددییەوەیە. هەرگیز ئەو بڕیارانە قبووڵ مەکە کە سەلامەتی دەخەنە مەترسییەوە، تەنانەت ئەگەر لەلایەن بەڕێوەبەرایەتییەوە فشارت لەسەر بێت.","ڕاپۆرتکردن: ئەرکی ئەخلاقیی تۆیە کە هەر مەترسییەکی هەبوو بە ڕوونی ڕاپۆرت بکەیت پێش ئەوەی کارەسات ڕوو بدات."]}],media:[{kind:"image",src:"media/images/uni_06_negligence_chart.png",title:"بازنەی کەمتەرخەمی",description:"چوار توخمە یاساییەکە بۆ سەلماندنی کەمتەرخەمی لە دادگادا"},{kind:"video",src:"media/videos/uni_06_legal_brief.mp4",title:"بەرپرسیارێتیی یاسایی",description:"شیکردنەوەی کەیسێکی ڕاستەقینەی کارەساتێکی ئاگر بەپێی یاساکانی عێراق"},{kind:"image",src:"media/images/uni_06_documentation_log.png",title:"نموونەی تۆمارکردن",description:"چۆنیەتیی تۆمارکردنی پشکنینەکانی سەلامەتی بۆ پاراستنی یاسایی"}],quiz:[{question:"کام لەم توخمانە مەرج «نییە» بۆ سەلماندنی کەمتەرخەمی (Negligence) لە دادگادا؟",options:[{text:"بوونی ئەرک (Duty)",correct:!1},{text:"نیازی خراپ (Criminal Intent)",correct:!0},{text:"زیان (Harm)",correct:!1},{text:"پەیوەندیی هۆکاری (Causation)",correct:!1}],explanation:"کەمتەرخەمی (Negligence) پێویستی بە نیازی خراپ نییە؛ تەنانەت ئەگەر بە ئەنقەست زیانت نەگەیاندبێت، بەڵام ئەرکی خۆتت بۆ پاراستن جێبەجێ نەکردبێت، لە ڕووی یاساییەوە بەرپرسیت."},{question:"مەبەست لە «Vicarious Liability» چییە؟",options:[{text:"بەرپرسیارێتیی کەسیی کارمەند",correct:!1},{text:"بەرپرسیارێتیی دامەزراوە لەسەر کارەکانی کارمەندەکانی",correct:!0},{text:"یاسای کوژاندنەوەی ئاگر",correct:!1},{text:"قەرەبووکردنەوەی ژینگە",correct:!1}],explanation:"ئەم زاراوەیە نیشان دەدات کە دامەزراوە یان کۆمپانیا بەرپرسە لە کار و هەڵەکانی کارمەندەکانی لە کاتی جێبەجێکردنی ئەرکەکانیاندا."},{question:"لە عێراق، کام یاسا بەرگریی شارستانی و ڕێکارەکانی سەلامەتیی دامەزراوە و بیناکان ڕێک دەخات؟",options:[{text:"یاسای ژمارە ٦٤ی ١٩٧٨",correct:!1},{text:"یاسای بەرگریی شارستانی ژمارە ٤٤ی ٢٠١٣",correct:!0},{text:"یاسای ژمارە ٧ی ٢٠٠٥",correct:!1},{text:"یاسای هاتوچۆ",correct:!1}],explanation:"یاسای بەرگریی شارستانی ژمارە ٤٤ی ساڵی ٢٠١٣ یاسای سەرەکیی بەرگریی شارستانییە لە عێراق؛ یاسای ژمارە ٦٤ی ١٩٧٨ بەم یاسایە هەڵوەشێنراوەتەوە. جێبەجێکردنی لە هەرێمی کوردستان لەگەڵ نووسینگەی یاسایی بەڕێوەبەرایەتییەکەدا پشتڕاست بکەرەوە."},{question:"ڕێسای زێڕین لە پاراستنی یاساییدا دەڵێت: «ئەگەر نەنووسرابێت...»؟",options:[{text:"واتە گرنگ نییە",correct:!1},{text:"واتە دواتر دەکرێت",correct:!1},{text:"واتە بە ڕاستی ڕووی نەداوە",correct:!0},{text:"واتە یاساییە",correct:!1}],explanation:"لە دادگادا، تۆمارکردن و نووسین بەهێزترین بەڵگەن؛ هەر کارێک تۆمار نەکرابێت، وا هەژمار دەکرێت کە نەکراوە."}]},{id:7,code:"PSYCH-700",icon:"BrainCircuit",accent:"#0d9488",title:"دەروونناسیی کارەساتەکان و ڕەفتاری مرۆڤ",subtitle:"Disaster Psychology, Crowd Dynamics & Crisis Leadership",summary:"شیکردنەوەی کاردانەوەی بایۆلۆجی و دەروونیی مرۆڤ لە کاتی کارەساتەکاندا، بەڕێوەبردنی قەرەباڵغی، و بنەماکانی سەرکردایەتیی تەنگانە.",blocks:[{body:"لە کاتی کارەساتە گەورەکاندا، چ ئاگر بێت، بوومەلەرزە یان تەقینەوە، ڕەفتاری مرۆڤ خۆی دەتوانێت ببێتە هۆکارێکی سەرەکیی قوربانییەکان: دوودڵی، قەرەباڵغی لەسەر یەک دەرگا، و پاڵەپەستۆی خەڵک لەسەر دەرچوونەکان. بۆ نموونە، لە ئاگرەکەی یانەی «The Station» لە ئەمریکا (٢٠٠٣)، ١٠٠ کەس گیانیان لەدەستدا؛ بەپێی لێکۆڵینەوەی NIST، زۆربەی خەڵک هەوڵیان دا لە ڕێگەی ئەو دەرگا سەرەکییەوە دەربچن کە پێیدا هاتبوونە ژوورەوە، و لەوێ قەرەباڵغی و گیرانی دەرگاکە ڕوویدا، هەرچەندە دەرچوونی تریش هەبوون. تێگەیشتن لە دەروونناسیی قەرەباڵغی ئەرکێکی سەرەکیی هەر سەرکردەیەکی بەرگریی شارستانییە بۆ بەڕێوەبردنی خێرا و کەمکردنەوەی قوربانییەکان."},{heading:"١. کاردانەوەی بایۆلۆجی بەرامبەر مەترسی (Fight-Flight-Freeze)",body:"کاتێک مێشک هەست بە مەترسییەک بۆ سەر ژیان دەکات، کۆئەندامی دەماریی سیمپاتەتیک (Sympathetic Nervous System) چالاک دەبێت و لەش هۆرمۆنەکانی ئەدرینالین و کۆرتیزۆل دەردەدات، و ئەمە دەبێتە هۆی چەند جۆرێک کاردانەوە:",points:["Fight (شەڕ): ئامادەبوونی لەش بۆ بەرگری. لە کارەساتەکاندا، ئەمە دەتوانێت ببێتە هۆی ڕەفتاری توند لەگەڵ کەسانی تر بۆ ڕزگاربوون.","Flight (هەڵاتن): هەوڵدان بۆ دوورکەوتنەوەی خێرا. ئەمە دەتوانێت ببێتە هۆی پاڵنانی قەرەباڵغی بەرەو یەک ئاراستە.","Freeze (وەستان/وشکبوون): کەسەکە ناتوانێت بجووڵێت یان بڕیار بدات و وەک پەیکەرێک لە شوێنی خۆی دەمێنێتەوە. ئەمە یەکێکە لە مەترسیدارترین حاڵەتەکان چونکە کەسەکە لە ناو مەترسیدا دەمێنێتەوە.","Fawn (گونجاندن): هەوڵدانی کەس بۆ ڕازیکردنی لایەنی مەترسیدار، یان شوێنکەوتنی کۆمەڵ بەبێ بیرکردنەوە.","گۆڕانکارییەکانی مێشک: لە کاتی ترسدا، بەشی Amygdala کۆنتڕۆڵ دەگرێتە دەست و بەشی Prefrontal Cortex کە بەرپرسە لە بڕیاردانی ژیرانە لاواز دەبێت. ئەمە دەبێتە هۆی «بینینی تونێلی» (Tunnel Vision): تەنها بینینی یەک ئامانج و پشتگوێخستنی دەرچوونەکانی تر."]},{heading:"٢. دەروونناسیی قەرەباڵغی و ڕەفتاری مێگەلی (Herd Behavior)",body:"مرۆڤ لە کاتی تەنگانەدا زۆرجار بەبێ بیرکردنەوە لاسایی زۆرینە دەکاتەوە، و ئەمە دەتوانێت ببێتە هۆی کارەسات. تێبینی: لێکۆڵینەوەکانی کارەسات نیشان دەدەن کە ترسی بێکۆنتڕۆڵ (Panic) کەمترە لەوەی خەڵک پێیان وایە؛ زۆربەی خەڵک بە ژیرانە ڕەفتار دەکەن، بەڵام کەمیی زانیاری و ڕێنمایی دوودڵی و قەرەباڵغی دروست دەکات:",points:["Herd Behavior (ڕەفتاری مێگەلی): ئەگەر کەسێک ڕابکات، زۆر کەس بەدوایدا ڕادەکەن تەنانەت ئەگەر نەزانن بۆچی. ئەمە ترس وەک ڤایرۆسێک بڵاو دەکاتەوە.","Funnel Effect (دیاردەی قیف): کۆبوونەوەی هەموو خەڵک لەسەر یەک دەرگا (زۆرجار ئەو دەرگایەی پێیدا هاتوونەتە ژوورەوە)، کە دەبێتە هۆی خنکان و پێشێلبوونی کەسەکان.","Panic Contagion: بڵاوبوونەوەی خێرای ترس لە ناو خەڵکدا، کە دەسەڵاتی سەرکردایەتی لاواز دەکات.","Deindividuation: کاتێک کەس دەبێتە بەشێک لە کۆمەڵێکی گەورە، هەستی بەرپرسیارێتیی تاکەکەسی کەم دەبێتەوە و دەکرێت ڕەفتاری بێکۆنتڕۆڵ بکات."]},{heading:"٣. سەرکردایەتیی قەیرانەکان (Crisis Leadership)",body:"سەرکردایەتی لە کاتی کارەساتەکاندا پێویستی بە ئارامی و فەرمانی ڕاستەوخۆ هەیە بۆ ڕێگرتن لە ترس:",points:["ئامادەبوونی ئارام (Calm Presence): سەرکردە پێویستە بە ئارامی قسە و ڕەفتار بکات؛ ئەگەر سەرکردە ترسی خۆی نیشان بدات، خەڵکیش دەترسن.","فەرمانی کورت و ڕوون: لە جیاتی قسەی درێژ، فەرمانی وەک «بڕۆنە لای ڕاست»، «بوەستن»، «بەدوای مندا وەرن» بەکاربهێنە.","ئاماژەی دەست (Hand Signals): لە کاتی ژاوەژاوی بەرزدا، ئاماژەی دەستی ڕوون بەکاربهێنە بۆ ئاراستەکردنی خەڵک.","جیاکردنەوەی کەسە ترساوەکان (Isolating Panickers): ئەو کەسانەی هاوار دەکەن و ترس بڵاو دەکەنەوە، پێویستە بە نەرمی لە کۆمەڵەکە جیا بکرێنەوە بۆ ئەوەی کاریگەری لەسەر ئەوانی تر نەکەن."]},{heading:"٤. فریاکەوتنی دەروونیی سەرەتایی (Psychological First Aid - PFA)",body:"مۆدێلی RAPID (لە زانکۆی Johns Hopkins ەوە) بۆ کەمکردنەوەی برینی دەروونیی قوربانییەکان بەکاردەهێنرێت: R گوێگرتن و دووبارەکردنەوەی هەستەکان، A هەڵسەنگاندنی پێداویستییەکان، P دیاریکردنی پێشینەکان، I دەستێوەردان، D ڕەوانەکردن بۆ خزمەتگوزارییە پێویستەکان. خاڵە سەرەکییەکان:",points:["R - Reflective Listening: گوێگرتن و دووبارەکردنەوەی هەستەکانی کەسەکە؛ ڕێگە بدە قوربانی خەمەکانی بڵێت بەبێ دادوەریکردن.","A - Assessment: هەڵسەنگاندنی پێداویستییە یەکسەرییەکان (ئاو، خواردن، پەیوەندی بە خێزانەوە).","سەلامەتی و ئارامی (Safety & Comfort): دابینکردنی شوێنێکی ئارام و دوور لە دیمەنەکانی کارەساتەکە.","چی نەکەین: هەرگیز مەڵێ «هەموو شتێک باش دەبێت» یان «دەزانم بە چیدا تێدەپەڕیت»، چونکە ئەمانە بەڵێنی بێبنەمان و کاریگەریی نەرێنییان هەیە."]},{heading:"٥. نەخۆشیی فشاری دوای برینی دەروونی (PTSD)",body:"نەخۆشیی فشاری دوای برینی دەروونی (Post-Traumatic Stress Disorder) نەک تەنها بۆ قوربانییەکان، بەڵکو بۆ تیمەکانی فریاکەوتنیش مەترسییە:",points:["نیشانەکان: خەونی ترسناک (Nightmares)، دووبارە هاتنەوەی دیمەنەکانی ڕووداوەکە (Flashbacks)، و وریایی زیادەڕۆ (Hypervigilance).","ماوە: ئەگەر نیشانەکان زیاتر لە مانگێک بەردەوام بوون یان ژیانی ڕۆژانەیان تێک دا، پێویست بە یارمەتیی پسپۆڕانی دەروونی هەیە.","خۆڕاگری (Resilience): ئامادەکاریی دەروونی پێش ڕووداو، هەڵسەنگاندنی کار دوای ئەرکەکان (Operational Debriefing)، و پشتگیریی هاوکاران. بەپێی ڕێنماییەکانی WHO، دانیشتنی دەروونیی یەکجاریی بەزۆر (Psychological Debriefing) بۆ ڕێگرتن لە PTSD پێشنیار ناکرێت."]}],media:[{kind:"video",src:"media/videos/uni_07_crowd_dynamics.mp4",title:"داینامیکی قەرەباڵغی",description:"شیکردنەوەی چۆنیەتیی جووڵەی خەڵک لە کاتی ترسدا"},{kind:"image",src:"media/images/uni_07_pfa_model.png",title:"مۆدێلی RAPID",description:"هەنگاوەکانی فریاکەوتنی دەروونیی سەرەتایی"},{kind:"video",src:"media/videos/uni_07_leadership_drill.mp4",title:"ڕاهێنانی سەرکردایەتی",description:"چۆنیەتیی ئاراستەکردنی خەڵک بە دەنگ و ئاماژەی دەست"}],quiz:[{question:"مەبەست لە «Freeze» لە کاردانەوەی بایۆلۆجیی ترسدا چییە؟",options:[{text:"هەڵاتنی خێرا",correct:!1},{text:"شەڕکردن بۆ پاراستنی ژیان",correct:!1},{text:"وشکبوون و وەستان لە شوێنی خۆ بەبێ جووڵە",correct:!0},{text:"گونجاندن لەگەڵ کۆمەڵ",correct:!1}],explanation:"Freeze حاڵەتێکی دەروونییە کە تێیدا کەس ناتوانێت هیچ بڕیارێک بدات یان بجووڵێت، و ئەمە مەترسیی مانەوە لە ناو کارەساتەکەدا زیاد دەکات."},{question:"بەپێی پرۆتۆکۆڵی PFA، کام ڕەفتار لەگەڵ کەسێکی تووشبووی برینی دەروونی «هەڵەیە»؟",options:[{text:"گوێگرتن بە ئارامی",correct:!1},{text:"دابینکردنی ئاو و خواردن",correct:!1},{text:"گوتنی ڕستەی «هەموو شتێک باش دەبێت»",correct:!0},{text:"پەیوەندیکردن بە خێزانەکەیەوە",correct:!1}],explanation:"دانی بەڵێنی بێبنەمای وەک «باش دەبێت» کاریگەرییەکی نەرێنیی هەیە و متمانەی قوربانی کەم دەکاتەوە."},{question:"باشترین شێوازی فەرماندان لە کاتی قەیراندا بۆ سەرکردەیەکی بەرگریی شارستانی چییە؟",options:[{text:"قسەکردن بە هاوار و ترسەوە",correct:!1},{text:"فەرمانی کورت، ڕوون و بە دەنگێکی ئارام",correct:!0},{text:"گوێنەدان بە خەڵک",correct:!1},{text:"باسکردنی وردەکارییە کیمیاییەکانی کارەساتەکە",correct:!1}],explanation:"خەڵک پێویستیان بە ئاراستەکردنی ڕاستەوخۆ و ڕوون هەیە؛ ئارامیی سەرکردە ترس لە ناو خەڵکدا کەم دەکاتەوە."},{question:"دیاردەی «Herd Behavior» چۆن کار دەکات؟",options:[{text:"بیرکردنەوەی تاکەکەسی",correct:!1},{text:"لاساییکردنەوەی بێ بیرکردنەوەی ڕەفتارەکانی زۆرینە",correct:!0},{text:"پەیڕەوکردنی یاساکان",correct:!1},{text:"ڕزگارکردنی کەسانی تر",correct:!1}],explanation:"مرۆڤ لە کاتی ترسدا زیاتر حەز دەکات بەدوای خەڵکدا بڕوات بەبێ ئەوەی بیر بکاتەوە کە ئایا ئەو ڕێگایە دروستە یان نا."}]},{id:8,code:"ENV-800",icon:"Leaf",accent:"#16a34a",title:"سەلامەتیی ژینگە و بەڕێوەبردنی پاشماوەکان",subtitle:"Environmental Safety & Waste Management",summary:"کاریگەریی ئاگر و ماددە کیمیاییەکان لەسەر ژینگە، بەڕێوەبردنی دروستی پاشماوە پزیشکییەکان، پاراستنی سەرچاوەکانی ئاو، و بەرپرسیارێتیی ژینگەیی.",blocks:[{body:"کاتێک باسی سەلامەتی دەکەین، پێویستە تەنها بیر لە سەلامەتیی مرۆڤ نەکەینەوە، بەڵکو سەلامەتیی ژینگە و سروشتیش لەبەرچاو بگرین. هەر کارەسات یان ڕووداوێکی سەلامەتی (وەک ئاگر یان ڕژانی کیمیایی) کاریگەرییەکی درێژخایەن لەسەر ژینگە بەجێ دەهێڵێت: دووکەڵ هەوا پیس دەکات، ئاوی کوژاندنەوەی ئاگر ژەهراوی دەبێت و لەگەڵ ئاوە ژێرزەوییەکاندا تێکەڵ دەبێت، و پاشماوەی مەترسیدار پەیدا دەبن. لەم مۆدیوولەدا، باسی بەڕێوەبردنی پاشماوەکان، پاراستنی ئاو و هەوا، و بەرپرسیارێتیی ژینگەییی دامەزراوەکان دەکەین بۆ پاراستنی نەوەکانی داهاتوو."},{heading:"١. پاشماوە پزیشکی و بایۆلۆجییەکان (Medical Waste)",body:"لە نەخۆشخانە، کلینیک و تاقیگەکاندا، پاشماوەی تایبەت پەیدا دەبن کە دەتوانن بەکتریا و ڤایرۆس بگوازنەوە. ئەم پاشماوانە نابێت وەک زبڵی ئاسایی فڕێ بدرێن، بەڵکو پێویستە بە ڕەنگ جیا بکرێنەوە. ڕەنگەکان لە وڵاتێکەوە بۆ وڵاتێکی تر دەگۆڕێن؛ لێرەدا سیستەمی ڕێکخراوی تەندروستیی جیهانی (WHO) بەکاردەهێنرێت، و هەمیشە ڕێنماییە ناوخۆییەکانی نەخۆشخانەکە پەیڕەو بکە:",points:["پاشماوەی تیژ (Sharps - زەرد): هەموو ئەو شتانەی دەتوانن پێست کون بکەن، وەک دەرزی، تیغی نەشتەرگەری و شووشەی شکاو. پێویستە لە سندووقی پلاستیکیی ڕەق و دژە-کونبووندا (Sharps Container) کۆ بکرێنەوە.","پاشماوەی گوازەرەوەی نەخۆشی (Infectious/Biohazard - زەرد بەپێی WHO؛ لە هەندێک وڵات وەک ئەمریکا سوور): ئەو شتانەی بە خوێن یان شانەکانی لەش پیس بوون و کەرەستەکانی تاقیگە. پێویستە بە ئۆتۆکلاڤ (Autoclave) یان سووتاندنی تەواو (Incineration) لەناو ببرێن.","پاشماوەی گشتی (General - ڕەش): کاغەز، کارتۆن و پلاستیکی پاک کە هیچ مەترسییەکی بایۆلۆجییان لەسەر نییە.","پاشماوەی دەرمانی و کیمیایی (Pharmaceutical/Chemical - قاوەیی بەپێی WHO): دەرمانی بەسەرچوو یان پاشماوە کیمیاییەکانی تاقیگە کە پێویستە بە ڕێکاری تایبەت چارەسەر بکرێن."]},{heading:"٢. پیسبوونی ئاو بەهۆی کوژاندنەوەی ئاگرەوە (Fire Runoff)",body:"ئەو ئاوەی لە کاتی کوژاندنەوەی ئاگرە گەورەکاندا بەکاردەهێنرێت، تەنها ئاوێکی پیس نییە، بەڵکو «ژەهرێکی شل»ە کە پڕە لە ماددەی کیمیایی و کانزایی:",points:["ماددە پیسکەرەکان: PAHs لە سووتانی پلاستیکەوە، کانزا قورسەکانی وەک قوڕقوشم و جیوە، و ماددە مەترسیدارەکانی کەفی کوژاندنەوەی ئاگر وەک PFAS ی تێدایە، کە پێیان دەوترێت «کیمیایی هەتاهەتایی» (Forever Chemicals) چونکە لە ژینگەدا شی نابنەوە.","گرتنەوەی ئاو (Containment): ئەندازیارانی سەلامەتی پێویستە بەربەستی کاتی دروست بکەن بۆ ئەوەی ئەم ئاوە ژەهراوییە نەچێتە ناو ڕێڕەوەکانی ئاوی پیس یان ڕووبارەکانەوە.","چارەسەرکردنی ئاو: ئەم ئاوە پێویستە کۆ بکرێتەوە و بۆ وێستگە تایبەتەکانی چارەسەرکردنی ئاوی پیس (Wastewater Treatment) بنێردرێت پێش ئەوەی بەربدرێت."]},{heading:"٣. پیسبوونی هەوا و کیمیای دووکەڵ",body:"ئاگرە گەورەکان، بە تایبەتی ئاگری پیشەسازی و دارستانەکان، تەنۆلکەی زۆر مەترسیدار فڕێ دەدەنە ناو هەواوە:",points:["تەنۆلکە وردەکان (PM2.5): پارچەی زۆر بچووکن کە دەچنە قووڵایی سییەکانەوە و دەبنە هۆی نەخۆشییەکانی دڵ و سییەکان و شێرپەنجە.","گازە ژەهراوییەکان: وەک مۆنۆکسیدی کاربۆن (CO) و هایدرۆجین سیانید (HCN) کە لە کاتی سووتانی بیناکاندا بەرهەم دێن و هەوای دەوروبەر ژەهراوی دەکەن.","بارانی ترش (Acid Rain): گازەکانی وەک SOx و NOx لەگەڵ باراندا تێکەڵ دەبن و زیان بە ڕووەک و دارستانەکان دەگەیەنن."]},{heading:"٤. پاشماوە ئەلیکترۆنییەکان (E-Waste)",body:"ئامێرە ئەلیکترۆنییە شکاو یان سووتاوەکان (مۆبایل، کۆمپیوتەر) مەترسییەکی ژینگەییی گەورەن:",points:["کانزا ژەهراوییەکان: قوڕقوشم، جیوە و کادمیۆمیان تێدایە کە ئەگەر بچنە ناو ئاو یان خاکەوە، شی نابنەوە و بۆ ماوەیەکی زۆر درێژ دەمێننەوە و تەندروستیی مرۆڤ دەخەنە مەترسییەوە.","ڕیسایکلین (Recycling): نابێت ئەم ئامێرانە لە شوێنە گشتییەکاندا فڕێ بدرێن؛ پێویستە بۆ وێستگە تایبەتەکانی ڕیسایکلین بنێردرێن بۆ ئەوەی کانزا بەنرخەکان (زێڕ و زیو) لێیان جیا بکرێنەوە."]},{heading:"٥. بەرپرسیارێتیی ژینگەیی و ستانداردی ISO 14001",body:"باشترە هەر دامەزراوەیەک سیستەمێکی بەڕێوەبردنی ژینگەیی هەبێت بۆ کەمکردنەوەی زیانەکان:",points:["بنەمای 3R: کەمکردنەوە (Reduce)، دووبارە بەکارهێنانەوە (Reuse)، و ڕیسایکلین (Recycle).","ISO 14001: ستانداردێکی نێودەوڵەتیی خۆبەخشانەیە بۆ سیستەمی بەڕێوەبردنی ژینگەیی (EMS)؛ ئەو دامەزراوانەی پەیڕەوی دەکەن، سیاسەتێکی ژینگەیی، ئامانجی شیاوی پێوانەکردن و پشکنینی ناوخۆیی خولی دادەنێن.","چاودێری و پشکنین: ئەنجامدانی پشکنینی خولی بۆ خاک و ئاوی دەوروبەری کارگەکان بۆ دڵنیابوونەوە لە نەبوونی دزەکردنی ماددە کیمیاییەکان."]}],media:[{kind:"image",src:"media/images/uni_08_waste_colors.png",title:"سیستەمی ڕەنگەکان",description:"جیاکردنەوەی پاشماوە پزیشکییەکان بە ڕەنگ بەپێی WHO"},{kind:"video",src:"media/videos/uni_08_hazmat_disposal.mp4",title:"فڕێدانی ماددە مەترسیدارەکان",description:"ڕێکارە دروستەکانی فڕێدانی پاشماوە کیمیاییەکان"},{kind:"image",src:"media/images/uni_08_runoff_control.png",title:"کۆنتڕۆڵکردنی ئاوی کوژاندنەوەی ئاگر",description:"چۆنیەتیی ڕێگرتن لە تێکەڵبوونی ئاوی ژەهراوی لەگەڵ ڕووبارەکاندا"}],quiz:[{question:"بەپێی سیستەمی WHO، دەرزی و تیغە پزیشکییەکان لە کام دەفردا فڕێ دەدرێن؟",options:[{text:"کیسەی سوور (Biohazard)",correct:!1},{text:"کیسەی ڕەش (گشتی)",correct:!1},{text:"سندووقی ڕەقی زەرد (Sharps Container)",correct:!0},{text:"کیسەی شین",correct:!1}],explanation:"هەموو شتە تیژەکان پێویستە لە سندووقی ڕەقی زەرددا (Sharps Container) فڕێ بدرێن بۆ ئەوەی نەبنە هۆی برینداربوون و گواستنەوەی نەخۆشی."},{question:"مەترسیی گەورەی ئاوی کوژاندنەوەی ئاگر (Fire Runoff) چییە؟",options:[{text:"تەنها پیسە",correct:!1},{text:"ماددەی ژەهراوی و کانزای قورس لەگەڵ خۆیدا دەباتە ناو ژینگەوە",correct:!0},{text:"پلەی گەرمای زۆر بەرزە",correct:!1},{text:"هیچ مەترسییەکی نییە",correct:!1}],explanation:"ئەم ئاوە ژەهر و ماددە کیمیاییە سووتاوەکان لەگەڵ خۆیدا دەبات و دەتوانێت ئاوی سەر زەوی و ژێرزەوی ژەهراوی بکات."},{question:"تەنۆلکەکانی PM2.5 لە دووکەڵی ئاگرەکاندا چ مەترسییەک بۆ تەندروستیی مرۆڤ دروست دەکەن؟",options:[{text:"تەنها ڕەنگی پێست دەگۆڕن",correct:!1},{text:"دەچنە قووڵایی سییەکانەوە و دەبنە هۆی نەخۆشیی سەخت",correct:!0},{text:"هیچ زیانێکیان نییە",correct:!1},{text:"بۆ هەناسەدان باشن",correct:!1}],explanation:"PM2.5 پارچەی زۆر بچووکن کە دەچنە قووڵایی سییەکانەوە و دەبنە هۆی کێشەی درێژخایەنی دڵ و کۆئەندامی هەناسە."},{question:"مەبەست لە (Recycle) لە بنەمای 3R دا چییە؟",options:[{text:"سووتاندنی پاشماوەکان",correct:!1},{text:"ڕیسایکلین و دووبارە بەرهەمهێنانەوە لە پاشماوەکان",correct:!0},{text:"کەمکردنەوەی خەرجییەکان",correct:!1},{text:"فڕێدان لە دەرەوەی شار",correct:!1}],explanation:"Recycle واتە گۆڕینی پاشماوەکان بۆ کەرەستەی نوێ بۆ ئەوەی ژینگە بپارێزرێت."}]},{id:9,code:"MGMT-900",icon:"Network",accent:"#2563eb",title:"سیستەمی فەرماندەیی ڕووداوەکان (ICS)",subtitle:"Incident Command System & Strategic Management",summary:"سیستەمی ستانداردی ICS بۆ بەڕێوەبردنی ڕووداو و کارەساتەکان، هەماهەنگی لە نێوان دەزگاکاندا، و بەڕێوەبردنی سەرچاوەکان.",blocks:[{body:"کاتێک کارەساتێکی گەورە ڕوو دەدات، وەک لافاو، بوومەلەرزە یان ئاگرێکی پیشەسازی، زۆرجار گەورەترین کێشە تەنها کەمیی سەرچاوەکان نییە، بەڵکو نەبوونی هەماهەنگی و ڕێکخستنە. زۆرجار دەیان تیمی جیاواز (کوژاندنەوەی ئاگر، پۆلیس، ئەمبولانس و خۆبەخشان) پێکەوە دەگەنە شوێنی ڕووداوەکە؛ بەبێ سیستەمێکی ڕێکخراو، ئەمە دەبێتە هۆی تێکچوون و دووبارەبوونەوەی کارەکان. سیستەمی فەرماندەیی ڕووداوەکان (ICS) چارەسەری ئەم کێشەیەیە. ئەم سیستەمە لە ساڵانی حەفتاکاندا لە ئەمریکا (بەرنامەی FIRESCOPE لە کالیفۆرنیا) دانرا، و ئەمڕۆ بەشێکە لە سیستەمی نیشتمانیی ئەمریکی NIMS (FEMA) و لە زۆر وڵات و ڕێکخراودا وەرگیراوە بۆ بەڕێوەبردنی قەیرانەکان بە شێوەیەکی ڕێکخراو."},{heading:"١. پێنج ئەرکە سەرەکییەکەی ICS (Major Functions)",body:"سیستەمی ICS لەسەر بنەمای دابەشکردنی ئەرکەکان کار دەکات. هەر ڕووداوێک، بچووک بێت یان گەورە، پێویستی بەم پێنج ئەرکە هەیە (لە ڕووداوە تایبەتەکاندا، ئەرکی زانیاری و لێکۆڵینەوە - Intelligence/Investigations - دەکرێت وەک ئەرکی شەشەم زیاد بکرێت):",points:["١. Incident Commander (IC): فەرماندەی ڕووداوەکە؛ یەک کەسە کە بڕیارە کۆتاییەکان دەدات و بەرپرسە لە دانانی ئامانجە سەرەکییەکان و سەلامەتیی گشتیی تیمەکان (لەو ڕووداوانەی چەند دەزگایەکیان تێدایە، فەرماندەیی یەکگرتوو - Unified Command - بەکاردەهێنرێت).","٢. Operations (کارە مەیدانییەکان): ئەو بەشەیە کە کاری ڕاستەوخۆ لە مەیداندا ئەنجام دەدات (وەک کوژاندنەوەی ئاگر، ڕزگارکردن، یان چارەسەری پزیشکی).","٣. Planning (پلاندانان): کۆکردنەوەی زانیاری لەسەر ڕووداوەکە، شیکردنەوەی داتاکان، و نووسینی «پلانی کارەکانی ڕووداو» (IAP) بۆ قۆناغەکانی داهاتوو.","٤. Logistics (لۆجیستیک): دابینکردنی هەموو پێداویستییەکان (خواردن، ئاو، سووتەمەنی، ئامێرەکانی پەیوەندی و شوێنی حەوانەوەی تیمەکان). بەبێ لۆجیستیک، تیمە مەیدانییەکان ناتوانن بەردەوام بن.","٥. Finance/Admin (دارایی و کارگێڕی): بەڕێوەبردنی لایەنی دارایی، تۆمارکردنی کاتژمێرەکانی کار و خەرجیی کەرەستەکان، و مامەڵەکردن لەگەڵ داواکارییەکانی قەرەبووکردنەوە."]},{heading:"٢. مەودای کۆنتڕۆڵ (Span of Control)",body:"یەکێک لە گرنگترین بنەماکانی ICS ئەوەیە کە نابێت بارێکی زیادە لەسەر سەرپەرشتیار بێت. ئەم بنەمایە دیاری دەکات کە سەرپەرشتیارێک دەتوانێت بە باشی کۆنتڕۆڵی چەند کەس بکات:",points:["ژمارەی گونجاو: بەپێی NIMS، هەر سەرپەرشتیارێک پێویستە کۆنتڕۆڵی ٣ تا ٧ کەس یان یەکە بکات، و ڕێژەی پێشنیارکراو بریتییە لە ١ بۆ ٥.","بۆچی ٥؟ ئەگەر ژمارەکە لە ٧ زیاتر بێت، سەرپەرشتیار کۆنتڕۆڵ لەدەست دەدات و هەڵە پەیدا دەبن؛ ئەگەر لە ٣ کەمتر بێت، سەرچاوەکان بەفیڕۆ دەچن.","ڕێکخستنی مۆدیوولی (Modular Organization): ICS یەکە بە یەکە فراوان دەبێت؛ هەرکاتێک پێویست بوو، بەشی نوێ دەکرێنەوە بۆ ئەوەی مەودای کۆنتڕۆڵ لە سنووری گونجاودا بمێنێتەوە."]},{heading:"٣. زمانی هاوبەش و زاراوە ستانداردەکان",body:"لە کاتی تەنگانەدا، تێنەگەیشتن دەتوانێت ببێتە هۆی مردن. ICS پێویست دەکات کە هەموو لایەنەکان بە زمانێکی هاوبەش و ڕوون قسە بکەن:",points:["زمانی ڕوون (Plain Language): کۆدەکانی دە (Ten-codes، وەک 10-4) و کۆدە تایبەتەکانی دەزگاکان بەکارناهێنرێن؛ ئەوانە سیستەمێکی کۆنن (Legacy) و واتاکانیان لە دەزگایەکەوە بۆ یەکێکی تر جیاوازن. پێویستە زمانێکی سادە و ڕوون بەکاربهێنرێت بۆ ئەوەی هەموو دەزگاکان (پۆلیس، کوژاندنەوەی ئاگر، ئەمبولانس) تێبگەن.","ناوی ستانداردی پۆستەکان: ناوی پۆست و یەکەکان لە هەموو ڕووداوەکاندا پێویستە وەک یەک بن (بۆ نموونە: Incident Commander، نەک «سەرۆک» یان «بەرپرس» لە شوێنێک و ناوێکی تر لە شوێنێکی تر).","دابەشکردنی جوگرافی: دابەشکردنی شوێنی ڕووداوەکە بۆ ناوچەکان (Divisions) بۆ کۆنتڕۆڵکردنی هەر ناوچەیەک بە جیا، و بۆ گرووپەکان (Groups) بەپێی ئەرک."]},{heading:"٤. پلانی کارەکانی ڕووداو (Incident Action Plan - IAP)",body:"IAP بەڵگەنامەیەکی نووسراوە کە ڕێگای کار بۆ هەر ماوەیەکی کار (Operational Period) دیاری دەکات:",points:["ناوەڕۆک: پلانەکە دیاری دەکات: ئامانج چییە؟ کێ بەرپرسە؟ کام کەناڵی ڕادیۆ بەکاربهێنرێت؟ و خاڵی پزیشکی لە کوێیە؟","ماوەی پلان: زۆربەی جار پلانەکە بۆ ١٢ تا ٢٤ کاتژمێری داهاتوو دەنووسرێت.","ئامانجەکانی SMART: ئامانجەکان پێویستە دیار، شیاوی پێوانەکردن، شیاوی بەدەستهێنان، گونجاو و بە کاتێکی دیاریکراو بن (بۆ نموونە: کوژاندنەوەی ئاگری کۆگای باکوور لە ماوەی ٤ کاتژمێردا)."]},{heading:"٥. فەرماندەیی یەکگرتوو (Unified Command)",body:"کاتێک ڕووداوێک کاریگەری لەسەر چەند دەزگایەک یان چەند ناوچەیەکی ئیداری دەکات، فەرماندەیی یەکگرتوو (Unified Command) بەکاردەهێنرێت:",points:["هەماهەنگی: لە جیاتی ئەوەی هەر دەزگایەک بە سەربەخۆیی کار بکات، بەرپرسانی هەموو دەزگاکان لە یەک شوێندا کۆ دەبنەوە و لەسەر یەک پلان ڕێک دەکەون.","سوود: ڕێگری لە ناکۆکییەکان دەکات و ناهێڵێت یەک کار دوو جار لەلایەن دوو تیمەوە بکرێت.","ICP (Incident Command Post): شوێنێکی فیزیکیی دیاریکراوە کە فەرماندەکانی ڕووداوەکە تێیدا کۆ دەبنەوە بۆ بەڕێوەبردنی ڕووداوەکە."]},{heading:"٦. کۆتاییهێنان بە ئەرک (Demobilization)",body:"کۆتاییهێنان بە ئەرک بە شێوەیەکی ڕێکخراو هێندەی دەستپێکردن گرنگە:",points:["پلانی کشانەوە: تیمەکان پێویستە بە ڕیزبەندی بکشێنرێنەوە بۆ ئەوەی هیچ کەموکوڕییەک لە مەیداندا نەمێنێت و هەموو کەس و ئامێرەکان هەژمار بکرێن.","After Action Review (AAR): ئەنجامدانی دانیشتنێکی هەڵسەنگاندن دوای ڕووداوەکە بۆ دیاریکردنی خاڵە بەهێز و لاوازەکان، بۆ ئەوەی کار لە داهاتوودا باشتر بێت."]}],media:[{kind:"image",src:"media/images/uni_09_ics_structure.png",title:"پەیکەری ڕێکخستنی ICS",description:"دیاگرامی پێنج ئەرکە سەرەکییەکەی فەرماندەیی ڕووداوەکان"},{kind:"video",src:"media/videos/uni_09_command_post.mp4",title:"بنکەی فەرماندەیی ڕووداو (ICP)",description:"چۆنیەتیی بەڕێوەبردنی هەماهەنگیی مەیدانی لە کاتی کارەساتەکاندا"},{kind:"image",src:"media/images/uni_09_span_control.png",title:"مەودای کۆنتڕۆڵ",description:"ڕوونکردنەوەی بنەمای ١ سەرپەرشتیار بۆ ٥ کارمەند"}],quiz:[{question:"بەپێی ICS/NIMS، ڕێژەی پێشنیارکراوی مەودای کۆنتڕۆڵ (Span of Control) چەندە؟",options:[{text:"١٠ کەس",correct:!1},{text:"٥ کەس",correct:!0},{text:"٢ کەس",correct:!1},{text:"١٥ کەس",correct:!1}],explanation:"بەپێی NIMS، مەودای کۆنتڕۆڵ لە نێوان ٣ و ٧ دایە و ڕێژەی ١ بۆ ٥ پێشنیار دەکرێت بۆ ئەوەی سەرپەرشتیار بتوانێت بە وردی چاودێریی تیمەکە بکات."},{question:"کام بەش بەرپرسە لە دابینکردنی خواردن، ئاو و ئامێرەکانی پەیوەندی بۆ تیمەکان؟",options:[{text:"کارە مەیدانییەکان (Operations)",correct:!1},{text:"پلاندانان (Planning)",correct:!1},{text:"لۆجیستیک (Logistics)",correct:!0},{text:"دارایی (Finance)",correct:!1}],explanation:"بەشی لۆجیستیک بەرپرسە لە دابینکردنی هەموو پێداویستییە فیزیکییەکان و خزمەتگوزارییەکان."},{question:"ئامانجی سەرەکی لە «زمانی ڕوون» (Plain Language) لە پەیوەندییەکاندا چییە؟",options:[{text:"بۆ ئەوەی خەڵک تێنەگەن",correct:!1},{text:"بۆ دڵنیابوونەوە لە هەماهەنگیی هەموو دەزگاکان بەبێ هەڵە",correct:!0},{text:"بۆ کەمکردنەوەی کاتژمێرەکانی کار",correct:!1},{text:"بۆ جوانیی قسەکردن",correct:!1}],explanation:"بەکارهێنانی زمانێکی سادە و ڕوون (نەک کۆد) ڕێگە دەدات پۆلیس، کوژاندنەوەی ئاگر و ئەمبولانس بە دروستی لە یەکتر تێبگەن."},{question:"کەی «Unified Command» بەکاردەهێنرێت؟",options:[{text:"کاتێک ڕووداوەکە بچووک بێت",correct:!1},{text:"کاتێک تەنها یەک دەزگا لە شوێنی ڕووداوەکە بێت",correct:!1},{text:"کاتێک چەند دەزگایەک یان چەند ناوچەیەکی ئیداری لە ڕووداوەکەدا بەشدار بن",correct:!0},{text:"هەرگیز بەکارناهێنرێت",correct:!1}],explanation:"کاتێک چەند دەزگایەک یان چەند ناوچەیەکی ئیداری لە ڕووداوەکەدا بەشدار دەبن، فەرماندەیی یەکگرتوو (Unified Command) دادەمەزرێت بۆ ئەوەی هەموو لایەنەکان لەسەر یەک پلان کار بکەن."}]},{id:10,code:"TECH-1000",icon:"Satellite",accent:"#7c3aed",title:"تەکنەلۆجیای داهاتوو و داهێنان",subtitle:"Future Technology in Emergency Response",summary:"ڕۆڵی فڕۆکەی بێفڕۆکەوان (UAVs)، ڕۆبۆتەکانی کوژاندنەوەی ئاگر، کامێراکانی گەرما (Thermal)، زیرەکیی دەستکرد (AI)، و سیستەمەکانی IoT لە ڕزگارکردندا.",blocks:[{body:"لە دە ساڵی ڕابردوودا، تەکنەلۆجیا بە شێوەیەکی بەرچاو شێوازی کاری بەرگریی شارستانی و ڕزگارکردنی گۆڕیوە. ئامێرە نوێیەکان و هەستەوەرە زیرەکەکان دەتوانن بچنە ئەو شوێنانەی کە مرۆڤ بە ئاستەم پێیان دەگات، و ئەمە ڕێگە دەدات زانیاریی ورد لەسەر مەترسییەکان کۆ بکرێتەوە و یارمەتی خێراتر بگات. لەم مۆدیوولەدا، باسی ئەو تەکنەلۆجیایانە دەکەین کە ئەمڕۆ پەرەیان پێ دەدرێت بۆ ئەوەی ببنە بەشێک لە سیستەمەکانی پاراستنی شارستانی لە جیهاندا."},{heading:"١. فڕۆکەی بێفڕۆکەوان (Drones / UAVs)",body:"درۆن یەکێکە لە گەورەترین داهێنانەکان لە بواری تەنگانەدا. ئەم ئامێرانە دەتوانن کاری مەیدانیی سەخت ئەنجام بدەن بەبێ ئەوەی ژیانی تیمەکانی ڕزگارکردن بکەوێتە مەترسییەوە:",points:["چاودێریی ئاسمانی (Aerial Surveillance): درۆن دەتوانێت وێنە و ڤیدیۆی ڕاستەوخۆ (Real-time) بۆ ناوەندی فەرماندەیی بنێرێت بۆ ئەوەی وێنەی گشتیی کارەساتەکە دەربکەوێت.","کامێراکانی گەرما (Thermal Imaging): دۆزینەوەی کەسە زیندووەکان لە ناو دارستانەکاندا، لە شەودا، یان لە ناو دووکەڵێکی چڕدا لە ڕێگەی هەستکردن بە گەرمای لەشەوە.","گەیاندنی تەنگانە: ناردنی دەرمان، کەرەستەی پزیشکی یان ئامێری پەیوەندی بۆ ئەو شوێنانەی کە بەهۆی لافاو یان بوومەلەرزەوە ڕێگایان لێ گیراوە.","نەخشەسازیی سێ-ڕەهەندی (3D): درۆن دەتوانێت لە ماوەیەکی کورتدا نەخشەیەکی سێ-ڕەهەندی بۆ شوێنی ڕووداوەکە دروست بکات بۆ ئەوەی پلانی ڕزگارکردن و دەرچوون باشتر دابنرێت."]},{heading:"٢. ڕۆبۆتەکانی کوژاندنەوەی ئاگر و ڕزگارکردنی تەکنیکی",body:"ڕۆبۆتەکان وەک هێزێکی پشتیوان کار دەکەن لەو شوێنانەی کە پلەی گەرما یان گازە ژەهراوییەکان لە توانای مرۆڤ بەدەرن:",points:["ڕۆبۆتەکانی کوژاندنەوە: ئامێری گەورەن کە لە دوورەوە کۆنتڕۆڵ دەکرێن و دەتوانن لە ناوەڕاستی ئاگرەکە نزیک ببنەوە و ئاو بە پەستانێکی بەرز بپڕژێنن (وەک ڕۆبۆتی Colossus).","ڕۆبۆتە مارئاساکان (Snake Robots): ڕۆبۆتی باریکن کە دەتوانن بچنە ناو کەلێنەکانی بینا ڕووخاوەکانەوە بۆ دیاریکردنی شوێنی بریندارەکان.","ئێسکەپەیکەری دەرەکی (Exoskeletons): جلوبەرگی میکانیکیی بەهێزکەرن کە توانا جەستەییەکانی ئاگرکوژەکان زیاد دەکەن بۆ هەڵگرتنی باری قورس بە ماندووبوونێکی کەمتر.","HazMat Robots: ڕۆبۆتی تایبەتن بۆ مامەڵەکردن لەگەڵ ماددە ئەتۆمی و کیمیاییەکان، بۆ ئەوەی مرۆڤ تووشی ژەهراویبوون نەبێت."]},{heading:"٣. زیرەکیی دەستکرد و شیکردنەوەی داتای گەورە (AI & Big Data)",body:"زیرەکیی دەستکرد (Artificial Intelligence) دەتوانێت لە چەند چرکەیەکدا ملیۆنان زانیاری شی بکاتەوە:",points:["پێشبینیکردنی مەترسییەکان: شیکردنەوەی داتاکانی کەشوهەوا و هەستەوەرەکان بۆ پێشبینیکردنی لافاو یان مەترسیی ئاگری دارستانەکان پێش ڕوودانیان.","سیستەمەکانی وەڵامدانەوەی زیرەک: AI دەتوانێت یارمەتیی کارمەندانی وەرگرتنی پەیوەندییەکان بدات بۆ پۆلێنکردنی پەیوەندییەکانی تەنگانە (١١٥) بەپێی گرنگی و ناردنی تیمی گونجاو؛ بڕیاری کۆتایی بە دەست مرۆڤەوە دەمێنێتەوە.","بینینی کۆمپیوتەری (Computer Vision): ناسینەوەی ئاگر یان دووکەڵ لە ڕێگەی کامێراکانی چاودێریی شارەوە بە شێوەیەکی ئۆتۆماتیکی و ئاگادارکردنەوەی خێرا."]},{heading:"٤. ئینتەرنێتی شتەکان (IoT) و بینا زیرەکەکان",body:"سیستەمی IoT (Internet of Things) ئامێرەکان بە تۆڕێکەوە دەبەستێتەوە بۆ ئەوەی بینا ببێتە سیستەمێکی وریا:",points:["بینا زیرەکەکان (Smart Buildings): هەستەوەرەکان دەتوانن بە شێوەیەکی ئۆتۆماتیکی دەرگا دژە-ئاگرەکان دابخەن و سیستەمی گۆڕینی هەوا ڕابگرن بۆ ئەوەی دووکەڵ بڵاو نەبێتەوە.","ئامێرە لەبەرکراوەکان (Wearables): کاتژمێری زیرەک بۆ تیمەکانی تەنگانە کە ئاستی ئۆکسجین، لێدانی دڵ و شوێنەکەیان (GPS) بۆ ناوەندی کۆنتڕۆڵ دەنێرن.","ئۆتۆمبێلە بەستراوەکان: ئۆتۆمبێلەکانی کوژاندنەوەی ئاگر کە دەتوانن بە ئۆتۆماتیکی گڵۆپەکانی هاتوچۆ سەوز بکەن (Traffic Signal Preemption) بۆ ئەوەی زووتر بگەنە شوێنی مەبەست."]},{heading:"٥. ڕاستیی مەجازی (VR) و ڕاستیی زیادکراو (AR)",body:"بەکارهێنانی تەکنەلۆجیای بینراو بۆ ڕاهێنان و کاری مەیدانی:",points:["ڕاهێنان بە VR: ڕێگە دەدات تیمەکانی ڕزگارکردن لەسەر سیناریۆی کارەساتە گەورەکان ڕاهێنان بکەن بەبێ هیچ مەترسییەک.","AR لە ناو کڵاوەکاندا: هەندێک کڵاوی (Helmet) نوێی ئاگرکوژی شاشەیەکی بچووکیان تێدایە کە نەخشەی بیناکە و ئاستی هەوا لە تانکی SCBA دا لە ناو دووکەڵدا نیشان دەدات."]},{heading:"٦. نانۆتەکنەلۆجیا و ماددە نوێیەکان",body:"پەرەپێدانی کەرەستەکانی داهاتوو بۆ پاراستنی لەش:",points:["Nanotechnology: دروستکردنی جلوبەرگی ئاگرکوژیی سووکتر بەڵام بە بەرگرییەکی بەرزتر لە بەرامبەر گەرمادا.","پاترییە نوێیەکان: پاتریی Sodium-ion یان Solid-state کە مەترسیی گڕگرتن و تەقینەوەیان کەمترە لە پاترییە ئاساییەکانی لیتیۆم-ئایۆن."]},{heading:"٧. ئاستەنگەکان و لایەنی ئەخلاقی",body:"سەرەڕای سوودە گەورەکان، تەکنەلۆجیا چەندین پرسیاری گرنگ دروست دەکات:",points:["تێچوون (Cost): نرخی بەرزی ئەم ئامێرانە ڕێگرە لە وەرگرتنیان لەلایەن هەموو وڵاتانەوە.","پاراستنی داتاکان: مەترسیی هاککردنی سیستەمەکانی بینا زیرەکەکان یان سیستەمەکانی فەرماندەیی.","بڕیارەکانی AI: ئایا دروستە زیرەکیی دەستکرد لە جیاتی مرۆڤ بڕیار لەسەر ژیانی مرۆڤەکان بدات لە کاتی پۆلێنکردنی بریندارەکاندا (Triage)؟"]}],media:[{kind:"video",src:"media/videos/uni_10_drone_thermal.mp4",title:"درۆن و دۆزینەوەی بریندارەکان",description:"چۆنیەتیی بەکارهێنانی کامێراکانی گەرما بۆ دۆزینەوەی کەسەکان لە ناو دارستانەکاندا"},{kind:"image",src:"media/images/uni_10_smart_helmet.jpg",title:"کڵاوی زیرەکی AR",description:"نیشاندانی زانیارییەکانی ژینگە لەسەر شاشەی کڵاوی ئاگرکوژ"},{kind:"video",src:"media/videos/uni_10_robot_extinguish.mp4",title:"کارکردنی ڕۆبۆتی کوژاندنەوەی ئاگر",description:"کوژاندنەوەی ئاگری کارگەیەک بە کۆنتڕۆڵی لە دوورەوە"}],quiz:[{question:"کامێراکانی گەرما (Thermal Imaging) لەسەر درۆنەکان چۆن یارمەتیی تیمەکانی ڕزگارکردن دەدەن؟",options:[{text:"بۆ وێنەگرتنی ڕەنگاوڕەنگ",correct:!1},{text:"بۆ دۆزینەوەی لەشی مرۆڤ لە ڕێگەی گەرماوە لە تاریکی و دووکەڵدا",correct:!0},{text:"بۆ کوژاندنەوەی ئاگر",correct:!1},{text:"بۆ پەیوەندیکردن بە مۆبایلەوە",correct:!1}],explanation:"لەشی مرۆڤ لە ژینگەی دەوروبەر گەرمترە، بۆیە کامێراکانی Thermal دەتوانن شوێنی مرۆڤ بە ڕوونی نیشان بدەن، بە تایبەتی لە شەودا و لە ناو دووکەڵدا. لە ژێر بەرد و کۆنکریتدا، توانایان سنووردارە."},{question:"سوودی سەرەکیی Exoskeletons بۆ کارمەندانی بەرگریی شارستانی چییە؟",options:[{text:"بۆ فڕین لە هەوادا",correct:!1},{text:"زیادکردنی توانای جەستەیی بۆ هەڵگرتنی باری قورس و کەمکردنەوەی ماندووبوون",correct:!0},{text:"بۆ پاککردنەوەی ئاو",correct:!1},{text:"بۆ لێکۆڵینەوەی کیمیایی",correct:!1}],explanation:"ئەم جلوبەرگە میکانیکییانە هێز دەدەنە ماسولکەکانی مرۆڤ بۆ ئەوەی بتوانێت بریندار یان ئامێری قورس ئاسانتر هەڵبگرێت."},{question:"مەبەست لە بینای زیرەک (Smart Building) لە بواری سەلامەتیدا چییە؟",options:[{text:"بینایەکی جوانە",correct:!1},{text:"بینایەکە کە هەستەوەر و ئامێرەکانی بە تۆڕەوە بەستراون بۆ وەڵامدانەوەی ئۆتۆماتیکی لە بەرامبەر مەترسییەکاندا",correct:!0},{text:"بینایەکە کە تەنها لە شووشە دروست کراوە",correct:!1},{text:"بینایەکی بێ کارەبایە",correct:!1}],explanation:"لە بینا زیرەکەکاندا، سیستەمەکە خۆی مەترسییەکە دەدۆزێتەوە و بەبێ دەستێوەردانی مرۆڤ دەرگاکان دادەخات، گۆڕینی هەوا ڕادەگرێت و تیمەکان ئاگادار دەکاتەوە."},{question:"زیرەکیی دەستکرد (AI) چۆن دەتوانێت پێشبینیی کارەساتەکان بکات؟",options:[{text:"بە جادوو",correct:!1},{text:"بە شیکردنەوەی داتای گەورەی کەشوهەوا و هەستەوەرە زەمینییەکان",correct:!0},{text:"بە تەلەفۆنکردن بۆ خەڵک",correct:!1},{text:"ناتوانێت پێشبینی بکات",correct:!1}],explanation:"AI پشت بە داتاکانی ساڵانی ڕابردوو و گۆڕانکارییە نوێیەکان دەبەستێت بۆ ئەوەی دیاری بکات کە ئەگەری مەترسی لە کوێ زیاترە؛ پێشبینی ئەگەرە، نەک دڵنیاییەکی تەواو."}]},{id:11,code:"QUAKE-1100",icon:"Activity",accent:"#ea580c",title:"بوومەلەرزەناسی و ئەندازیاریی سەلامەتی",subtitle:"Seismology & Earthquake Resistant Design",summary:"شیکردنەوەی زانستیی پلێتە تەکتۆنییەکان، شەپۆلەکانی بوومەلەرزە، دیاردەی شلبوونەوەی خاک، دیزاینی بینا بەرگرەکان، و ڕێکاری Drop, Cover, Hold On لە کاتی لەرزیندا.",blocks:[{body:`عێراق و هەرێمی کوردستان لەسەر ناوچەیەکی چالاکی بوومەلەرزەن، بە تایبەتی ناوچەکانی باکوور و ڕۆژهەڵات کە نزیکی زنجیرەچیاکانی زاگرۆسن. ئەم ناوچەیە لە ئەنجامی لێکدانی پلێتی عەرەبی لەگەڵ پلێتی ئۆراسیادا دروست بووە. لەم مۆدیوولەدا، بە شێوەیەکی ئەکادیمی باسی فیزیای بوومەلەرزە و ڕێکارە ئەندازیارییەکانی پاراستنی ژیان و بیناکان دەکەین.

پاراستنی کەسی لە کاتی لەرزیندا (Drop, Cover, Hold On): لە شوێنی خۆت خۆت بدە بە زەویدا (Drop)، سەر و ملت لە ژێر مێزێکی بەهێزدا بپارێزە (Cover)، و قاچی مێزەکە بگرە تا لەرزینەکە دەوەستێت (Hold On)، دوور لە پەنجەرە و ئامێری قورس. مەچۆ ژێر چوارچێوەی دەرگا و پشت بە «سێگۆشەی ژیان» (Triangle of Life) مەبەستە؛ ئەوانە ڕێکاری پەسەندکراو نین. لە کاتی لەرزیندا بەرەو دەرەوە ڕامەکە و ئاسانسۆر بەکار مەهێنە. دوای لەرزینەکە، تەنها ئەگەر بۆنی گاز هات یان دەنگی دزەکردنت بیست، گازەکە دابخە.`},{heading:"١. میکانیزمی بوومەلەرزە و پلێتە تەکتۆنییەکان",body:"بوومەلەرزە پرۆسەیەکی فیزیاییی ئاڵۆزە کە بەپێی تیۆری «گەڕانەوەی لاستیکی» (Elastic Rebound) ڕوو دەدات:",points:["پلێتە تەکتۆنییەکان: توێکڵی زەوی لە چەند پارچەیەکی گەورە پێک دێت کە لەسەر چینێکی نەرمتر دەجووڵێن. پلێتی عەرەبی هەموو ساڵێک نزیکەی دوو سانتیمەتر بەرەو باکوور-ڕۆژهەڵات دەجووڵێت.","ناوەند و سەرناوەند: ناوەندی بوومەلەرزە (Hypocenter) ئەو خاڵەیە لە ژێر زەویدا کە وزەی لێ ئازاد دەبێت. سەرناوەند (Epicenter) ئەو خاڵەیە لەسەر ڕووی زەوی کە ڕاستەوخۆ لە سەرووی ناوەندەکەوەیە، و زۆرجار گەورەترین وێرانکاری لە نزیکییەوە ڕوو دەدات.","هێڵەکانی شکان (Faults): زانینی هێڵەکانی شکانی وەک پشتێنەی زاگرۆس (Zagros Fold-Thrust Belt) بۆ ئەندازیارانی شارستانی لە کاتی دیزاینکردنی پرۆژەکاندا زۆر پێویستە."]},{heading:"٢. شیکردنەوەی شەپۆلەکانی بوومەلەرزە (Seismic Waves)",body:"وزەی بوومەلەرزە بە شێوەی شەپۆل بڵاو دەبێتەوە، کە دابەش دەکرێن بۆ سێ جۆری سەرەکی:",points:["شەپۆلەکانی P (Primary): خێراترین شەپۆلەکانن و وەک پاڵنانێک بە ناو هەموو ماددەکاندا (ڕەق، شل و گاز) تێدەپەڕن. ئەمانە یەکەم شەپۆلن کە ئامێرە سیسمۆگرافییەکان تۆماریان دەکەن.","شەپۆلەکانی S (Secondary): هێواشترن بەڵام لەرزینەکەیان بەهێزترە. تەنها بە ناو ماددە ڕەقەکاندا تێدەپەڕن، و جووڵەکەیان ستوونییە لەسەر ئاراستەی ڕۆیشتن (بە لادا یان سەرەوە و خوارەوە)، و زیانی گەورە بە بیناکان دەگەیەنن.","شەپۆلەکانی ڕووی زەوی (Surface Waves): لەسەر ڕووی زەوی دەجووڵێن، درێژترین ماوە دەخایەنن، و بەرپرسی سەرەکین لە وێرانکاریی گەورەی شارەکان."]},{heading:"٣. پێوەرە زانستییەکان و دیاردەی شلبوونەوەی خاک",body:"بۆ دیاریکردنی هێزی بوومەلەرزە، پێویستە جیاوازی لە نێوان گەورەیی (Magnitude) و توندی (Intensity) دا بکرێت:",points:["پێوەری گەورەیی (Magnitude): ئەو وزەیە دەپێوێت کە ئازاد بووە. ئەمڕۆ پێوەری Moment Magnitude (Mw) بەکاردەهێنرێت کە جێگەی پێوەری ڕیختەری گرتووەتەوە. هەر پلەیەکی زیاتر = ١٠ هێندە گەورەیی شەپۆل لەسەر سیسمۆگراف و نزیکەی ٣٢ هێندە وزەی زیاتر.","پێوەری مێرکالیی گۆڕاو (Modified Mercalli Intensity): توندیی لەرزین بەپێی کاریگەرییەکەی لەسەر مرۆڤ و بیناکان لە هەر شوێنێکدا دەپێوێت.","شلبوونەوەی خاک (Liquefaction): لە ناوچەکانی خاکی لمی و تەڕدا، لەرزین وا دەکات خاک تایبەتمەندیی ڕەقیی خۆی لەدەست بدات و وەک شلەمەنی لێ بێت، و ئەمە دەبێتە هۆی نقومبوون یان وەرگەڕانی بیناکان."]}],media:[{kind:"video",src:"media/videos/uni_11_seismic_waves.mp4",title:"فیزیای شەپۆلەکان",description:"شیکردنەوەی جووڵەی شەپۆلەکانی P و S بە ناو زەویدا"},{kind:"image",src:"media/images/uni_11_building_design.png",title:"ئەندازیاریی دژە-لەرزین",description:"تەکنیکی جیاکردنەوەی بنچینە (Base Isolation) بۆ پاراستنی بیناکان"}],quiz:[{question:"کام جۆری شەپۆل خێراترینە و یەکەم جار دەگاتە وێستگە سیسمۆگرافییەکان؟",options:[{text:"S-Waves",correct:!1},{text:"P-Waves",correct:!0},{text:"Surface Waves",correct:!1},{text:"Love Waves",correct:!1}],explanation:"شەپۆلەکانی P (Primary) خێراترین شەپۆلەکانن و بە ناو هەموو جۆرەکانی ماددەدا تێدەپەڕن."}]},{id:12,code:"PLAN-1200",icon:"ClipboardList",accent:"#4f46e5",title:"پلاندانانی تەنگانە و ئامادەکاری",subtitle:"Emergency Planning & Family Preparedness",summary:"دانانی پلانی دەرچوونی تەنگانە بۆ خێزان و شوێنەکانی کار، و ئامادەکردنی پێداویستییە سەرەکییەکانی مانەوە.",blocks:[{body:"پلاندانان پێش هەر کارەساتێک، باشترین ڕێگایە بۆ کەمکردنەوەی ترس و پاراستنی ژیان. لەم مۆدیوولەدا، فێر دەبین چۆن پلانێکی زانستی بۆ خێزان و دامەزراوەکان دابنێین کە هەموو ئەگەرەکانی مەترسی لەخۆ بگرێت."},{heading:"١. پلانی تەنگانەی خێزان",body:"هەر خێزانێک پێویستە لەسەر پلانێکی ڕوون ڕێک بکەوێت:",points:["ڕێڕەوەکانی دەرچوون: دیاریکردنی دوو ڕێگا لە هەر ژوورێکی ماڵەکەوە، بۆ ئەوەی ئەگەر یەکێکیان گیرا، ئەوی تریان بەکاربهێنرێت.","خاڵەکانی کۆبوونەوە: دیاریکردنی دوو شوێن: یەکێکیان لە نزیک ماڵەکە، و یەکێکیان لە دەرەوەی ناوچەکە ئەگەر گەڕانەوە بۆ ماڵەکە نەگونجا.","پەیوەندیی دەرەکی: هەبوونی ژمارەی کەسێکی نزیک کە لە دەرەوەی شار دەژی، بۆ ئەوەی ببێتە خاڵی پەیوەندی لە نێوان ئەندامانی خێزاندا."]},{heading:"٢. جانتای تەنگانە (Survival Kit)",body:"پێویستە کەرەستە پێویستەکان بۆ لانیکەم ٧٢ کاتژمێر (٣ ڕۆژ) ئامادە بن:",points:["ئاو و خواردن: نزیکەی ٤ لیتر ئاو بۆ هەر کەسێک لە ڕۆژێکدا، بۆ لانیکەم ٣ ڕۆژ، لەگەڵ خواردنێک کە خراپ نابێت وەک قوتوو.","ڕووناکی و پەیوەندی: فانۆس یان چرای دەستی، پاتریی زیادە، و ڕادیۆیەکی پاتریدار بۆ گوێگرتن لە زانیارییە فەرمییەکان.","پێداویستییە پزیشکییەکان: دەرمانە تایبەتەکانی ئەندامانی خێزان و سندووقی فریاکەوتنی سەرەتایی."]}],media:[{kind:"video",src:"media/videos/uni_12_plan_making.mp4",title:"چۆنیەتیی دانانی پلان",description:"هەنگاوەکانی دروستکردنی نەخشەی دەرچوون لە بینا"}],quiz:[{question:"جانتای تەنگانە پێویستە پێداویستییەکانی خێزان بۆ لانیکەم چەند ڕۆژ دابین بکات؟",options:[{text:"١ ڕۆژ",correct:!1},{text:"٣ ڕۆژ (٧٢ کاتژمێر)",correct:!0},{text:"١ هەفتە",correct:!1},{text:"١ مانگ",correct:!1}],explanation:"ڕێنماییەکانی ئامادەکاری (وەک Ready.gov و FEMA) ئامادەکردنی پێداویستییەکانی لانیکەم ٧٢ کاتژمێر (٣ ڕۆژ) پێشنیار دەکەن، چونکە لە سەرەتای کارەساتێکی گەورەدا یارمەتی دەکرێت دوا بکەوێت."}]},{id:13,code:"FLOOD-1300",icon:"Waves",accent:"#2563eb",title:"لافاو و ڕێکارەکانی پاراستن لە ئاو",subtitle:"Flood Dynamics & Water Rescue",summary:"تێگەیشتن لە جۆرەکانی لافاو، پاراستنی ئۆتۆمبێلەکان، و بنەماکانی ڕزگارکردنی تەنگانە لە ناو ئاودا.",blocks:[{body:"لافاو یەکێکە لە بڵاوترین کارەساتەکان لە هەرێمی کوردستان. تەنها چەند سانتیمەترێک ئاوی جووڵاو دەتوانێت کارەساتی گەورە دروست بکات. لەم مۆدیوولەدا، باسی پاراستنی ژیان و ئۆتۆمبێلەکان لە کاتی بەرزبوونەوەی ئاودا دەکەین. هەرگیز بە پێ یان بە ئۆتۆمبێل مەچۆ ناو ئاوی لافاوەوە، و پەیوەندی بکە بە ١١٥."},{heading:"١. جۆرەکانی لافاو و مەترسییەکانیان",body:"لافاوەکان بەپێی خێرایی و شوێن پۆلێن دەکرێن:",points:["لافاوی لەناکاو (Flash Flood): لە ماوەی کەمتر لە ٦ کاتژمێردا دوای بارانی بەخوڕ ڕوو دەدات، و مەترسیدارترین جۆرە چونکە کاتی ئامادەکاری زۆر کەمە.","مەترسی لەسەر ئۆتۆمبێلەکان: تەنها ٣٠ سم ئاوی جووڵاو بەسە بۆ هەڵگرتن و ڕاپێچکردنی زۆربەی ئۆتۆمبێلەکان لە شوێنی خۆیان.","مەترسی لەسەر مرۆڤ: ١٥ سم ئاوی جووڵاو دەتوانێت مرۆڤ بخاتە سەر زەوی و ببێتە هۆی خنکان."]},{heading:"٢. ڕێکارەکانی ڕزگارکردن: Reach, Throw, Row, Go",body:"ئەگەر کەسێکت لە ناو ئاودا بینی، سەرەتا پەیوەندی بکە بە ١١٥، پاشان ئەم هەنگاوانە بە ڕیزبەندی جێبەجێ بکە:",points:["REACH: بە دارێک یان شتێکی درێژ بگە بە کەسەکە بەبێ ئەوەی خۆت بچیتە ناو ئاوەکەوە.","THROW: شتێک کە لەسەر ئاو دەمێنێتەوە (وەک تایەیەک یان پەتێکی بەستراو بە شتێکی سووکەوە) بۆی فڕێ بدە.","ROW: ئەگەر بەلەم و ڕاهێنان هەبوو، بۆ نزیکبوونەوەی سەلامەت بەکاری بهێنە.","GO: تەنها تیمە پسپۆڕەکان دەتوانن بچنە ناو ئاوەکەوە؛ هەرگیز وەک خۆبەخش مەچۆ ناو ئاوی لافاوەوە."]}],media:[{kind:"video",src:"media/videos/uni_13_water_safety.mp4",title:"پاراستن لە لافاو",description:"ڕێکارە دروستەکان بۆ مامەڵەکردن لەگەڵ هێزی ئاودا"}],quiz:[{question:"لانیکەم چەند سانتیمەتر ئاوی جووڵاو بەسە بۆ هەڵگرتن و ڕاپێچکردنی ئۆتۆمبێلێکی ئاسایی؟",options:[{text:"١٠ سم",correct:!1},{text:"٣٠ سم",correct:!0},{text:"١٠٠ سم",correct:!1},{text:"٥ سم",correct:!1}],explanation:"٣٠ سانتیمەتر (١٢ ئینج) ئاوی جووڵاو بەسە بۆ هەڵگرتن و ڕاپێچکردنی زۆربەی ئۆتۆمبێلەکان؛ تەنانەت ئاوێکی کەمتریش دەتوانێت ببێتە هۆی لەدەستدانی کۆنتڕۆڵی ئۆتۆمبێل."}]},{id:14,code:"GAS-1400",icon:"Fuel",accent:"#ca8a04",title:"سەلامەتیی گاز و فیزیای تەقینەوە",subtitle:"Natural Gas & LPG Advanced Safety",summary:"شیکردنەوەی چڕیی گاز بەرامبەر هەوا، سنوورەکانی تەقینەوە (LEL/UEL)، و ستراتیژییەکانی بەرگریی شارستانی بۆ کۆنتڕۆڵکردنی دزەکردنی گاز.",blocks:[{body:"گازی ئاگرگر لە پیشەسازی و ماڵەکاندا سەرچاوەیەکی سەرەکیی وزەیە، بەڵام بە کەمترین هەڵە دەتوانێت ببێتە بۆمبێکی وێرانکەر. لەم مۆدیوولەدا، باسی داینامیکی گاز دەکەین: لە چڕیی هەڵمەوە تا پلەی خۆگڕگرتن. تێگەیشتن لەم زانیارییانە بۆ هەر ئەندازیارێکی سەلامەتی پێویستە بۆ ئەوەی بتوانێت سیستەمەکانی پاراستن بەپێی ستانداردەکانی NFPA دیزاین بکات."},{heading:"١. فیزیای گاز و چڕیی هەڵم (Vapor Density)",body:"بۆ ڕێگرتن لە کۆبوونەوەی گاز، پێویستە بزانیت کە گازەکە لە هەوا سووکترە یان قورسترە (هەوا = ١):",points:["گازی سروشتی (Methane): لە هەوا سووکترە (نزیکەی ٠.٥٥). ئەگەر دزەی کرد، بەرەو سەرەوە دەچێت و لە ژێر بنمیچدا کۆ دەبێتەوە؛ بۆیە هەواگۆڕکێ لە شوێنە بەرزەکاندا پێویستە.","گازی LPG (Propane/Butane): لە هەوا قورسترە (نزیکەی ١.٥ تا ٢). لە کاتی دزەکردندا، وەک ئاو لەسەر زەوی و شوێنە نزمەکاندا (ژێرزەمین، چاڵ) کۆ دەبێتەوە. ئەمە زۆر مەترسیدارە چونکە دەتوانێت بگاتە پریشکی سویچ و ئامێرە نزمەکان.","بۆندارکردنی گاز (Mercaptan): گازی پاک بێبۆنە، بۆیە کۆمپانیاکان ماددەی مێرکاپتان (وەک Ethyl Mercaptan) تێکەڵ دەکەن بۆ ئەوەی مرۆڤ بە بۆن هەست بە مەترسییەکە بکات."]},{heading:"٢. سنوورەکانی تەقینەوە (Flammability Limits - LEL/UEL)",body:"گاز تەنها کاتێک دەتەقێتەوە کە ڕێژەکەی لە هەوادا لە نێوان دوو سنووردا بێت:",points:["سنووری خوارەوە (LEL): کەمترین ڕێژەی گاز لە هەوادا کە دەتوانێت گڕ بگرێت. ئەگەر گاز لەمە کەمتر بێت، تەقینەوە ڕوو نادات.","سنووری سەرەوە (UEL): بەرزترین ڕێژەی گاز؛ ئەگەر گاز لەمە زیاتر بێت، ئۆکسجین بەس نییە و تەقینەوە ڕوو نادات (بەڵام کاتێک لەگەڵ هەوادا تێکەڵ دەبێت و دەگاتە نێوان هەردوو سنوورەکە، دەتوانێت گڕ بگرێت).","مەترسیی خنکان: کۆبوونەوەی گاز لە شوێنە داخراوەکاندا جێگەی ئۆکسجین دەگرێتەوە و دەتوانێت ببێتە هۆی مردنێکی بێدەنگ (Asphyxiation)."]},{heading:"٣. ڕێکارە تەکنیکییەکانی تەنگانە",body:"لە کاتی هەستکردن بە دزەکردنی گازدا، بەرگریی شارستانی ئەم ڕێسایانە پەیڕەو دەکات:",points:["قەدەغەکردنی پریشک: هەڵکردنی سویچی کارەبا، بەکارهێنانی تەلەفۆن یان هەر ئامێرێکی کارەبایی لە ناو شوێنەکەدا، یان هەر گڕێکی ئاشکرا، دەتوانێت وزەی پێویست بۆ تەقینەوە دابین بکات.","جێبەجێکردن: کردنەوەی دەرگا و پەنجەرەکان (بەبێ هەڵکردنی پانکە کارەباییەکان)، داخستنی ڤاڵڤی سەرەکی ئەگەر بە سەلامەتی بگونجێت، دەرهێنانی خەڵک بەبێ ژاوەژاو، و پەیوەندیکردن بە ١١٥ لە دەرەوەی شوێنەکە."]}],media:[{kind:"video",src:"media/videos/gov_14_gas_physics.mp4",title:"داینامیکی تەقینەوەی گاز",description:"شیکردنەوەی تاقیگەیی لەسەر سنوورەکانی LEL و UEL"},{kind:"image",src:"media/images/gov_14_gas_detectors.png",title:"هەستەوەرە پیشەسازییەکان",description:"جۆرەکانی ئامێری دۆزینەوەی دزەکردنی گاز لە کارگەکاندا"}],quiz:[{question:"بۆچی گازی LPG لە کاتی دزەکردندا لەسەر زەوی کۆ دەبێتەوە؟",options:[{text:"چونکە ساردە",correct:!1},{text:"چونکە لە هەوا قورسترە",correct:!0},{text:"چونکە بۆنێکی تیژی هەیە",correct:!1},{text:"چونکە گازی سروشتییە",correct:!1}],explanation:"LPG لە هەوا قورسترە (Vapor Density > 1)، بۆیە بەرەو خوارەوە دەچێت و لە شوێنە نزمەکاندا کۆ دەبێتەوە."}]},{id:15,code:"PLAN-1500",icon:"Landmark",accent:"#4f46e5",title:"پلاندانانی ستراتیژیی تەنگانە",subtitle:"Institutional Emergency & Continuity Planning",summary:"دانانی پلانەکانی دەرچوون بۆ دامودەزگا حکومییەکان، بەڕێوەبردنی قەیرانەکان، و دڵنیابوونەوە لە بەردەوامیی کارەکان.",blocks:[{body:"پلاندانان پێش کارەسات، جیاوازیی نێوان سەرکەوتن و کارەسات دیاری دەکات. ئەم مۆدیوولە بۆ بەڕێوەبەران و ئەفسەرانی بەرگریی شارستانی ئامادە کراوە، بۆ ئەوەی بزانن چۆن «پلانی وەڵامدانەوەی تەنگانە» (Emergency Response Plan - ERP) بۆ بینا حکومی و بازرگانییەکان دابنێن."},{heading:"١. توخمە سەرەکییەکانی پلانی ERP",body:"هەر پلانێکی باش پێویستە ئەم سێ بەشەی تێدا بێت:",points:["ستراتیژیی دەرچوون (Evacuation): نەخشەکێشانی ڕێڕەوەکانی دەرچوون و دڵنیابوونەوە لەوەی هیچ ڕێگرییەک لە ڕێگای خەڵک و تیمەکانی تەنگانەدا نییە.","خاڵەکانی کۆبوونەوە (Assembly Points): دیاریکردنی شوێنی سەلامەت لە دەرەوەی بینا، دوور لە بینا و ڕێگای ئۆتۆمبێلەکانی تەنگانە، کە لە پشکنینی ئەندازیاریدا پەسەند کرابن.","زنجیرەی فەرماندەیی (Chain of Command): دیاریکردنی بەرپرسیارێتییەکان: کێ فەرمانی دەرچوون دەدات و کێ پەیوەندی بە تیمە دەرەکییەکانەوە (١١٥ و ١٢٢) دەکات."]},{heading:"٢. کەرەستەکانی مانەوە و سەرچاوە بەردەوامەکان (Survival Logistics)",body:"ئامادەکردنی کەرەستەکانی ژیان بۆ یەکەم خولەکەکانی ڕووداو و بۆ یەکەم ٧٢ کاتژمێری کارەساتێکی گەورە:",points:["کەرەستە پزیشکییەکان: سندووقی برین (Trauma Kit) کە کەرەستەکانی ڕاگرتنی خوێنبەربوونی مەترسیداری (وەک تۆرنیکێت و گازی پڕکردنەوە) تێدا بێت.","پەیوەندیی یەدەگ: ڕادیۆی VHF/UHF و تەلەفۆنی مانگی دەستکرد (Satellite) بۆ کاتی پچڕانی تۆڕەکانی پەیوەندی.","سەرچاوە سەرەکییەکان: ئامادەکردنی ئاو و وزەی پاتری یان مۆلیدە بۆ تیمە کارگێڕییەکان لە کاتی مانەوە لە ناوچەی کارەساتەکەدا."]}],media:[{kind:"video",src:"media/videos/gov_15_emergency_drills.mp4",title:"ڕاهێنانە مەیدانییەکان",description:"چۆنیەتیی ئەنجامدانی ڕاهێنانەکانی دەرچوون لە فەرمانگەکاندا"}],quiz:[{question:"ئامانجی سەرەکی لە خاڵەکانی کۆبوونەوە (Assembly Points) چییە؟",options:[{text:"بۆ نیشاندانی جوانیی بیناکە",correct:!1},{text:"بۆ هەژمارکردنی کارمەندان و دڵنیابوونەوە لە سەلامەتیی هەموو کەسێک",correct:!0},{text:"بۆ کۆکردنەوەی پاشماوەکان",correct:!1},{text:"بۆ ڕاگرتنی ئۆتۆمبێلەکان",correct:!1}],explanation:"خاڵەکانی کۆبوونەوە بەکاردەهێنرێن بۆ ئەوەی بزانرێت کە هەموو کەس لە بیناکە دەرچوون یان کەسێک لە ناو مەترسیدا ماوەتەوە."}]},{id:16,code:"SAR-1600",icon:"Construction",accent:"#16a34a",title:"گەڕان و ڕزگارکردنی پێشکەوتوو (USAR)",subtitle:"Urban Search and Rescue & Structural Collapse",summary:"تەکنیکەکانی ڕزگارکردن لە ژێر داروپەردووی ڕووخاو، سیستەمی نیشانەکردنی INSARAG، و بەکارهێنانی ئامێرەکانی گوێگرتن و گەڕان.",blocks:[{body:"گەڕان و ڕزگارکردن لە شارەکاندا (Urban Search and Rescue - USAR) کارێکی هەستیار و مەترسیدارە. دوای بوومەلەرزە یان ڕووخانی بینا بەرزەکان، تیمە پسپۆڕەکان پێویستیان بە زانیاریی ئەندازیاری هەیە بۆ ئەوەی بزانن پارچە کۆنکریتییەکان چۆن دەجووڵێن. ئەم مۆدیوولە بەپێی ڕێنماییە نێودەوڵەتییەکانی INSARAG ئامادە کراوە."},{heading:"١. قۆناغەکانی ڕزگارکردن (Phases of Rescue)",body:"پرۆسەی ڕزگارکردن بەم ڕیزبەندییە ئەنجام دەدرێت:",points:["پشکنینی گشتی (Size-up / Reconnaissance): هەڵسەنگاندنی ئاستی زیان، جێگیریی بیناکە و مەترسییەکانی وەک گاز و کارەبا.","ڕزگارکردن لەسەر ڕوو (Surface Rescue): دەرهێنانی ئەو کەسانەی بەرچاون و بە ئاسانی دەتوانین پێیان بگەین.","گەڕان لە بۆشاییەکاندا (Void Space Search): دۆزینەوەی بریندارەکان لە ناو کون و بۆشاییەکانی بینا ڕووخاوەکاندا بە کامێرای ورد و ئامێرەکانی گوێگرتن.","لابردنی هەڵبژێردراوی داروپەردوو (Selected Debris Removal): لابردنی پارچە دیاریکراوەکان بە وردی و بە ئامرازی دەستی و هایدرۆلیکی بۆ گەیشتن بە بریندارەکان؛ پاشان لابردنی گشتیی داروپەردوو بە ئامێری قورس."]},{heading:"٢. سیستەمی نیشانەکردنی نێودەوڵەتی (INSARAG Marking)",body:"تیمەکانی USAR نیشانەی ستاندارد لەسەر دیواری بیناکان دادەنێن بۆ ئەوەی زانیاری بۆ ئەو تیمانەی دوای خۆیان بەجێ بهێڵن:",points:["نیشانەی شوێنی کار (Worksite Marking): بەپێی INSARAG، تیمەکە ناسنامەی شوێنی کارەکە (پیتی ناوچە و ژمارەی شوێنی کار، وەک C-6) لەسەر بیناکە دەنووسێت بۆ ئەوەی هەموو تیمەکان بە یەک ناو بیناسن. سیستەمی X ی چوار-بەشی (ناوی تیم، کات و بەروار، مەترسی، قوربانی) سیستەمی FEMA یە لە ئەمریکا.","نیشانەی قوربانییەکان (Victim Marking): پیتی گەورەی (V) لە نزیک شوێنی قوربانییەکی ئەگەری یان پشتڕاستکراو دەنووسرێت؛ لە ژێریدا، (L) لەگەڵ ژمارەیەک بۆ کەسە زیندووەکان و (D) لەگەڵ ژمارەیەک بۆ مردووەکان. کاتێک قوربانییەکە دەردەهێنرێت، هێڵ بەسەر نیشانەکەدا دەکێشرێت."]}],media:[{kind:"video",src:"media/videos/gov_16_search_tech.mp4",title:"تەکنەلۆجیای گەڕان",description:"بەکارهێنانی ئامێرەکانی گوێگرتن و ڕادار بۆ دۆزینەوەی دەنگ و جووڵەی بریندارەکان لە ژێر داروپەردوودا"},{kind:"image",src:"media/images/gov_16_marking_standard.png",title:"ڕێنماییەکانی INSARAG",description:"چۆنیەتیی نووسینی زانیاری لەسەر بینا ڕووخاوەکان"}],quiz:[{question:"بەپێی INSARAG، پیتی (L) لە ژێر نیشانەی (V) لەسەر دیواری بیناکە نیشانەی چییە؟",options:[{text:"دزەکردنی گاز",correct:!1},{text:"بوونی کەسی زیندوو (Live)",correct:!0},{text:"ڕووخانی تەواو",correct:!1},{text:"کۆتاییهاتنی پشکنین",correct:!1}],explanation:"L کورتکراوەی Live ە؛ لەگەڵ ژمارەیەکدا نیشان دەدات کە چەند قوربانیی زیندووی پشتڕاستکراو لەو شوێنەدا هەن."}]},{id:17,code:"TRAFFIC-1700",icon:"CarFront",accent:"#dc2626",title:"ڕووداوەکانی هاتوچۆ و دەرهێنانی تەکنیکی",subtitle:"Advanced Vehicle Extrication & Road Safety",summary:"مامەڵەکردن لەگەڵ ڕووداوە توندەکانی هاتوچۆ، بەکارهێنانی ئامێرە هایدرۆلیکییەکان (Jaws of Life)، و پاراستنی بڕبڕەی پشت.",blocks:[{body:"ڕووداوەکانی هاتوچۆ یەکێکن لە سەرەکیترین کارە ڕۆژانەکانی بەرگریی شارستانی. لەم مۆدیوولەدا، باسی قۆناغەکانی دەرهێنانی بریندارەکان لە ناو ئۆتۆمبێلەکانەوە دەکەین، بەبێ ئەوەی زیانی زیاتر بە بڕبڕەی پشت و مل بگات. لە هەموو ڕووداوێکدا کە بریندار هەبێت، پەیوەندی بکە بە ١١٥ و ١٢٢."},{heading:"١. سەلامەتیی شوێنی ڕووداو (Scene Safety)",body:"پێش هەر دەستێوەردانێک، پێویستە شوێنی ڕووداوەکە سەلامەت بکرێت:",points:["ناوچەی ئاگادارکردنەوە: دیاریکردنی ناوچەی مەترسی (Danger Zone) و دانانی نیشانە و قووچەکەکانی هاتوچۆ پێش شوێنی ڕووداوەکە بە مەودایەکی گونجاو لەگەڵ خێرایی ڕێگاکەدا، و هەماهەنگی لەگەڵ پۆلیسی هاتوچۆ (١٠٤).","جێگیرکردنی ئۆتۆمبێل (Vehicle Stabilization): بەکارهێنانی پارچەی دار یان پاڵپشت (Cribbing/Blocks) لە ژێر ئۆتۆمبێلەکە و لە پێش و پشتی تایەکاندا بۆ ئەوەی لە کاتی کارکردندا نەجووڵێت.","پچڕاندنی وزە: پچڕاندنی وایەری نێگەتیڤی پاترییەکە بۆ کەمکردنەوەی مەترسیی ئاگر و تەقینەوەی نەخوازراوی کیسە هەواییەکان (Airbags). تێبینی: کیسە هەواییەکان دەتوانن دوای پچڕاندنی پاترییەکەش بۆ ماوەیەکی کورت ئامادە بمێننەوە، و ئۆتۆمبێلە هایبرید و کارەباییەکان سیستەمی ڤۆڵتیەی بەرزیان هەیە."]},{heading:"٢. تەکنیکەکانی دەرهێنان بە «Jaws of Life»",body:"بەکارهێنانی هێزی هایدرۆلیکی بۆ گۆڕینی شێوەی لاشەی ئۆتۆمبێلەکە:",points:["بڕین (Cutting): بڕینی کۆڵەکەکانی (A, B, C)ی ئۆتۆمبێلەکە بۆ ئەوەی سەقفەکە بە تەواوی لاببرێت.","کردنەوە (Spreading): کردنەوەی دەرگا چەماوەکان و دروستکردنی بۆشایی بۆ تیمە پزیشکییەکان.","پاراستنی مل: پێش هەر جووڵەیەک، سەری بریندارەکە بە دەست جێگیر بکە (Manual In-line Stabilization)، و ئەگەر پێویست بوو بەپێی پرۆتۆکۆڵی پزیشکی پشتێنی مل (C-Collar) بەکاربهێنە."]}],media:[{kind:"video",src:"media/videos/gov_17_extrication_tech.mp4",title:"دەرهێنانی تەکنیکی",description:"شێوازی بڕینی ئاسن بە ئامێرە هایدرۆلیکییەکان"},{kind:"image",src:"media/images/gov_17_airbag_safety.png",title:"سەلامەتیی Airbag",description:"مەترسییەکانی تەقینەوەی نەخوازراوی کیسەی هەوا لە کاتی ڕزگارکردندا"}],quiz:[{question:"بۆچی جێگیرکردنی ئۆتۆمبێل (Stabilization) یەکەم هەنگاوە پێش دەرهێنانی بریندار؟",options:[{text:"بۆ جوانی",correct:!1},{text:"بۆ ئەوەی ئۆتۆمبێلەکە نەجووڵێت و برینەکانی مل و پشتی بریندارەکە خراپتر نەبن",correct:!0},{text:"بۆ پاککردنەوەی شەقامەکە",correct:!1},{text:"هیچ گرنگییەکی نییە",correct:!1}],explanation:"هەر جووڵەیەکی ئۆتۆمبێلەکە لە کاتی بڕینی ئاسندا، دەتوانێت زیان بە بڕبڕەی پشت بگەیەنێت و ببێتە هۆی پەککەوتنی هەمیشەیی بریندارەکە."}]},{id:18,code:"IND-1800",icon:"Factory",accent:"#4b5563",title:"سەلامەتیی پیشەسازی و کارگەکان",subtitle:"Industrial Safety & Factory Risk Management",summary:"ڕێگرتن لە ڕووداوە پیشەسازییەکان، ستانداردەکانی سەلامەتیی کار (OSHA)، و سیستەمی LOTO بۆ قفڵکردنی وزە.",blocks:[{body:"کارگە و ناوچە پیشەسازییەکان پڕن لە مەترسیی ئاڵۆز. بەپێی ستانداردەکانی سەلامەتیی کار (وەک OSHA لە ئەمریکا و ستانداردی نێودەوڵەتیی ISO 45001)، هەر دامەزراوەیەک پێویستە سیستەمێکی هەڵسەنگاندنی مەترسییەکانی (Risk Assessment) هەبێت. ئەم مۆدیوولە فێرت دەکات چۆن ژینگەیەکی کاری سەلامەت بەپێی بنەما ئەندازیارییەکان دابین بکەیت."},{heading:"١. سیستەمی LOTO (Lockout / Tagout)",body:"ستانداردی سەلامەتی لە کاتی چاککردنەوەی ماشینەکاندا (OSHA 1910.147):",points:["Lockout: قفڵکردنی فیزیکیی سویچی سەرەکیی کارەبا یان ڤاڵڤی پەستان.","Tagout: دانانی کارتێکی ئاگادارکردنەوە بە ناوی ئەو کەسەی کار دەکات، بۆ ئەوەی هیچ کەسێک ماشینەکە هەڵنەکات.","Zero Energy State: دڵنیابوونەوە لەوەی هیچ وزەیەک (کارەبا، پەستان، گەرما یان وزەی میکانیکی) لە سیستەمەکەدا نەماوە پێش دەستپێکردنی کار."]},{heading:"٢. پاراستنی ماشینەکان و کەرەستەکانی PPE",body:"ڕێگرتن لە بەرکەوتنی لەش لەگەڵ پارچە جووڵاوەکاندا:",points:["Machine Guarding: دانانی بەربەستی ئاسنین لە دەوروبەری قایش و چەرخە تیژەکانی ماشینەکاندا.","کەرەستەکانی پاراستن: بەکارهێنانی پێڵاوی سەر-ئاسن (Steel-toe)، دەستکێشی دژە-ترش (ئەسید)، و پاراستنی گوێ لەو شوێنانەی کە دەنگ بە تێکڕایی لە ٨٥ دیسیبێل (dBA) لە ماوەی ٨ کاتژمێردا بەرزترە."]}],media:[{kind:"video",src:"media/videos/gov_18_loto_training.mp4",title:"پرۆتۆکۆڵی LOTO",description:"چۆنیەتیی جێبەجێکردنی قفڵکردنی وزە لە کارگەکاندا"},{kind:"image",src:"media/images/gov_18_ppe_factory.png",title:"کەرەستەکانی PPE",description:"لیستی پێداویستییەکانی پاراستن بۆ کارمەندانی پیشەسازی"}],quiz:[{question:"مەبەست لە «Zero Energy State» لە کاری چاککردنەوەی ماشینەکاندا چییە؟",options:[{text:"بەکارهێنانی کارەبایەکی کەم",correct:!1},{text:"دڵنیابوونەوە لە نەمانی هەر وزەیەکی ماوە لە ماشینەکەدا، بۆ ئەوەی نەتەقێتەوە و نەجووڵێت",correct:!0},{text:"کارنەکردنی ماشینەکە بە شەو",correct:!1},{text:"هیچ کامێک لەمانە",correct:!1}],explanation:"پێویستە هەموو پەستان و کارەبای هەڵگیراو (لە پاتری و کەپاسیتەرەکاندا) بەتاڵ بکرێتەوە بۆ ئەوەی ماشینەکە لە کاتی چاککردنەوەدا بە شێوەیەکی نەخوازراو کار نەکات."}]},{id:19,code:"HIGH-1900",icon:"Building",accent:"#2563eb",title:"کوژاندنەوەی ئاگر لە باڵەخانە بەرزەکاندا",subtitle:"High-Rise Fire Dynamics & Standpipe Operations",summary:"تایبەتمەندییە فیزیاییەکانی ئاگر لە بینا بەرزەکاندا، سیستەمەکانی Standpipe، دیاردەی Stack Effect، و ستراتیژییەکانی دەرچوون.",blocks:[{body:"باڵەخانە بەرزەکان (High-Rise Buildings) ئاستەنگێکی گەورەن بۆ تیمەکانی کوژاندنەوەی ئاگر، چونکە گەیشتن بە نهۆمەکانی سەرەوە بە پەیژەی ئۆتۆمبێلەکان زۆرجار ناگونجێت. لەم مۆدیوولەدا، باسی داینامیکی هەوا لە بینا بەرزەکاندا و چۆنیەتیی بەکارهێنانی سیستەمە ناوخۆییەکانی ئاو بۆ کوژاندنەوەی ئاگر لە بەرزیی زیاتر لە ٢٣ مەتر (٧٥ پێ) دەکەین."},{heading:"١. دیاردەی Stack Effect و جووڵەی دووکەڵ",body:"لە بینا بەرزەکاندا، جیاوازیی پلەی گەرما لە نێوان ناوەوە و دەرەوەی بیناکەدا جووڵەیەکی هەوا دروست دەکات کە پێی دەوترێت Stack Effect:",points:["Stack Effect: لە زستاندا، هەوای گەرمی ناو بیناکە بەرەو سەرەوە دەچێت و دووکەڵ بە خێرایی لە ناو پلیکانە و بۆشاییەکانی ئاسانسۆردا بڵاو دەکاتەوە.","Reverse Stack Effect: لە هاویندا، هەوای ساردی ساردکەرەوەکان لە بۆشاییە ستوونییەکاندا بەرەو خوارەوە دەچێت و دەتوانێت دووکەڵ بەرەو نهۆمەکانی خوارەوە ببات.","دیاردەی Mushrooming: کاتێک دووکەڵ دەگاتە سەرەوەی بیناکە یان شوێنێکی داخراو، بە ئاسۆیی بڵاو دەبێتەوە و پاشان بەرەو خوارەوە دەگەڕێتەوە و نهۆمەکانی سەرەوە پڕ دەکات."]},{heading:"٢. ئەندازیاریی سیستەمی Standpipe و FDC",body:"چونکە ئۆتۆمبێلەکانی کوژاندنەوەی ئاگر ناتوانن بە ئاسانی ئاو بگەیەننە نهۆمە زۆر بەرزەکان، پشت بە سیستەمی بۆریی جێگیر (NFPA 14) دەبەسترێت:",points:["Class I System: دەرچەی ئاوی ٢.٥ ئینجی کە تەنها تیمەکانی کوژاندنەوەی ئاگر بەکاری دەهێنن، لەگەڵ لوولەکانی خۆیان.","Fire Department Connection (FDC): ئەو گرێدانەیەیە لە دەرەوەی بیناکە کە ئۆتۆمبێلی کوژاندنەوەی ئاگر ئاوی پێدا پاڵ دەنێت بۆ ئەوەی پەستانی سیستەمەکە بۆ نهۆمە بەرزەکان زیاد بکات.","Pressure Regulating Valves: ڤاڵڤەکانی ڕێکخستنی پەستان بۆ ئەوەی پەستانی زیادەی ئاو لە نهۆمەکانی خوارەوەدا نەبێتە مەترسی بۆ ئاگرکوژەکان و لوولەکان."]},{heading:"٣. پرۆتۆکۆڵەکانی دەرچوون و Elevator Recall",body:"بەڕێوەبردنی خەڵک لە بینا بەرزەکاندا پێویستی بە پلانی ورد هەیە بۆ پاراستنی ژیان:",points:["ئاسانسۆر بەکار مەهێنە: لە کاتی ئاگردا، ئاسانسۆرەکان دەچنە دۆخی (Phase I Recall) و دەچنە نهۆمی سەرەکی و دەوەستن بۆ ئەوەی خەڵک تێیاندا گیر نەخوات؛ پاشان تەنها ئاگرکوژەکان دەتوانن بە دۆخی (Phase II) بەکاریان بهێنن.","دەرچوونی قۆناغ بە قۆناغ (Phased Evacuation): سەرەتا دەرهێنانی خەڵکی نهۆمی ئاگرەکە و ئەو نهۆمانەی ڕاستەوخۆ لە سەرەوە و خوارەوەیدان، پاشان نهۆمەکانی تر بە ڕیزبەندی.","شوێنەکانی پەناگرتن (Area of Refuge): شوێنی پارێزراو لە نهۆمەکاندا بۆ ئەو کەسانەی پێداویستیی تایبەتیان هەیە و ناتوانن بە پلیکانەدا دابەزن."]}],media:[{kind:"video",src:"media/videos/uni_19_highrise_tactics.mp4",title:"تاکتیکەکانی بینا بەرزەکان",description:"چۆنیەتیی کوژاندنەوەی ئاگر لە نهۆمە زۆر بەرزەکاندا"},{kind:"image",src:"media/images/uni_19_standpipe_diagram.png",title:"دیاگرامی Standpipe",description:"شیکردنەوەی سیستەمی بۆرییەکانی ئاو لە ناو بیناکەدا"}],quiz:[{question:"دیاردەی Stack Effect لە باڵەخانە بەرزەکاندا بە چ هۆیەک دروست دەبێت؟",options:[{text:"بەهۆی تێکچوونی کارەباوە",correct:!1},{text:"بەهۆی جیاوازیی پلەی گەرما لە نێوان ناوەوە و دەرەوەی بیناکەدا",correct:!0},{text:"بەهۆی کەمیی ئاوەوە",correct:!1},{text:"تەنها بەهۆی بەرزیی باڵەخانەکەوە",correct:!1}],explanation:"Stack Effect بەهۆی جیاوازیی گەرما و چڕیی هەواوە دروست دەبێت، و هەوا لە ناو بۆشاییە ستوونییەکاندا (پلیکانە و ئاسانسۆر) بەرەو سەرەوە یان خوارەوە دەجووڵێنێت."}]},{id:20,code:"WILD-2000",icon:"TreePine",accent:"#ea580c",title:"کوژاندنەوەی ئاگر لە دارستان و دەشتەکاندا",subtitle:"Wildfire Dynamics & Vegetation Fire Safety",summary:"داینامیکی ئاگری دارستانەکان، کاریگەریی کەشوهەوا، دیزاینی ناوچەی پاراستن (Defensible Space)، و تەکنیکەکانی هێڵی ڕاگرتنی ئاگر (Firebreak).",blocks:[{body:"ئاگری دارستان و دەشتەکان (Wildfires) مەترسییەکی جیاوازن چونکە کەشوهەوا و ئاراستەی با ڕاستەوخۆ کاریگەرییان لەسەر دەکەن. لە هەرێمی کوردستان، ئاگرەکانی هاوین هەموو ساڵێک زیان بە کێڵگەکانی گەنم و دارستانەکان دەگەیەنن. لەم مۆدیوولەدا، باسی ستراتیژییە زانستییەکانی ڕێگرتن و کوژاندنەوەی ئەم ئاگرانە دەکەین."},{heading:"١. سێگۆشەی ڕەفتاری ئاگری دارستان (Fire Behavior Triangle)",body:"ڕەفتاری ئاگر لە دەرەوە پشت بە سێ هۆکاری سەرەکی دەبەستێت:",points:["سووتەمەنی (Fuel): جۆری دار و گیای وشک و ڕێژەی شێی تێیاندا، کە دیاری دەکات ئاگر بە چ توندییەک بڵاو دەبێتەوە.","شێوەی زەوی (Topography): ئاگر لەسەر لێژاییەکان بەرەو سەرەوە زۆر خێراتر دەڕوات، چونکە گەرما و گڕ بەرەو سەرەوە دەچن و سووتەمەنیی سەرەوە پێشوەخت گەرم دەکەن.","کەشوهەوا (Weather): پلەی گەرما، بای توند و کەمیی شێ سێ هۆکاری سەرەکیی بڵاوبوونەوەی ئاگرن."]},{heading:"٢. جۆرەکانی ئاگری دارستان",body:"ئاگر بەپێی ئاستی سووتان دابەش دەکرێت:",points:["ئاگری ڕووی زەوی (Surface Fire): سووتانی گیا و گەڵای سەر زەوی، کە کۆنتڕۆڵکردنی ئاسانترە.","ئاگری لووتکەی دارەکان (Crown Fire): مەترسیدارترین جۆرە؛ کاتێک ئاگر دەگاتە لووتکەی دارەکان و بە هێزی با بە خێراییەکی زۆر گەورە بڵاو دەبێتەوە.","پریشکی فڕیو (Spotting): کاتێک پشکۆ و پریشکی ئاگر بە با دەفڕن و لە شوێنی دوورتر (هەندێک جار چەند کیلۆمەتر) ئاگری نوێ دروست دەکەن."]},{heading:"٣. ستراتیژیی پاراستن: Defensible Space",body:"بۆ پاراستنی گوند و بیناکانی نزیک دارستانەکان، بەپێی ڕێنماییەکانی CAL FIRE سێ ناوچە دیاری دەکرێن:",points:["Zone 0 (٠–١.٥ مەتر): ناوچەی بێ سووتەمەنی؛ نابێت هیچ دار، گیای وشک یان کەلوپەلی ئاگرگر لە تەنیشت دیوارەکەوە هەبێت.","Zone 1 (١.٥–٩ مەتر): کەمکردنەوەی چڕیی دارەکان، پاککردنەوەی بەردەوامی گەڵا وشکەکان، و دوورخستنەوەی دارەکان لە یەکتر.","Zone 2 (٩–٣٠ مەتر): کەمکردنەوەی سووتەمەنی و لابردنی لقە خوارەوەکانی دارەکان، بۆ ئەوەی ئاگر لە زەوییەوە نەگاتە لووتکەی دارەکان (Ladder Fuels)."]}],media:[{kind:"video",src:"media/videos/uni_20_wildfire_behavior.mp4",title:"ڕەفتاری ئاگر لە چیاکاندا",description:"چۆنیەتیی بڵاوبوونەوەی ئاگر بەپێی ئاراستەی با و لێژاییەکان"},{kind:"image",src:"media/images/uni_20_defensible_space.png",title:"نەخشەی پاراستن",description:"دیاریکردنی ناوچەکانی سەلامەتی لە دەوروبەری ماڵەکاندا"}],quiz:[{question:"بۆچی ئاگر لەسەر لێژاییەکانی چیا خێراتر بڵاو دەبێتەوە لە زەویی تەخت؟",options:[{text:"چونکە دار لەوێ زیاترە",correct:!1},{text:"چونکە گەرما و گڕ بەرەو سەرەوە دەچن و سووتەمەنیی سەرەوە پێشوەخت گەرم دەکەن",correct:!0},{text:"چونکە بای سەر چیا ساردە",correct:!1},{text:"هیچ جیاوازییەک نییە",correct:!1}],explanation:"بەپێی یاساکانی فیزیا، گەرما بەرەو سەرەوە دەچێت؛ بۆیە تا لێژایی (Slope) توندتر بێت، خێرایی بڵاوبوونەوەی ئاگر بەرەو سەرەوە زیاتر دەبێت."}]},{id:21,code:"WATER-2100",icon:"LifeBuoy",accent:"#0891b2",title:"ڕزگارکردن لە ئاو و هایدرۆلۆجیی لافاوەکان",subtitle:"Advanced Water Rescue & Drowning Prevention",summary:"شیکردنەوەی هێزی هایدرۆلیکیی ئاو، تەکنیکەکانی ڕزگارکردنی تەنگانە، و ڕێگرتن لە خنکان.",blocks:[{body:"خنکان (Drowning) یەکێکە لە سەرەکیترین هۆکارەکانی مردن لە کاتی گەشت و کارەساتەکاندا. تێگەیشتن لە هێزی ئاو و چۆنیەتیی کارکردنی لەش لە ژێر ئاودا (Mammalian Dive Reflex) بۆ تیمەکانی ڕزگارکردن زۆر گرنگە. لەم مۆدیوولەدا، باسی زانستی ڕزگارکردن لە ئاو و پرۆتۆکۆڵەکانی پاراستن دەکەین. لە هەر ڕووداوێکی ئاودا، پەیوەندی بکە بە ١١٥ و ١٢٢."},{heading:"١. فیزیای ئاوی خێرا (Swiftwater Hydrology)",body:"ئاوی خێرا هێزێکی زۆر گەورە دروست دەکات کە مرۆڤ ناتوانێت لە بەرامبەریدا خۆڕاگری بکات:",points:["هێزی ئاو: ئەگەر خێرایی ئاو دوو هێندە ببێت، هێزەکەی لەسەر لەش یان ئۆتۆمبێل چوار هێندە زیاد دەبێت.","پاڵێوەرەکان (Strainers): ڕێگرییەکانی وەک لقی دار یان تۆڕ لە ناو ئاودا کە ئاو پێیاندا تێدەپەڕێت بەڵام شتە ڕەقەکان (وەک مرۆڤ) دەگرن، و ئەمە دەبێتە هۆی خنکانێکی خێرا.","ئاوی گەڕاوە (Eddies): ناوچە ئارامەکانی پشت بەردە گەورەکان کە تیمەکانی ڕزگارکردن بۆ پشوودان و نزیکبوونەوە بەکاریان دەهێنن."]},{heading:"٢. ڕێسا زێڕینەکانی ڕزگارکردن لە ئاو",body:"بۆ پاراستنی ژیانی ڕزگارکەر، پێویستە ئەم ڕیزبەندییە بپارێزرێت:",points:["REACH: بەکارهێنانی دارێک یان پەیژەیەک بەبێ ئەوەی خۆت بچیتە ناو ئاوەکەوە.","THROW: فڕێدانی پەتێک یان شتێک کە لەسەر ئاو دەمێنێتەوە (وەک تایەیەک).","ROW: بەکارهێنانی بەلەم بۆ نزیکبوونەوە لە بریندارەکە.","GO: دوایین هەڵبژاردنە و تەنها بۆ پسپۆڕە ڕاهێنراوەکانە کە جلی مانەوە لەسەر ئاو (PFD) لەبەر دەکەن.","HELO: بەکارهێنانی هەلیکۆپتەر لە لافاوە گەورەکاندا لەلایەن تیمە تایبەتەکانەوە."]},{heading:"٣. فریاکەوتنی سەرەتایی بۆ کەسانی خنکاو",body:"ئەگەر کەسێک لە ئاو دەرهێنرا، هەر چرکەیەک گرنگە:",points:["هەناسەدان: خنکان لە بنەڕەتدا کێشەیەکی کەمیی ئۆکسجینە؛ ئەگەر کەسەکە بێهۆش بوو و هەناسەی ئاسایی نەبوو، CPR دەست پێ بکە و هەناسەی ڕزگارکردن (Rescue Breaths) زیاد بکە ئەگەر ڕاهێنراو بیت (بەپێی ERC، بە ٥ هەناسەی سەرەتایی).","ساردبوونەوەی لەش (Hypothermia): زۆرجار ئەو کەسانەی لە ئاو دەردەهێنرێن تووشی ساردبوونەوەی لەش دەبن؛ جلە تەڕەکانیان دابکەنە و بە هێواشی گەرمیان بکەرەوە.","تێکچوونی دواکەوتووی سییەکان: هەر کەسێک لە ئاو دەرهێنرابێت و کۆکە، هەناسەتەنگی یان سەرگێژخواردنی هەبێت، پێویستە لەلایەن پزیشکەوە بپشکنرێت، چونکە تێکچوونی سییەکان دەکرێت دوای چەند کاتژمێرێک دەربکەوێت. زاراوە کۆنەکانی وەک «Secondary/Dry Drowning» چیتر بە شێوەیەکی پزیشکی بەکارناهێنرێن."]}],media:[{kind:"video",src:"media/videos/uni_21_swiftwater_rescue.mp4",title:"ڕزگارکردنی تەنگانە",description:"تەکنیکە نێودەوڵەتییەکان بۆ دەرهێنانی کەسەکان لە ئاوی خێرا"},{kind:"image",src:"media/images/uni_21_hydrology.png",title:"شیکردنەوەی هێزی ئاو",description:"نیشاندانی هێزی ئاو لەسەر لەشی مرۆڤ"}],quiz:[{question:"یەکەم هەنگاوی سەلامەت بۆ ڕزگارکردنی کەسێک لە ناو ئاودا چییە؟",options:[{text:"خۆت بهاوێژە ناو ئاوەکەوە",correct:!1},{text:"REACH (گەیاندنی دارێک یان شتێک)",correct:!0},{text:"ROW (بەکارهێنانی بەلەم)",correct:!1},{text:"چاوەڕێکردن تا تیمەکان دێن",correct:!1}],explanation:"REACH سەلامەتترین ڕێگایە چونکە ناچیتە ناو ئاوەکەوە و ژیانت ناکەوێتە مەترسییەوە."},{question:"بۆچی پێویستە ئەو کەسانەی لە ئاو ڕزگار کراون و نیشانەی وەک کۆکە یان هەناسەتەنگییان هەیە، بچنە نەخۆشخانە تەنانەت ئەگەر باش دەربکەون؟",options:[{text:"بۆ پشکنینی جلوبەرگەکانیان",correct:!1},{text:"چونکە تێکچوونی سییەکان دەکرێت دوای چەند کاتژمێرێک دەربکەوێت",correct:!0},{text:"بۆ گۆڕینی ناوەکانیان",correct:!1},{text:"هیچ پێویست ناکات",correct:!1}],explanation:"دوای خنکان، ئەو ئاوەی چووەتە ناو سییەکانەوە دەتوانێت هێدی هێدی تێکچوونی سییەکان دروست بکات و نیشانەکان دوای چەند کاتژمێرێک دەربکەون؛ بۆیە پشکنینی پزیشکی پێویستە."}]},{id:22,code:"WEATHER-2200",icon:"CloudLightning",accent:"#9333ea",title:"کەشوهەوای توند و تەنگانە سروشتییەکان",subtitle:"Severe Weather Emergencies & Survival",summary:"شیکردنەوەی هەورەتریشقە، بای توند، تەپوتۆز، و ڕێکارەکانی پاراستنی لەش لە بەرامبەر سەرما و گەرمای تونددا.",blocks:[{body:"کەشوهەوای توند دەتوانێت لە ماوەیەکی کورتدا ببێتە هۆی کارەساتی گەورە و لەدەستدانی ژیان. لە هەرێمی کوردستان، ڕووبەڕووی هەورەتریشقە، تەپوتۆزی توند، و پلەی گەرمای زۆر بەرز یان نزم دەبینەوە. ناسینەوەی نیشانەکانی مەترسی و زانینی ڕێکارەکانی پاراستن پێش ڕووداو، کلیلی ڕزگاربوونە."},{heading:"١. دیاردەی هەورەتریشقە (Lightning Safety)",body:"هەورەتریشقە دەتوانێت تا نزیکەی ٣٠٠ ملیۆن ڤۆڵت و دەیان هەزار ئەمپێری هەبێت (NOAA)، بۆیە پاراستن پێویستە:",points:["پەناگە: باشترین شوێن لە کاتی هەورەتریشقەدا بینا داخراوەکان یان ئۆتۆمبێلی داخراوی خاوەن سەقفی کانزایین.","دوورکەوتنەوە: هەرگیز لە ژێر دارە بەرزەکاندا مەوەستە، و لە شوێنە کراوە و بەرزەکان و لە ئاو دوور بکەوەرەوە.","ئەگەر دەنگی هەورەگرمەت (Thunder) بیست، ئەوەندە نزیکیت کە هەورەتریشقە دەتوانێت لێت بدات: یەکسەر بچۆ ناو شوێنێکی داخراو (When Thunder Roars, Go Indoors)، و تا ٣٠ خولەک دوای دوایین هەورەگرمە بمێنەوە. یاسا کۆنەکەی (٣٠-٣٠) هەمان ٣٠ خولەکی چاوەڕێکردنی بەکاردەهێنا.","ئامێرە کارەباییەکان: لە ماڵەوە، ئامێرە هەستیارەکان لە کارەبا دابڕە بۆ ئەوەی بەرزبوونەوەی لەناکاوی ڤۆڵتیە (Power Surge) زیانیان پێ نەگەیەنێت."]},{heading:"٢. تەپوتۆز و بای توند",body:"تەپوتۆز (Dust Storms) مەترسییەکی تەندروستی و هاتوچۆیی گەورەیە لە ناوچەکەماندا:",points:["لێخوڕین: ئەگەر بینین زۆر کەم بووەوە، بە تەواوی لە شەقامەکە دەربچۆ و لە لای ڕاستەوە بوەستە، گڵۆپەکانی ئۆتۆمبێلەکە بکوژێنەرەوە و بریکی دەستی ڕابکێشە، بۆ ئەوەی ئۆتۆمبێلەکانی تر بەدوای ڕووناکییەکانتدا نەیەن و لێت نەدەن.","پاراستنی کۆئەندامی هەناسە: بەکارهێنانی دەمامکی N95 یان پارچە قوماشێکی تەڕ بۆ کەمکردنەوەی چوونی تەنۆلکە وردەکان بۆ ناو سییەکان.","بای توند: لە کاتی بای تونددا، لە پەنجەرە شووشەییەکان دوور بکەوەرەوە و لە ژوورە ناوەکییەکانی بیناکەدا بمێنەوە."]},{heading:"٣. تەنگانەکانی پلەی گەرما (Heat & Cold Stress)",body:"تێگەیشتن لە حاڵەتەکانی Hypothermia و Heat Stroke بۆ هەر ڕزگارکەرێک پێویستە:",points:["گەرمالێدانی مەترسیدار (Heat Stroke): کاتێک پلەی گەرمای لەش لە ٤٠ پلەی سیلیزی تێدەپەڕێت و گۆڕانکاریی هۆشی (سەرگێژخواردن، شێوان) پەیدا دەبن. پێست دەکرێت وشک و سوور و گەرم بێت، بەڵام لە گەرمالێدانی بەهۆی کار و وەرزشەوە دەکرێت ئارەقەی هەبێت. ئەمە حاڵەتێکی کوشندەیە: پەیوەندی بکە بە ١٢٢ و یەکسەر لەشی بە ئاوی سارد سارد بکەرەوە.","ساردبوونەوەی لەش (Hypothermia): کاتێک پلەی گەرمای ناوەکیی لەش دادەبەزێتە خوار ٣٥ پلە. نیشانەکان: لەرزینی توند، قسەکردنی قورس، و هێواشبوونەوەی لێدانی دڵ.","سەرمابردن (Frostbite): ڕەقبوونی شانەکانی لەش (پەنجە، گوێ، لووت) بەهۆی سەرمای زۆر توندەوە؛ هەرگیز شوێنی سەرمابردووەکە مەسوو و بە ئاوی زۆر گەرم گەرمی مەکەرەوە."]}],media:[{kind:"video",src:"media/videos/uni_22_weather_survival.mp4",title:"ڕێکارەکانی پاراستن",description:"چۆنیەتیی مامەڵەکردن لەگەڵ هەورەتریشقە و بای توند"},{kind:"image",src:"media/images/uni_22_heat_stroke.png",title:"نیشانەکانی گەرمالێدان",description:"جیاوازیی نێوان ماندووبوونی گەرما و حاڵەتی کوشندەی Heat Stroke"}],quiz:[{question:"یاسای ٣٠-٣٠ لە کاتی هەورەتریشقەدا ئاماژەیە بۆ چی؟",options:[{text:"پلەی گەرما",correct:!1},{text:"دیاریکردنی مەودای مەترسی و کاتی چاوەڕێکردن دوای هەورەتریشقە",correct:!0},{text:"خێرایی با",correct:!1},{text:"بڕی باران",correct:!1}],explanation:"یاسا کۆنەکە دەڵێت: ئەگەر کاتی نێوان هەورەتریشقە و دەنگەکەی کەمتر لە ٣٠ چرکە بێت، پێویستە بچیتە شوێنێکی داخراو و تا ٣٠ خولەک دوای دوایین هەورەگرمە بمێنیتەوە. ڕێنماییە نوێیەکەی NOAA ئاسانترە: ئەگەر هەورەگرمەت بیست، یەکسەر بچۆ ژوورەوە."},{question:"کام لەمانە نیشانەی گەرمالێدانی مەترسیدارە (Heat Stroke)؟",options:[{text:"تەنها ئارەقکردنەوەی زۆر",correct:!1},{text:"بەرزبوونەوەی پلەی گەرمای لەش بۆ سەرووی ٤٠ پلە لەگەڵ سەرگێژخواردن، و پێستی وشک و سوور",correct:!0},{text:"لەرزینی لەش",correct:!1},{text:"پژمین",correct:!1}],explanation:"لە کاتی Heat Stroke دا، لەش کۆنتڕۆڵی ساردکردنەوەی خۆی لەدەست دەدات و پلەی گەرماکەی لە ٤٠ بەرزتر دەبێتەوە، و ئەمە زیان بە مێشک دەگەیەنێت. ساردکردنەوەی یەکسەر و پەیوەندیکردن بە ١٢٢ پێویستە."}]},{id:23,code:"SUPP-2300",icon:"BellRing",accent:"#dc2626",title:"سیستەمەکانی ئاگادارکردنەوە و کوژاندنەوەی ئاگر",subtitle:"Fire Detection & Automatic Suppression Engineering",summary:"شیکردنەوەی تەکنیکیی هەستەوەرەکانی ئاگر، سیستەمەکانی Sprinkler، و تەکنەلۆجیای کوژاندنەوە بە گازە پاکەکان.",blocks:[{body:"سیستەمە ئۆتۆماتیکییەکانی پاراستن یەکەم هێڵی بەرگرین لە بینا نوێیەکاندا. ئەم سیستەمانە دیزاین دەکرێن بۆ ئەوەی ئاگر لە قۆناغی دەستپێکدا (Incipient Stage) بدۆزنەوە و بەبێ دەستێوەردانی مرۆڤ کۆنتڕۆڵی بکەن. ئەم مۆدیوولە بنەما ئەندازیارییەکان بەپێی ستانداردەکانی NFPA 13 (Sprinkler) و NFPA 72 (ئاگادارکردنەوە) ڕوون دەکاتەوە."},{heading:"١. سیستەمەکانی هەستەوەر و ئاگادارکردنەوە (Detection)",body:"هەستەوەرەکان (Detectors) چاوی بینان و بە چەند شێوازێک کار دەکەن:",points:["Photoelectric Smoke Detector: پشت بە تیشکی ڕووناکی دەبەستێت؛ بۆ دۆزینەوەی ئاگری هێواش و دووکەڵاوی باشترین جۆرە.","Ionization Detector: بۆ تەنۆلکە زۆر بچووکەکانی ئاگری خێرا و گڕدار هەستیارترە.","Heat Detectors: لەو شوێنانە بەکاردێن کە دووکەڵ یان هەڵم بە شێوەیەکی ئاسایی تێیاندا هەیە (وەک چێشتخانە و کارگە)، و بە بەرزبوونەوەی گەرما کار دەکەن.","Notification Appliances: بەکارهێنانی زەنگ و ڕووناکیی فلاشدار بۆ ئاگادارکردنەوەی هەموو بیناکە."]},{heading:"٢. ئەندازیاریی سیستەمی Sprinkler",body:"ئەم سیستەمە پەستانی ئاو بەکاردەهێنێت بۆ کۆنتڕۆڵکردنی ئاگر لە شوێنی ڕوودانیدا:",points:["بڵبی شووشەیی (Bulb): زۆربەی سەرەکانی Sprinkler بڵبێکی شووشەیی پڕ لە شلەمەنی هەیە کە لە پلەیەکی گەرمای دیاریکراودا دەشکێت و ڕێگە دەدات ئاو بپڕژێت.","جۆرەکانی سیستەم: Wet Pipe کە باوترینە و بۆرییەکانی پڕن لە ئاو، و Dry Pipe بۆ ئەو شوێنانەی مەترسیی بەستنی ئاویان تێدایە.","ڕاستییەکی زانستی: تەنها ئەو سەرانەی دەکەونە ژێر گەرمای ئاگرەکەوە دەکرێنەوە، نەک هەموو سەرەکانی بیناکە پێکەوە (وەک لە فیلمەکاندا نیشان دەدرێت)."]},{heading:"٣. کوژاندنەوە بە گازە پاکەکان (Clean Agent Systems)",body:"لەو شوێنانەی کە ئاو زیان بە کەرەستەکان دەگەیەنێت (وەک ژووری سێرڤەر و مۆزەخانەکان)، گاز بەکاردەهێنرێت (NFPA 2001):",points:["FM-200 و FK-5-1-12 (Novec 1230): ئەم گازانە بە شێوەیەکی سەرەکی گەرما هەڵدەمژن و هەندێک لە کارلێکی زنجیرەییش دەپچڕێنن، و هیچ پاشماوەیەک لە دوای خۆیان بەجێ ناهێڵن.","CO₂ Systems: زۆر کاریگەرن بەڵام مەترسیی خنکانیان بۆ مرۆڤ هەیە، بۆیە بە گشتی تەنها لە شوێنە بێ مرۆڤەکاندا، لەگەڵ ئاگادارکردنەوە پێش بەردان و قفڵکردنی سیستەمەکە (NFPA 12) بەکاردەهێنرێن.","Saponification: ڕێگای کوژاندنەوەی ئاگری چێشتخانەکان (Class K لە NFPA دا، Class F لە EN 2 دا) بە گۆڕینی ڕۆنی سووتاو بۆ ماددەیەکی وەک سابوون."]}],media:[{kind:"video",src:"media/videos/uni_23_sprinkler_physics.mp4",title:"فیزیای Sprinkler",description:"شیکردنەوەی کارکردنی ئۆتۆماتیکیی سیستەمی ئاو"},{kind:"image",src:"media/images/uni_23_detector_types.png",title:"جۆرەکانی هەستەوەر",description:"بەراوردکردنی کارکردنی هەستەوەرەکانی دووکەڵ و گەرما"}],quiz:[{question:"کام جۆری هەستەوەری دووکەڵ (Smoke Detector) بۆ ناسینەوەی ئاگری هێواش و دووکەڵاوی باشترە؟",options:[{text:"Ionization Detector",correct:!1},{text:"Photoelectric Detector",correct:!0},{text:"Heat Detector",correct:!1},{text:"Flame Detector",correct:!1}],explanation:"هەستەوەرەکانی Photoelectric لە ڕێگەی تیشکی ڕووناکییەوە زۆر بە خێرایی هەست بە دووکەڵی چڕ دەکەن، کە تایبەتمەندیی ئاگری هێواشە."},{question:"لە سیستەمی ستانداردی Sprinkler دا، ئایا هەموو سەرەکانی ئاو پێکەوە دەکرێنەوە؟",options:[{text:"بەڵێ، هەموویان پێکەوە کار دەکەن",correct:!1},{text:"نەخێر، تەنها ئەو سەرەی گەرماکەی دەگاتە پلەی شکانی بڵبەکەی دەکرێتەوە",correct:!0},{text:"تەنها ئەگەر تیمەکانی کوژاندنەوەی ئاگر فەرمان بدەن",correct:!1},{text:"تەنها بە شەو",correct:!1}],explanation:"سیستەمی ستاندارد بە شێوەیەکی شوێنی کار دەکات؛ هەر سەرێک بە سەربەخۆیی کار دەکات بۆ ئەوەی زیانەکانی ئاو لە شوێنەکانی تر کەم ببنەوە."}]},{id:24,code:"EVAC-2400",icon:"Tent",accent:"#0d9488",title:"چۆڵکردنی بە کۆمەڵ و بەڕێوەبردنی پەناگەکان",subtitle:"Mass Evacuation Strategy & Shelter Operations",summary:"ستراتیژییەکانی چۆڵکردنی بە کۆمەڵ لە کارەساتە گەورەکاندا، ڕێکخستنی کەمپەکانی یارمەتی، و پەیڕەوکردنی ستانداردە نێودەوڵەتییەکانی پەناگەکان (Sphere).",blocks:[{body:"لە کاتی کارەساتە گەورەکاندا وەک بوومەلەرزە وێرانکەرەکان یان لافاوە بەرفراوانەکان، گواستنەوەی هەزاران کەس بۆ شوێنی سەلامەت پێویستی بە پلانێکی لۆجیستیکیی ئاڵۆز هەیە. بەڕێوەبردنی پەناگەکان تەنها دابینکردنی شوێن نییە، بەڵکو دابینکردنی تەندروستی، ئاسایش و کەرامەتی مرۆڤە بەپێی ستانداردە نێودەوڵەتییەکان (وەک Sphere Handbook). ئەم مۆدیوولە بنەماکانی ڕێکخستنی خەڵک و پەناگەکان ڕوون دەکاتەوە."},{heading:"١. پلاندانانی ستراتیژیی چۆڵکردن",body:"پرۆسەی چۆڵکردنی خەڵک پێویستە بەپێی قۆناغی ڕێکخراو بێت بۆ ئەوەی تێکچوون دروست نەبێت:",points:["دیاریکردنی ڕێڕەوەکانی چۆڵکردن: نەخشەکێشانی ڕێگا سەرەکی و یەدەگەکان، و دیاریکردنی ئەو ڕێگایانەی تەنها بۆ ئۆتۆمبێلەکانی تەنگانە تەرخان کراون.","بەڕێوەبردنی هاتوچۆ: هەماهەنگی لەگەڵ پۆلیسی هاتوچۆ (١٠٤) بۆ ڕێگرتن لە قەرەباڵغی و داخرانی ڕێگاکانی دەرچوون.","سیستەمی ئاگادارکردنەوەی گشتی: بەکارهێنانی بڵندگۆ، SMS، ڕادیۆ و تەلەفزیۆنە ناوخۆییەکان بۆ ئاگادارکردنەوەی خەڵک لە کاتی دەستپێکردنی چۆڵکردن."]},{heading:"٢. بەڕێوەبردنی پەناگە و کەمپەکانی تەنگانە",body:"بەپێی ستانداردە نێودەوڵەتییەکان (Sphere)، هەر پەناگەیەک پێویستە ئەم مەرجانە جێبەجێ بکات:",points:["پۆلێنکردنی شوێن: جیاکردنەوە لە نێوان پەناگە کورتخایەنەکان (وەک قوتابخانە و هۆڵە وەرزشییەکان) و کەمپە درێژخایەنەکان (وەک کەمپی چادر).","تۆمارکردن و داتابەیس: نووسینی لیستی ناوی هەموو ئاوارەکان، و تۆمارکردنی خێزانەکان و کەسە تەنهاکان (بە تایبەتی منداڵانی بێ سەرپەرشت) بە جیا بۆ پاراستنی ئاسایش.","تەندروستی و پاکوخاوێنی: دابینکردنی لانیکەم ١٥ لیتر ئاو بۆ هەر کەسێک لە ڕۆژێکدا (بۆ خواردنەوە، چێشتلێنان و پاکوخاوێنیی کەسی)، و یەک تەوالێت بۆ هەر ٢٠ کەس (لە سەرەتای تەنگانەدا، یەک بۆ ٥٠ کەس وەک کەمترین ئاست)."]},{heading:"٣. چاودێریی گرووپە هەستیارەکان (Vulnerable Groups)",body:"لە کاتی کارەساتەکاندا، هەندێک گرووپ پێویستیان بە پاراستنێکی تایبەت هەیە:",points:["بەساڵاچووان و کەسانی خاوەن پێداویستیی تایبەت: دابینکردنی ڕێڕەوی گونجاو بۆ کورسیی چەرخدار و دابینکردنی دەرمانی نەخۆشییە درێژخایەنەکان.","منداڵان: دروستکردنی شوێنی تایبەتی پارێزراو (Child-Friendly Spaces) بۆ ئەوەی لە برینی دەروونی و مەترسییەکان دوور بن.","ئافرەتانی دووگیان: دابینکردنی تیمی پزیشکیی تایبەت لە پەناگەکەدا بۆ حاڵەتەکانی منداڵبوونی لەناکاو."]}],media:[{kind:"video",src:"media/videos/uni_24_shelter_org.mp4",title:"ڕێکخستنی کەمپەکان",description:"چۆنیەتیی دابەشکردنی چادر و خزمەتگوزارییەکان بەپێی ستانداردە نێودەوڵەتییەکان"},{kind:"image",src:"media/images/uni_24_evac_map.png",title:"نەخشەی چۆڵکردن",description:"نموونەی پلانی چۆڵکردنی شارێک لە کاتی لافاودا"}],quiz:[{question:"بەپێی ستانداردە مرۆییەکان (Sphere)، هەر کەسێک لە پەناگەدا لانیکەم پێویستی بە چەند لیتر ئاو هەیە لە ڕۆژێکدا؟",options:[{text:"٢ لیتر",correct:!1},{text:"٥ لیتر",correct:!1},{text:"١٥ لیتر",correct:!0},{text:"٥٠ لیتر",correct:!1}],explanation:"ستانداردی Sphere دیاری دەکات کە لانیکەم ١٥ لیتر بۆ خواردنەوە، پاکوخاوێنی و چێشتلێنان پێویستە."},{question:"ئامانجی سەرەکی لە (Child-Friendly Spaces) لە کەمپەکاندا چییە؟",options:[{text:"بۆ خەوتنی منداڵان",correct:!1},{text:"بۆ پاراستنی منداڵان لە برینی دەروونی و دابینکردنی شوێنێکی یاریی پارێزراو",correct:!0},{text:"بۆ کۆکردنەوەی خواردن",correct:!1},{text:"بۆ فێربوونی زمانەکان",correct:!1}],explanation:"ئەم شوێنانە دادەنرێن بۆ ئەوەی منداڵان لە ژینگەیەکی ئارامدا بن و دوای کارەساتەکە تووشی توندوتیژی یان کێشەی دەروونی نەبن."}]},{id:25,code:"TECH-2500",icon:"Mountain",accent:"#475569",title:"ڕزگارکردنی تەکنیکی و مەیدانی",subtitle:"Technical Rescue: Rope, Confined Space & Structural Collapse",summary:"ڕزگارکردن بە پەت، ڕزگارکردن لە شوێنە تەنگ و بەرزەکاندا، و ئەندازیاریی جێگیرکردنی بینا ڕووخاوەکان.",blocks:[{body:"ڕزگارکردنی تەکنیکی (Technical Rescue) ئاستێکی پێشکەوتووی کاری بەرگریی شارستانییە کە تێیدا تیمە تایبەتەکان بە بەکارهێنانی ئامێری ئەندازیاری و سیستەمی میکانیکی بریندارەکان ڕزگار دەکەن. ئەم کارە پێویستی بە پلاندانانێکی ورد و زانینی فیزیا هەیە بۆ ئەوەی نەبێتە هۆی زیانی زیاتر بۆ بریندار یان تیمەکە."},{heading:"١. ڕزگارکردن بە پەت (Rope Rescue)",body:"بەکارهێنانی سیستەمەکانی پەت بەپێی ستانداردی NFPA 2500 (کە جێگەی NFPA 1670، NFPA 1858 و NFPA 1983 ی پێشووی گرتووەتەوە):",points:["دوو سیستەم: بەکارهێنانی هێڵی سەرەکی (Main Line) و هێڵی پاراستن (Belay Line)؛ هەمیشە پێویستە دوو سیستەم هەبن بۆ ئەوەی ئەگەر یەکێکیان پچڕا، ئەوی تریان بریندار و ڕزگارکەر بپارێزێت.","سوودی میکانیکی (Mechanical Advantage): بەکارهێنانی سیستەمی ٣:١ یان ٥:١ لە ڕێگەی قەرقەرەکانەوە (Pulleys) بۆ بەرزکردنەوەی بریندار یان باری قورس بە کەمترین هێزی ماسولکە.","گرێ سەرەکییەکان: بەکارهێنانی گرێکانی وەک Figure 8 on a bight و Double Fisherman's کە لە ژێر باری قورسدا ناخلیسکێن."]},{heading:"٢. ڕزگارکردن لە شوێنە تەنگەکاندا (Confined Space Rescue)",body:"شوێنەکانی وەک تانکی سووتەمەنی، بۆرییەکانی ئاوی پیس و کونە ژێرزەوییەکان مەترسیی بێدەنگن (OSHA 1910.146):",points:["پشکنینی هەوا: پێش چوونە ژوورەوە، پێویستە ئاستی ئۆکسجین (لانیکەم ١٩.٥٪)، گازە ئاگرگرەکان (کەمتر لە ١٠٪ لە LEL)، و گازە ژەهراوییەکانی وەک H₂S و CO بپشکنرێن.","ڕۆڵەکانی تیم: تیمەکە دەبێتە سێ بەش: Entrant (ئەوەی دەچێتە ژوورەوە)، Attendant (ئەوەی لە دەرەوە چاودێری دەکات و هەرگیز ناچێتە ژوورەوە)، و Supervisor (فەرماندە).","هەواگۆڕکێ بە پانکە (Forced Ventilation): بەکارهێنانی پانکەی هەوا بۆ دەرکردنی گازە ژەهراوییەکان و هێنانی هەوای پاک پێش چوونی تیمەکە و لە کاتی کارکردندا."]},{heading:"٣. ڕزگارکردن لە ڕووخانی بیناکاندا (Structural Collapse)",body:"جێگیرکردنی بینا ڕووخاوەکان بۆ ئەوەی تیمەکان بتوانن بە سەلامەتی بچنە ناو بۆشاییەکانەوە:",points:["Shoring (پاڵپشتکردن): بەکارهێنانی دار و کۆڵەکەی ئاسنین بۆ ڕاگرتنی سەقف و دیوارە لەبەر ڕووخانەکان.","ئامێرەکانی گەڕان: بەکارهێنانی ئامێرەکانی گوێگرتنی دەنگی و لەرینەوەیی بۆ بیستنی لێدان و دەنگی بریندارەکان، و ئامێرەکانی ڕادار بۆ دۆزینەوەی هەناسە و جووڵەیان لە ژێر داروپەردوودا.","تیمەکانی K9: بەکارهێنانی سەگی ڕاهێنراو بۆ دۆزینەوەی بۆنی مرۆڤی زیندوو لە ناو داروپەردووی گەورەدا."]}],media:[{kind:"video",src:"media/videos/uni_25_rope_systems.mp4",title:"سیستەمەکانی پەت",description:"شیکردنەوەی سیستەمی ٣:١ بۆ بەرزکردنەوەی بریندارەکان لە چیاکاندا"},{kind:"video",src:"media/videos/uni_25_confined_entry.mp4",title:"چوونە ناو شوێنە تەنگەکان",description:"ڕێکارەکانی سەلامەتی و بەکارهێنانی ئامێرەکانی پشکنینی هەوا"},{kind:"image",src:"media/images/uni_25_shoring_types.png",title:"جۆرەکانی Shoring",description:"نیشاندانی شێوازە ئەندازیارییەکان بۆ ڕاگرتنی دیوارە لەبەر ڕووخانەکان"}],quiz:[{question:"بۆچی لە ڕزگارکردن بە پەتدا هەمیشە پێویست بە دوو سیستەم (Main و Belay) هەیە؟",options:[{text:"بۆ خێرایی زیاتر",correct:!1},{text:"بۆ ئەوەی ئەگەر پەتێک یان سیستەمێک تێک چوو، ئەوی تر ژیانی بریندار و تیمەکە بپارێزێت",correct:!0},{text:"بۆ ئەوەی کەرەستە زیاتر بن",correct:!1},{text:"تەنها بۆ دیمەنێکی جوان",correct:!1}],explanation:"بەپێی ستانداردە نێودەوڵەتییەکان، سیستەمی Belay (یەدەگ) مەرجێکی سەرەکیی سەلامەتییە لە بەرزاییەکاندا."},{question:"کەمترین ڕێژەی ئۆکسجین کە چوونە ناو شوێنێکی تەنگ بەبێ ئامێری هەناسە ڕێگەپێدراو بێت، چەندە؟",options:[{text:"١٠٪",correct:!1},{text:"١٦٪",correct:!1},{text:"١٩.٥٪",correct:!0},{text:"٢١٪",correct:!1}],explanation:"ئەگەر ئۆکسجین لە ١٩.٥٪ کەمتر بێت، کەشێکی کەم-ئۆکسجین (Oxygen-Deficient) هەیە و تیمەکە نابێت بەبێ ئامێری هەناسەدانی سەربەخۆ (SCBA) بچێتە ژوورەوە."}]},{id:26,code:"COMM-2550",icon:"Radio",accent:"#2563eb",title:"پەیوەندییەکانی تەنگانە و سیستەمەکانی ناردنی تیمەکان",subtitle:"Emergency Communications & Radio Dispatch Systems",summary:"سیستەمەکانی پەیوەندیی ڕادیۆیی، پرۆتۆکۆڵی وەرگرتن و ناردنی پەیوەندییەکان (Dispatch)، هەماهەنگیی نێوان دەزگاکان (Interoperability)، و بەکارهێنانی زمانی ڕوون (Plain Language).",blocks:[{body:"پەیوەندیی کاریگەر کۆڵەکەی سەرەکیی هەر بەڕێوەبردنێکی کارەساتە. لەم مۆدیوولەدا، باسی سیستەمە ڕادیۆییە دیجیتاڵ و ئەنالۆگەکان، پرۆتۆکۆڵی Dispatch، و چۆنیەتیی هەماهەنگی لە نێوان دەزگا جیاوازەکاندا (پۆلیس، کوژاندنەوەی ئاگر، ئەمبولانس) دەکەین. تێگەیشتن لەم سیستەمانە بۆ هەر ئەفسەرێکی بەرگریی شارستانی پێویستە."},{heading:"١. سیستەمە ڕادیۆییەکان (Radio Systems)",body:"جۆرەکانی سیستەمی پەیوەندیی بێتەل:",points:["VHF/UHF: فریکوێنسییە باوەکان بۆ پەیوەندیی ناوخۆیی؛ بە گشتی VHF بۆ ناوچە کراوەکان و UHF بۆ ناو بیناکان باشترە.","Trunked Radio: سیستەمێکە (ئەمڕۆ زۆرجار دیجیتاڵ) کە چەندین فریکوێنسی بە شێوەیەکی ئۆتۆماتیکی لە نێوان گرووپە جیاوازەکاندا دابەش دەکات، وەک سیستەمەکانی P25 لە ئەمریکا.","پەیوەندیی مانگی دەستکرد (Satellite Communications): بۆ ناوچە دوورەکان یان لە کاتی پچڕانی تۆڕە زەمینییەکاندا.","LTE/FirstNet: تۆڕێکی تایبەتی تیمەکانی تەنگانەیە لە ئەمریکا کە پێشینە و کوالیتییەکی بەرز دەداتە پەیوەندییەکان."]},{heading:"٢. پرۆتۆکۆڵی وەرگرتن و ناردنی پەیوەندییەکان (Dispatch Protocol)",body:"ڕێکارە ستانداردەکان بۆ وەرگرتنی پەیوەندییەکانی تەنگانە و ناردنی تیمەکان:",points:["وەرگرتنی پەیوەندی: بەکارهێنانی سیستەمی CAD (Computer Aided Dispatch) بۆ تۆمارکردنی خێرای زانیارییەکان.","پۆلێنکردنی پێشینە: دیاریکردنی ئاستی مەترسی (Priority 1, 2, 3) بەپێی جۆری ڕووداوەکە و ناوەڕۆکی پەیوەندییەکە.","پرۆتۆکۆڵی EMD (Emergency Medical Dispatch): دانی ڕێنمایی بە تەلەفۆن بە پەیوەندیکەر (بۆ نموونە ڕێنماییەکانی CPR) تا گەیشتنی ئەمبولانس.","کاتی وەڵامدانەوە: بەپێی NFPA 1225 (پێشتر NFPA 1221)، ٩٠٪ لە پەیوەندییەکانی تەنگانە پێویستە لە ماوەی ١٥ چرکەدا و ٩٥٪ لە ماوەی ٢٠ چرکەدا وەڵام بدرێنەوە؛ کاتی گەیشتنی تیمەکان بەپێی ئامانجە ناوخۆییەکانی بەڕێوەبەرایەتی دەپێورێت."]},{heading:"٣. زمانی ڕوون و زاراوە ستانداردەکانی ڕادیۆ",body:"بەپێی NIMS/ICS، پەیوەندییە ڕادیۆییەکان بە زمانێکی سادە و ڕوون دەکرێن، نەک بە کۆد، بۆ ئەوەی هەموو دەزگاکان لە یەکتر تێبگەن:",points:["کۆدەکانی دە (Ten-codes): وەک 10-4 و 10-20، سیستەمێکی کۆنە (Legacy) و واتاکانیان لە دەزگایەکەوە بۆ یەکێکی تر جیاوازن؛ بۆیە لە ڕووداوە هاوبەشەکاندا بەکارناهێنرێن. لە جیاتی «10-4» بڵێ «تێگەیشتم»، و لە جیاتی «10-20» شوێنەکەت بە ناو و ناونیشان بڵێ.","ئەلفوبێی دەنگی (Phonetic Alphabet): بەکارهێنانی Alfa، Bravo، Charlie... بۆ ڕوونکردنەوەی پیتەکان لەسەر ڕادیۆ.","Mayday: وشەی نێودەوڵەتیی داوای فریاکەوتنە (سێ جار دەوترێت) کاتێک ئاگرکوژێک لە مەترسییەکی کوشندەدا بێت؛ هەموو کەس پێویستە کەناڵەکەی بۆ چۆڵ بکەن.","PAR (Personnel Accountability Report): پشکنینی بوونی هەموو ئەندامانی تیمەکە لە شوێنی کار."]},{heading:"٤. هەماهەنگیی نێوان دەزگاکان (Interoperability)",body:"چۆنیەتیی پەیوەندیکردن لە نێوان دەزگا جیاوازەکاندا:",points:["کەناڵە هاوبەشەکان: دیاریکردنی فریکوێنسیی تایبەت بۆ پەیوەندیی نێوان پۆلیس، کوژاندنەوەی ئاگر و ئەمبولانس.","ئامێرەکانی بەستنەوە (Gateway Devices): ئەو ئامێرانەی سیستەمە جیاوازەکان پێکەوە دەبەستنەوە (وەک VHF لەگەڵ UHF).","پەیوەندی لە ICS دا: سەرۆکی یەکەی پەیوەندییەکان (Communications Unit Leader) بەرپرسە لە ڕێکخستنی پلانی پەیوەندییەکان.","NIMS Typing: پۆلێنکردنی کەرەستەکانی پەیوەندی بەپێی ستانداردە نیشتمانییەکان (Type I, II, III)."]},{heading:"٥. ناوەندەکانی فەرماندەیی (Command Centers)",body:"دانانی شوێنی ناوەندی بۆ کۆنتڕۆڵکردنی پەیوەندییەکان:",points:["EOC (Emergency Operations Center): ناوەندی سەرەکیی بەڕێوەبردنی کارەساتەکانە لە ئاستی شار یان پارێزگادا.","Mobile Command: ئۆتۆمبێلێکی تایبەتە کە وەک ناوەندی فەرماندەیی مەیدانی کار دەکات.","Status Boards: تەختەی نیشاندان بۆ زانینی شوێنی تیمەکان و دۆخی ڕووداوەکە.","Redundancy: بوونی سیستەمی یەدەگ لە کاتی تێکچوونی سیستەمی سەرەکیدا."]}],media:[{kind:"video",src:"media/videos/uni_26_radio_ops.mp4",title:"کارکردن بە ڕادیۆ",description:"بنەماکانی پەیوەندیی ڕادیۆیی و ئەلفوبێی دەنگی"},{kind:"image",src:"media/images/uni_26_dispatch_center.png",title:"ناوەندی وەرگرتنی پەیوەندییەکان",description:"ڕێکخستنی ژووری CAD و ئامێرەکان"}],quiz:[{question:"وشەی (Mayday) لەسەر ڕادیۆ نیشانەی چییە؟",options:[{text:"دەستپێکردنی کار",correct:!1},{text:"داوای فریاکەوتنی ئاگرکوژێک لە کاتی مەترسییەکی کوشندەدا",correct:!0},{text:"کۆتاییهاتنی کار",correct:!1},{text:"پشکنینی ڕادیۆ",correct:!1}],explanation:"Mayday وشەی نێودەوڵەتیی داوای فریاکەوتنە کاتێک ژیانی ئاگرکوژێک لە مەترسییەکی سەختدا بێت و پێویستی بە یارمەتیی خێرا هەبێت."},{question:"جیاوازیی سەرەکی لە نێوان VHF و UHF دا چییە؟",options:[{text:"VHF بۆ ناو بیناکان باشترە",correct:!1},{text:"UHF بۆ ناوچە کراوەکان باشترە",correct:!1},{text:"VHF بۆ ناوچە کراوەکان باشترە و UHF بۆ ناو بیناکان باشترە",correct:!0},{text:"هیچ جیاوازییەک نییە",correct:!1}],explanation:"شەپۆلەکانی VHF درێژترن و لە ناوچە کراوەکاندا باشتر دەگەن، بەڵام UHF ئاسانتر بە ناو بیناکاندا تێدەپەڕێت."}]},{id:27,code:"CBRN-2600",icon:"Radiation",accent:"#ca8a04",title:"بەرگری دژی ماددە کوشندەکان (CBRN)",subtitle:"Chemical, Biological, Radiological & Nuclear Defense",summary:"ستراتیژییەکانی پاراستن دژی مەترسییە کیمیایی، بایۆلۆجی، تیشکدەر و ئەتۆمییەکان، ئاستەکانی PPE، و ڕێکارەکانی پاککردنەوە (Decontamination).",blocks:[{body:"زاراوەی CBRN ئاماژەیە بۆ چوار جۆر مەترسیی کوشندە: کیمیایی، بایۆلۆجی، تیشکدەر (Radiological) و ئەتۆمی (Nuclear). ئەم مۆدیوولە بۆ ئەفسەران و ئەندازیاران ئامادە کراوە بۆ ئەوەی بزانن چۆن ڕووبەڕووی حاڵەتە نائاساییەکان ببنەوە. لێرەدا باسی فیزیای تیشکدانەوە، کیمیای ماددە دەمارییەکان، و پرۆتۆکۆڵەکانی پاککردنەوەی بە کۆمەڵ بەپێی ستانداردە نێودەوڵەتییەکان دەکەین."},{heading:"١. مەترسییە کیمیاییەکان (Chemical Agents)",body:"ماددە کیمیاییەکان بەپێی کاریگەرییان لەسەر لەش دابەش دەکرێن:",points:["ماددە دەمارییەکان (Nerve Agents): وەک Sarin و VX؛ کۆئەندامی دەمار پەک دەخەن. نیشانەکانیان بە SLUDGEM دەناسرێنەوە (بچووکبوونەوەی گلێنەی چاو، فرمێسک، میزکردن، سکچوون، و گرژبوونی ماسولکەکان).","ماددە خنکێنەرەکان (Choking Agents): وەک کلۆر و فۆسجین؛ زیانی سەخت بە سییەکان دەگەیەنن.","ماددە بڵقدروستکەرەکان (Blister Agents): وەک گازی خەردەل؛ دەبنە هۆی سووتانێکی کیمیاییی توند لەسەر پێست، چاو و سییەکان.","ماددەکانی خوێن (Blood Agents): وەک سیانید؛ ڕێگری لە خانەکان دەکەن کە ئۆکسجین بەکاربهێنن."]},{heading:"٢. مەترسییە بایۆلۆجی و میکرۆبییەکان (Biological Threats)",body:"بەکارهێنانی بەکتریا، ڤایرۆس و ژەهری زیندەیی وەک چەک:",points:["بەکتریا: وەک ئانسراکس (Anthrax) و تاعوون (Plague)؛ سپۆرەکانی ئانسراکس دەتوانن بۆ ماوەیەکی زۆر درێژ لە ژینگەدا بمێننەوە.","ڤایرۆس: وەک ئیبۆلا و ڤایرۆسی Smallpox؛ کە دەتوانن لە نێوان مرۆڤەکاندا بڵاو ببنەوە.","ژەهرە زیندەییەکان (Toxins): وەک ڕیسین (Ricin) کە لە تۆوی ڕووەکی Castor بەرهەم دەهێنرێت و ژەهرێکی زۆر کوشندەیە.","ڕێکار: بەکارهێنانی فلتەری HEPA و ژووری پەستانی نێگەتیڤ بۆ جیاکردنەوەی تووشبووان."]},{heading:"٣. فیزیای تیشکدانەوە و پاراستنی ئەتۆمی",body:"تێگەیشتن لە سێ بنەمای پاراستن: کات، مەودا، و پارێزەر:",points:["جۆرەکانی تیشک: Alpha بە پەڕەیەک کاغەز ڕادەگیرێت، Beta پێویستی بە پلاستیک یان ئەلەمنیۆم هەیە، بەڵام Gamma تەنها بە ماددەی چڕ و ئەستووری وەک قوڕقوشم (Lead)، کۆنکریت یان خاک کەم دەبێتەوە.","بۆمبی پیس (Dirty Bomb): تەقەمەنییەکی ئاساییە کە ماددەی تیشکدەری تێدایە بۆ پیسکردنی ناوچەیەک، تەقینەوەیەکی ئەتۆمی نییە.","بنەمای TDS: کەمکردنەوەی کاتی مانەوە لە نزیک سەرچاوەکە (Time)، زیادکردنی مەودا (Distance)، و بەکارهێنانی پارێزەر (Shielding)."]},{heading:"٤. ئاستەکانی جلوبەرگی پاراستن (PPE Levels)",body:"بەرگریی شارستانی پێویستە بزانێت کام جل لە کام کاتدا بەکاربهێنێت:",points:["Level A: بەرزترین پاراستن؛ جلێکی تەواو داخراو (Gas-tight) لەگەڵ ئامێری هەناسەدانی سەربەخۆ (SCBA) لە ناو جلەکەدا.","Level B: بەرزترین پاراستنی کۆئەندامی هەناسە (SCBA) لەگەڵ جلێکی دژی پڕژانی شلەمەنییەکان، بەڵام جلەکە گاز ناگرێتەوە.","Level C: دەمامکی فلتەردار (Air-Purifying Respirator) و جلی کیمیایی؛ تەنها کاتێک ماددەکە و چڕییەکەی ناسراو بێت و ئۆکسجین بەس بێت.","Level D: جلوبەرگی ئاسایی کار (Uniform) لەگەڵ دەستکێش؛ بەبێ مەترسیی کیمیاییی هەناسە."]},{heading:"٥. پرۆتۆکۆڵی پاککردنەوە (Decontamination)",body:"پرۆسەی لابردنی ماددەی پیسکەر لەسەر لەش و کەرەستەکان:",points:["قۆناغەکان: داکەندنی جلەکان (کە بەپێی ڕێنماییە نێودەوڵەتییەکان نزیکەی ٨٠–٩٠٪ لە پیسبوونەکە لادەبات)، شوشتن بە ئاو و سابوون، و پشکنین؛ بۆ پیسبوونی تیشکدەر بە ئامێری Geiger Counter.","ناوچەکان (Zones): ناوچەی گەرم (Hot Zone) کە پیس بووە، ناوچەی نیمچەگەرم (Warm Zone) شوێنی پاککردنەوە، و ناوچەی سارد (Cold Zone) شوێنی فەرماندەیی و تیمە پزیشکییەکان.","ئاراستەی با: ناوچەی پاک و بنکەی فەرماندەیی هەمیشە پێویستە لە لای هاتنی باوە (Upwind) و لە شوێنێکی بەرزتردا بن."]}],media:[{kind:"video",src:"media/videos/uni_27_cbrn_ppe.mp4",title:"ئاستەکانی پاراستن",description:"چۆنیەتیی لەبەرکردنی دروستی جلی Level A"},{kind:"image",src:"media/images/uni_27_radiation_chart.png",title:"جۆرەکانی تیشکدانەوە",description:"شیکردنەوەی توانای تێپەڕبوونی تیشکەکانی گاما و بێتا"}],quiz:[{question:"کام ئاستی PPE پاراستنی تەواو دژی گاز و بەرکەوتنی کیمیایی دابین دەکات؟",options:[{text:"Level D",correct:!1},{text:"Level C",correct:!1},{text:"Level B",correct:!1},{text:"Level A",correct:!0}],explanation:"Level A جلێکی تەواو داخراوە و مرۆڤ لە گاز و شلەمەنییە کیمیاییە کوشندەکان دەپارێزێت."},{question:"بەپێی بنەمای TDS، چۆن دەتوانیت مەترسیی تیشکدانەوە لەسەر لەشی خۆت کەم بکەیتەوە؟",options:[{text:"بە کەمکردنەوەی کاتی مانەوە و زیادکردنی مەودا لە سەرچاوەکەوە",correct:!0},{text:"بە خواردنەوەی ئاو",correct:!1},{text:"بە هەڵاتنی بێ ئاراستە",correct:!1},{text:"بە بەکارهێنانی دەمامکێکی سادە",correct:!1}],explanation:"کات (Time)، مەودا (Distance) و پارێزەر (Shielding) سێ بنەمای زانستین بۆ پاراستنی مرۆڤ لە تیشکدانەوە."}]},{id:28,code:"INVEST-2700",icon:"Search",accent:"#d97706",title:"لێکۆڵینەوە لە هۆکارەکانی ئاگر",subtitle:"Scientific Fire & Arson Investigation",summary:"زانستی دۆزینەوەی سەرچاوەی ئاگر، شیکردنەوەی نیشانەکانی سووتان، و ڕێبازی NFPA 921.",blocks:[{body:"لێکۆڵینەوە لە هۆکارەکانی ئاگر زانستێکی تێکەڵە لە کاری پۆلیس و ئەندازیاری. ئامانج دۆزینەوەی ڕاستیی ڕووداوەکەیە: ئایا ئاگرەکە بە ڕێکەوت (Accidental) بووە یان بە ئەنقەست (Arson)؟ ئەم مۆدیوولە پشت بە ڕێبەری NFPA 921 (Guide) دەبەستێت کە ڕێبازی زانستی (Scientific Method) بۆ کۆکردنەوە و شیکردنەوەی بەڵگەکان دیاری دەکات."},{heading:"١. دیاریکردنی سەرچاوەی دەستپێک (Origin Determination)",body:"دۆزینەوەی ئەو خاڵەی کە ئاگرەکە لێیەوە دەستی پێ کردووە:",points:["V-Pattern: نیشانەیەکە بە شێوەی پیتی V لەسەر دیوارەکان دروست دەبێت و ئاراستەی ئاگرەکە لە خوارەوە بەرەو سەرەوە نیشان دەدات. بنی ئەم نیشانەیە زۆرجار لە سەرچاوەی ئاگرەکەوە نزیکە.","نزمترین خاڵی سووتان: چونکە گەرما بەرەو سەرەوە دەچێت، نزمترین شوێن کە زیانی سووتانی پێوە دیارە زۆرجار لە شوێنی دەستپێکەوە نزیکە (بەڵام دوای Flashover ئەم نیشانانە دەکرێت بگۆڕدرێن).","Calcination: گۆڕانکاریی کیمیایی لەسەر دیوارە گەچییەکان (Gypsum) کە نیشان دەدەن ئاگرەکە چەند بەتین بووە و بۆ چ ماوەیەک لەو شوێنەدا ماوەتەوە."]},{heading:"٢. ماددە خێراکەرەکان (Accelerants)",body:"دۆزینەوەی ئاگری بە ئەنقەست لە ڕێگەی پاشماوەکانی سووتەمەنییەوە:",points:["هایدرۆکاربۆنەکان (Hydrocarbons): دۆزینەوەی پاشماوەی بەنزین، گازوایل یان نەوت لە ناو داروپەردووی سووتاودا.","سەگی بۆنکردن: تیمەکانی لێکۆڵینەوە سەگی ڕاهێنراو (K9) بەکاردەهێنن کە لە ماوەیەکی کورتدا بۆنی ماددە خێراکەرەکان دەدۆزنەوە؛ بەڵام بەپێی NFPA 921، هەر ئاماژەیەکی سەگ پێویستە بە شیکردنەوەی تاقیگەیی پشتڕاست بکرێتەوە.","شیکردنەوەی تاقیگەیی: بەکارهێنانی ئامێری Gas Chromatography–Mass Spectrometry (GC-MS) بۆ دڵنیابوونەوە لە بوونی ماددە کیمیاییەکان لە نموونەکانی داروپەردوو و خاکدا."]},{heading:"٣. نیشانەکانی ئاگری بە ئەنقەست (Arson Indicators)",body:"هەندێک نیشانە گومان لەسەر حاڵەتە تاوانکارییەکان دروست دەکەن:",points:["چەند سەرچاوە: ئەگەر ئاگرەکە لە چەند شوێنێکەوە پێکەوە دەستی پێ کردبێت، بەبێ پەیوەندی لە نێوانیاندا.","لەکارخستنی سیستەمەکان: ئەگەر سیستەمی Sprinkler یان ئاگادارکردنەوە پێشوەخت ڕاگیرابێت.","Trailer: بوونی هێڵێک لە سووتەمەنی یان قوماش لەسەر زەوی بۆ گەیاندنی ئاگر لە ژوورێکەوە بۆ ژوورێکی تر."]},{heading:"٤. پاراستنی بەڵگەکان (Chain of Custody)",body:"ڕێکارە یاساییەکان بۆ ئەوەی بەڵگەکان لە دادگادا قبووڵ بکرێن:",points:["زنجیرەی پاراستن: تۆمارکردنی هەر کەسێک کە دەستی لە بەڵگەیەک داوە، لە کاتی دۆزینەوەیەوە تا دەگاتە تاقیگە و دادگا.","تۆمارکردن: گرتنی وێنەی نزیک (Macro) بۆ نیشانە وردەکان، و کێشانی نەخشەی (Sketch) شوێنی ڕووداوەکە.","تێکچوونی بەڵگەکان (Spoliation): وریایی لە تێکچوونی بەڵگەکان لە کاتی کوژاندنەوەی ئاگردا؛ ئاگرکوژەکان پێویستە ئاگاداری نیشانەکانی سووتان بن و دوای کوژاندنەوە شوێنەکە نەگۆڕن."]}],media:[{kind:"video",src:"media/videos/uni_28_fire_patterns.mp4",title:"نیشانەکانی سووتان",description:"شیکردنەوەی جیاوازیی نێوان V-pattern و Clean Burn"},{kind:"image",src:"media/images/uni_28_arson_dog.jpg",title:"سەگەکانی K9",description:"ڕۆڵی سەگە ڕاهێنراوەکان لە دۆزینەوەی ماددە خێراکەرەکاندا"}],quiz:[{question:"نیشانەی (V-Pattern) لەسەر دیواری بینا نیشانەی چییە؟",options:[{text:"ئاراستەی دەرچوونی خەڵک",correct:!1},{text:"ئاراستەی بڵاوبوونەوەی ئاگر لە سەرچاوەکەوە بەرەو سەرەوە",correct:!0},{text:"تێکچوونی کارەبا",correct:!1},{text:"پلەی ساردبوونەوەی ئاگر",correct:!1}],explanation:"ئەم نیشانەیە دیاری دەکات کە ئاگرەکە لە کوێوە دەستی پێ کردووە و بەرەو کام لا چووە، و یارمەتیی لێکۆڵەران دەدات شوێنی دەستپێک بدۆزنەوە."},{question:"بۆچی «زنجیرەی پاراستن» (Chain of Custody) لە لێکۆڵینەوەدا گرنگە؟",options:[{text:"بۆ جوانیی ڕاپۆرتەکە",correct:!1},{text:"بۆ ئەوەی بەڵگەکان لە دادگادا قبووڵ بکرێن و نەگۆڕدرێن",correct:!0},{text:"بۆ خێراکردنی کوژاندنەوەی ئاگر",correct:!1},{text:"هیچ گرنگییەکی نییە",correct:!1}],explanation:"ئەگەر زنجیرەی پاراستن بپچڕێت، پارێزەران دەتوانن لە دادگادا بڵێن بەڵگەکە گۆڕدراوە و دۆسیەکە دەکرێت ڕەت بکرێتەوە."}]},{id:29,code:"COMM-2800",icon:"RadioTower",accent:"#2563eb",title:"سیستەمەکانی پەیوەندیکردن و پرۆتۆکۆڵی ڕادیۆ",subtitle:"Emergency Communications & Radio Protocols",summary:"پرۆتۆکۆڵەکانی قسەکردن بە ڕادیۆ، کەناڵەکانی تەنگانە، زمانی ڕوون (Plain Language)، و پاراستنی پەیوەندییەکان لە کاتی کارەساتەکاندا.",blocks:[{body:"پەیوەندی یەکێکە لە گرنگترین شتەکان لە کاتی کارەساتەکاندا. بەبێ پەیوەندییەکی باش، هەماهەنگی نابێت و تیمەکان ناتوانن پێکەوە کار بکەن. ئەم مۆدیوولە چۆنیەتیی بەکارهێنانی ڕادیۆ و سیستەمەکانی پەیوەندی لە کاتی تەنگانەدا نیشان دەدات."},{heading:"١. بنەماکانی پەیوەندیکردنی ڕادیۆیی",body:"ڕێسا سەرەکییەکانی قسەکردن بە ڕادیۆ:",points:["سەرەتا گوێ بگرە، پاشان قسە بکە: پێش قسەکردن دڵنیا ببەوە کە کەناڵەکە چۆڵە.","وشەکانی وەڵام: «وەرگیرا»، «تێگەیشتم»، «بەڵێ».","ئەلفوبێی دەنگی (Phonetic Alphabet): Alfa، Bravo، Charlie...","کورت و ڕوون: پەیامەکەت کورت و ڕوون بکە.","دووبارەکردنەوە: پەیامە گرنگەکان (شوێن، ژمارە، فەرمان) دووبارە بکەرەوە یان داوا لە وەرگر بکە دووبارەی بکاتەوە."]},{heading:"٢. زمانی ڕوون لە جیاتی کۆدەکان (Plain Language)",body:"بەپێی NIMS/ICS، لەو ڕووداوانەی چەند دەزگایەک تێیاندا بەشدارن، قسەکردن بە زمانێکی سادە و ڕوون دەبێت. کۆدەکانی دە (Ten-codes) سیستەمێکی کۆن (Legacy) و ناوخۆیین، و واتاکانیان لە دەزگایەکەوە بۆ یەکێکی تر جیاوازن. نموونە:",points:["لە جیاتی کۆدە کۆنەکەی «10-4» بڵێ: «وەرگیرا» یان «تێگەیشتم».","لە جیاتی «10-33» بڵێ: «تەنگانە، پێویستمان بە یارمەتیی خێرا هەیە» (بۆ مەترسی لەسەر ژیانی ئاگرکوژێک: Mayday).","لە جیاتی «10-9» بڵێ: «دووبارەی بکەرەوە».","لە جیاتی «10-20» شوێنەکەت بە ناو و ناونیشان بڵێ، بۆ نموونە: «من لە نهۆمی سێیەم، لای باکوورم».","Over: پەیامەکەم تەواو بوو و چاوەڕێی وەڵامم / Out: قسەکردن کۆتایی هات."]},{heading:"٣. سیستەمەکانی پەیوەندی",body:"جۆرەکانی سیستەمی پەیوەندی:",points:["VHF/UHF: ڕادیۆ ئاساییەکانی دەستی و ئۆتۆمبێل.","مانگی دەستکرد (Satellite): بۆ کاتێک تۆڕە زەمینییەکان کار ناکەن.","Push-to-Talk (PTT): قسەکردن بە داگرتنی دوگمەیەک لە ڕێگەی ڕادیۆ یان ئەپلیکەیشنەکانی مۆبایلەوە.","Repeater: ئامێری بەهێزکردن و دووبارە بڵاوکردنەوەی سیگناڵ بۆ مەودایەکی درێژتر.","Mesh Network: تۆڕێکی خۆڕێکخەرە کە هەر ئامێرێک پەیامەکان دەگەیەنێتە ئامێرێکی تر."]},{heading:"٤. هەماهەنگی لە کاتی کارەساتەکاندا",body:"چۆنیەتیی هەماهەنگیی تیمەکان:",points:["کەناڵی هەماهەنگی: کەناڵێکی هاوبەشی دیاریکراو بۆ هەموو تیمەکانی ناو ڕووداوەکە، بەپێی پلانی پەیوەندییەکان.","کەناڵی فەرماندەیی (Command Channel): تەنها سەرکردەکانی یەکەکان و فەرماندەی ڕووداوەکە لەسەر ئەم کەناڵە قسە دەکەن.","ڕاپۆرتی کاتی دیاریکراو: وەک PAR (Personnel Accountability Report) بەپێی پلانی ڕووداوەکە یان لە کاتی گۆڕانکارییە گرنگەکاندا.","داوای فریاکەوتن: Mayday سێ جار دەوترێت (Mayday, Mayday, Mayday)، و هەموو کەس کەناڵەکە چۆڵ دەکەن.","GPS: بەدواداچوونی شوێنی هەر تیمێک."]},{heading:"٥. ڕێگا یەدەگەکان کاتێک تۆڕ کار ناکات",body:"کاتێک پەیوەندیی ئاسایی کار ناکات:",points:["نامەبەر (Runners): ئەو کەسانەی پەیامەکان بە دەست یان بە نووسین دەگەیەنن.","خاڵی کۆبوونەوەی پێشوەخت: هەموو تیمەکان لە کاتی دیاریکراودا دەگەڕێنەوە شوێنێکی لەسەر ڕێککەوتوو.","GPS Tracker: ئامێری بەدواداچوونی شوێن بۆ هەر تیمێک.","ئاماژەی ڕووناکی: بە چرا یان فلاش، بە تایبەتی بە شەو.","ئاماژەی دەنگی: دەنگی دیاریکراوی فیکە یان زەنگ کە هەموو تیمەکان واتاکەیان دەزانن."]}],media:[{kind:"video",src:"media/videos/uni_28_radio.mp4",title:"بەکارهێنانی ڕادیۆ",description:"چۆنیەتیی قسەکردن بە ڕادیۆ"},{kind:"image",src:"media/images/uni_28_phonetic.png",title:"ئەلفوبێی دەنگی",description:"ئەلفوبێی دەنگی (Phonetic Alphabet) بە نموونەوە"},{kind:"video",src:"media/videos/uni_28_coordination.mp4",title:"هەماهەنگی",description:"هەماهەنگیی تیمەکان"}],quiz:[{question:"کۆدە کۆنەکەی «10-4» بەپێی زمانی ڕوونی NIMS چۆن دەوترێت؟",options:[{text:"تەنگانە",correct:!1},{text:"وەرگیرا / تێگەیشتم",correct:!0},{text:"شوێنەکەم",correct:!1},{text:"دووبارەی بکەرەوە",correct:!1}],explanation:"10-4 کۆدێکی کۆنە بە واتای «وەرگیرا»؛ بەپێی NIMS/ICS، لە جیاتی کۆد بە زمانێکی ڕوون دەڵێن «وەرگیرا» یان «تێگەیشتم»، چونکە کۆدەکان لە هەموو دەزگاکاندا یەک واتایان نییە."},{question:"وشەی «Mayday» کەی بەکاردەهێنرێت؟",options:[{text:"بۆ سڵاوکردن",correct:!1},{text:"تەنگانەی سەخت: ژیانی کەسێک لە مەترسیدایە و پێویستی بە یارمەتی هەیە",correct:!0},{text:"کۆتاییهاتنی کار",correct:!1},{text:"پشوودان",correct:!1}],explanation:"Mayday وشەی تەنگانەی سەختە: واتە ژیانی کەسێک (بە تایبەتی ئاگرکوژێک) لە مەترسیدایە و پێویستی بە یارمەتیی خێرا هەیە."}]},{id:30,code:"LOG-2900",icon:"Package",accent:"#059669",title:"لۆجیستیک و بەڕێوەبردنی سەرچاوەکان لە کارەساتەکاندا",subtitle:"Disaster Logistics & Supply Chain Management",summary:"دابینکردنی خواردن، دەرمان و کەرەستە بۆ هەزاران کەس، و بەڕێوەبردنی کۆگا و گواستنەوە.",blocks:[{body:"لۆجیستیکی کارەساتەکان زانستی گەیاندنی کەرەستە و خزمەتگوزارییەکانە بۆ خەڵکی پێویستدار، لە ماوەیەکی کورتدا و بە شێوەیەکی دادپەروەرانە. ئەم مۆدیوولە بۆ ئەو سەرکردە و بەڕێوەبەرانە گرنگە کە پێویستە بزانن چۆن سەرچاوەکان بەڕێوە ببەن."},{heading:"١. پلاندانانی لۆجیستیکی",body:"ئامادەکاریی پێشوەخت:",points:["کۆگا: دیاریکردنی شوێنەکانی هەڵگرتنی کەرەستە پێش کارەسات.","لیستی کەرەستەکان: خواردن، ئاو، دەرمان، چادر و بەتانی.","گواستنەوە: ئۆتۆمبێل، فڕۆکە و ئامرازەکانی تر.","تیم: کارمەندی ڕاهێنراوی لۆجیستیک.","پەیوەندی: گرێبەست و پەیوەندی لەگەڵ دابینکەراندا."]},{heading:"٢. بەڕێوەبردنی کۆگا",body:"چۆنیەتیی هەڵگرتن و دابەشکردنی کەرەستەکان:",points:["ژماردن (Inventory): ژماردن و تۆمارکردنی هەموو کەرەستەکان.","کۆدکردن: کۆدێکی تایبەت بۆ هەر جۆرێکی کەرەستە.","بەسەرچوون: چاودێریکردنی بەرواری بەسەرچوونی خواردن و دەرمانەکان (ئەوەی پێش هەموویان بەسەردەچێت، پێش هەموویان دابەش دەکرێت).","پاراستن: لە گەرما، سەرما و شێ.","ئاسایش: ڕێگرتن لە دزی و زیان."]},{heading:"٣. گواستنەوە و دابەشکردن",body:"گەیاندنی کەرەستەکان بۆ شوێنی پێویست:",points:["ئۆتۆمبێل: بۆ ناو شار و ناوچە نزیکەکان.","فڕۆکە: بۆ شوێنە دوور یان دابڕاوەکان.","هەلیکۆپتەر: بۆ شوێنە شاخاوییەکان و ئەو شوێنانەی ڕێگایان لێ گیراوە.","خاڵەکانی دابەشکردن: شوێنی دیاریکراو و ئاشکرا بۆ دابەشکردنی کەرەستەکان.","تۆمارکردن: کێ وەریگرت، چیی وەرگرت و چەند."]},{heading:"٤. زنجیرەی دابینکردن (Supply Chain)",body:"هەماهەنگی لەگەڵ دابینکەراندا:",points:["دابینکەران: کۆمپانیا و ڕێکخراوەکانی دابینکردن.","داواکاری: چۆنیەتیی داواکردنی کەرەستەکان (Requisition).","گەیاندن: دیاریکردنی کات و شوێنی گەیاندن.","دارایی: بودجە و پارەدان.","بەدواداچوون (Tracking): چاودێریکردنی کەرەستەکان لە دابینکەرەوە تا وەرگر."]},{heading:"٥. بەڕێوەبردنی پەناگەکان",body:"خزمەتگوزارییەکانی پەناگەکان (بەپێی ستانداردەکانی Sphere):",points:["چادر: دانان و ڕێکخستنی پەناگە.","خواردن: دابینکردنی خواردن بۆ هەزاران کەس.","ئاو: لانیکەم ١٥ لیتر ئاوی پاک بۆ هەر کەسێک لە ڕۆژێکدا.","تەوالێت و دەستشۆر: بە ژمارەیەکی بەس و شوێنی سەلامەت بۆ ئافرەتان و منداڵان.","تەندروستی: خزمەتگوزاریی پزیشکی و فریاکەوتنی سەرەتایی."]}],media:[{kind:"video",src:"media/videos/uni_29_logistics.mp4",title:"لۆجیستیکی کارەساتەکان",description:"بنەماکانی لۆجیستیک"},{kind:"image",src:"media/images/uni_29_warehouse.png",title:"کۆگا",description:"بەڕێوەبردنی کۆگا"},{kind:"video",src:"media/videos/uni_29_distribution.mp4",title:"دابەشکردن",description:"دابەشکردنی کەرەستەکان"}],quiz:[{question:"لۆجیستیکی کارەساتەکان چییە؟",options:[{text:"کوژاندنەوەی ئاگر",correct:!1},{text:"گەیاندنی کەرەستە و خزمەتگوزاری بۆ خەڵکی پێویستدار",correct:!0},{text:"فریاکەوتنی سەرەتایی",correct:!1},{text:"ڕزگارکردن",correct:!1}],explanation:"لۆجیستیکی کارەساتەکان زانستی گەیاندنی کەرەستە و خزمەتگوزارییەکانە (خواردن، ئاو، دەرمان) بۆ خەڵکی پێویستدار."},{question:"بۆچی چاودێریکردنی بەسەرچوونی خواردن و دەرمانەکان گرنگە؟",options:[{text:"بۆ ڕەنگ",correct:!1},{text:"بۆ پاراستنی تەندروستیی خەڵک",correct:!0},{text:"بێسوودە",correct:!1},{text:"بۆ خێرایی",correct:!1}],explanation:"خواردن و دەرمانی بەسەرچوو دەتوانن زیان بە تەندروستیی خەڵک بگەیەنن، بۆیە چاودێریکردنی بەرواری بەسەرچوون زۆر گرنگە."}]},{id:31,code:"TUNNEL-3000",icon:"Construction",accent:"#57534e",title:"سەلامەتیی تونێل و شوێنە ژێرزەوییەکان",subtitle:"Tunnel & Underground Space Safety",summary:"داینامیکی ئاگر لە شوێنە داخراو و ژێرزەوییەکاندا، ڕزگارکردن لە تونێلە درێژەکاندا، و کاریگەریی دووکەڵ.",blocks:[{body:"تونێل و شوێنە ژێرزەوییەکان (وەک تونێلی ڕێگاوبانەکان، کانەکان و گەراجە ژێرزەوییەکان) مەترسیی تایبەتیان هەیە. ئاگر لەم شوێنانەدا زۆر مەترسیدارترە چونکە هەواگۆڕکێ سنووردارە، دەرچوون سەختە و دووکەڵ بە خێرایی کۆ دەبێتەوە. ئەم مۆدیوولە بۆ تونێلی ڕێگاوبانەکان و گەراجە ژێرزەوییەکانی شارەکانی هەرێم گرنگە (ستانداردی سەرەکی: NFPA 502)."},{heading:"١. تایبەتمەندییەکانی تونێلەکان",body:"تونێل چۆن لە بینایەکی ئاسایی جیاوازە:",points:["هەوا: هەواگۆڕکێی سروشتی سنووردارە و ئاگر بە خێرایی ئۆکسجین بەکاردەهێنێت.","دەرچوون: زۆرجار تەنها دوو سەری هەیە، و لە تونێلە نوێیەکاندا دەرگای تەنگانەی نێوانی (Cross-passages) هەن.","دووکەڵ: لە ژێر سەقفی نزمدا بە خێرایی بڵاو دەبێتەوە و بەرەو دوو ئاراستە یان بەپێی هەواگۆڕکێ دەڕوات.","گەرما: دیوار و سەقف گەرما دەگەڕێننەوە و گەرما کۆ دەبێتەوە.","درێژی: دەکرێت چەند کیلۆمەتر بێت، و ئەمە کاتی گەیشتنی تیمەکان درێژ دەکاتەوە."]},{heading:"٢. داینامیکی ئاگر لە تونێلەکاندا",body:"ئاگر لە تونێلدا چۆن ڕەفتار دەکات:",points:["بڵاوبوونەوە: لەو تونێلانەی هەواگۆڕکێی درێژەیییان هەیە، دووکەڵ و گەرما بە ئاراستەی با دەڕۆن؛ خەڵکی لاکەی تر (Upstream) لە دووکەڵ دەپارێزرێن.","چینبەستنی دووکەڵ (Stratification): لە سەرەتادا دووکەڵ لە ژێر سەقفدا چینێک دروست دەکات و هەوای پاک لە خوارەوە دەمێنێتەوە؛ بای زیادە یان پڕژاندنی ئاو دەتوانێت ئەم چینە تێک بدات.","Backlayering: دووکەڵ لە ژێر سەقفدا پێچەوانەی ئاراستەی هەواگۆڕکێ دەگەڕێتەوە، کاتێک خێرایی هەوا لە خێرایی سنووری (Critical Velocity) کەمتر بێت.","Longitudinal Ventilation: هەواگۆڕکێی درێژەیی بە پانکەی تایبەت (Jet Fans) کە دووکەڵ بەرەو یەک ئاراستە پاڵ دەنێن.","خێرایی پەرەسەندن: ئاگری ئۆتۆمبێل و بارهەڵگرەکان لە تونێلدا دەتوانێت بە خێرایی گەرمایەکی زۆر بەرز دروست بکات."]},{heading:"٣. سیستەمەکانی سەلامەتیی تونێلەکان",body:"کەرەستەکانی پاراستن:",points:["سیستەمی ئاگادارکردنەوە: هەستەوەرەکانی گەرما و دووکەڵ، و زەنگ.","کوژاندنەوەی ئاگر: سیستەمە ئۆتۆماتیکییەکانی ئاو (Deluge یان Water Mist) و دەرچەکانی ئاو بۆ ئاگرکوژەکان.","هەواگۆڕکێ: پانکەی تایبەت بۆ دەرکردن و کۆنتڕۆڵکردنی دووکەڵ.","دەرچوونی تەنگانە: دەرگای تایبەت و ڕێڕەوی پارێزراو بە نیشانەی ڕووناککراو.","پەیوەندی: سیستەمی ڕادیۆ لە ناو تونێلدا و تەلەفۆنی تەنگانە."]},{heading:"٤. ڕزگارکردن لە تونێلەکاندا",body:"چۆنیەتیی ڕزگارکردنی کەسەکان:",points:["ڕێڕەوی پیادە: ڕێگای تایبەتی دەرچوون بە پێ.","ئاراستەی دەرچوون: هەمیشە بەرەو هەوای پاک و دوور لە دووکەڵ.","SCBA: ئامێری هەناسەدانی سەربەخۆ بۆ هەموو ئەو ئاگرکوژانەی دەچنە ناو تونێلەکەوە.","خاڵی پۆلێنکردنی بریندارەکان (Triage): لە دەرەوەی تونێلەکە و لە شوێنێکی سەلامەتدا.","هاتوچۆ: داخستنی ڕێگاکە بۆ ئۆتۆمبێلەکان بە هەماهەنگی لەگەڵ پۆلیسی هاتوچۆ."]},{heading:"٥. ڕاهێنان و پلاندانان",body:"ئامادەکاریی پێشوەخت:",points:["پلانی تەنگانە: بۆ هەر تونێلێک پلانێکی تایبەت.","ڕاهێنان: ڕاهێنانی خولیی دەرچوون.","نەخشە: نەخشەی تونێلەکە بۆ تیمەکانی کوژاندنەوەی ئاگر.","هەماهەنگی: لەگەڵ پۆلیس و ئەمبولانس.","ئەزموون: وەرگرتنی وانە لە ڕووداوەکانی پێشوو."]}],media:[{kind:"video",src:"media/videos/uni_30_tunnel_fire.mp4",title:"ئاگری تونێل",description:"داینامیکی ئاگر لە تونێلەکاندا"},{kind:"image",src:"media/images/uni_30_ventilation.png",title:"هەواگۆڕکێ",description:"سیستەمی هەواگۆڕکێی تونێل"},{kind:"video",src:"media/videos/uni_30_evacuation.mp4",title:"دەرچوون",description:"دەرچوون لە تونێل"}],quiz:[{question:"بۆچی ئاگر لە تونێلەکاندا لە بینایەکی ئاسایی مەترسیدارترە؟",options:[{text:"هەواگۆڕکێ سنووردارە، دەرچوون سەختە، و دووکەڵ کۆ دەبێتەوە",correct:!0},{text:"هیچ جیاوازییەک نییە",correct:!1},{text:"بینا ئاساییەکان خراپترن",correct:!1},{text:"حاڵەتێکی ئاساییە",correct:!1}],explanation:"لە تونێلدا هەواگۆڕکێ سنووردارە، دەرچوونەکان کەم و دوورن، و دووکەڵ لە ژێر سەقفی نزمدا بە خێرایی کۆ دەبێتەوە؛ هەموو ئەمانە مەترسی زیاد دەکەن."},{question:"Backlayering چییە؟",options:[{text:"هەواگۆڕکێ",correct:!1},{text:"گەڕانەوەی دووکەڵ بە پێچەوانەی ئاراستەی هەواگۆڕکێ",correct:!0},{text:"ڕزگارکردن",correct:!1},{text:"کوژاندنەوەی ئاگر",correct:!1}],explanation:"Backlayering دیاردەیەکە کە تێیدا دووکەڵ لە ژێر سەقفدا بە پێچەوانەی ئاراستەی هەواگۆڕکێ دەگەڕێتەوە، کاتێک خێرایی هەوا بەس نەبێت؛ ئەمە بۆ خەڵک و تیمەکان زۆر مەترسیدارە."}]},{id:32,code:"UNI-332",icon:"FireExtinguisher",accent:"#dc2626",title:"ئاگرکوژێنەرەوە — ڕاهێنانی تەواو",subtitle:"Fire Extinguisher — Complete Training (PASS)",summary:"ناسینی هەموو جۆرەکانی ئاگرکوژێنەرەوە، پۆلەکانی ئاگر بەپێی NFPA و EN 2، ڕێکاری P.A.S.S بە درێژی، و پشکنین و چاککردنەوەی ئاگرکوژێنەرەوەکان.",blocks:[{body:"ئاگرکوژێنەرەوە (Fire Extinguisher) ئامێرێکی سەرەکییە بۆ کوژاندنەوەی ئاگرە بچووکەکان لە قۆناغی دەستپێکدا. لە زانکۆ و تاقیگەکانی توێژینەوەدا، ماددە کیمیاییەکان و ئامێرە کارەباییەکان مەترسیی ئاگر بەرز دەکەنەوە. هەر خوێندکار و مامۆستایەک پێویستە بتوانێت ئاگرکوژێنەرەوە بە خێرایی و بە دروستی بەکاربهێنێت. ئاگرکوژێنەرەوە دەستییەکان تەنها بۆ چەند چرکەیەک کار دەکەن (نزیکەی ١٠–٢٠ چرکە بۆ قەبارە بچووکەکان)، بۆیە پێویستە بە خێرایی و بە دروستی بەکاربهێنرێن. ئەگەر ئاگرەکە گەورە بوو یان دووکەڵ ڕێگای دەرچوونی گرت، ئاگرکوژێنەرەوەکە جێ بهێڵە، دەربچۆ و پەیوەندی بکە بە ١١٥."},{heading:"١. پۆلەکانی ئاگر (Fire Classes) بەپێی NFPA",body:"بەپێی سیستەمی ئەمریکی NFPA (NFPA 10)، ئاگر دەبێتە پێنج پۆل. لە سیستەمی ئەورووپی EN 2 دا: پۆلی B تەنها شلەمەنییەکانە، پۆلی C گازەکانە، کارەبا پۆلێکی جیاواز نییە، و ڕۆنی چێشتخانە پۆلی F ە:",points:["پۆلی A (ماددە ڕەقەکان): دار، کاغەز، قوماش، پلاستیک. ئاگرکوژێنەرەوە: ئاو، تۆزی ABC، کەف (Foam).","پۆلی B (شلەمەنی و گازە ئاگرگرەکان): بەنزین، نەوت، ڕۆن، ئەلکهول، سۆڵڤێنتەکانی تاقیگە. ئاگرکوژێنەرەوە: CO₂، تۆزی ABC، کەف. (هەرگیز ئاو بەکار مەهێنە!)","پۆلی C (ئامێرە کارەباییەکانی بەستراو بە کارەباوە): سویچ، ترانسفۆرمەر، پانێڵ، مۆلیدە، سێرڤەر. ئاگرکوژێنەرەوە: CO₂، تۆزی ABC، Clean Agent. (ئاو و کەف قەدەغەن!) ئەگەر سەلامەت بوو، سەرەتا کارەبا بپچڕێنە.","پۆلی D (کانزا ئاگرگرەکان): مەگنیسیۆم، تۆزی ئەلەمنیۆم، تیتانیۆم، لیتیۆم (کانزا). ئاگرکوژێنەرەوە: تۆزی تایبەتی پۆلی D. (ئاو دەتوانێت کارلێکێکی توند و تەقینەوە دروست بکات!) تێبینی: ئاگری پاترییەکانی لیتیۆم-ئایۆن پۆلی D نییە؛ ئاو و ساردکردنەوەی بەردەوام پێشنیار دەکرێت.","پۆلی K (ڕۆنەکانی چێشتخانە؛ لە EN 2 دا پۆلی F): ڕۆن و چەورییەکانی چێشتلێنان. ئاگرکوژێنەرەوە: Wet Chemical (بەپێی BS EN 3 و BS 7863 بە ڕەنگی زەرد). (ئاو ڕۆنی سووتاو دەپەڕێنێت و ئاگرەکە بڵاو دەکاتەوە!)"]},{heading:"٢. جۆرەکانی ئاگرکوژێنەرەوە و ڕەنگەکانیان",body:"بەپێی ستانداردی ئەورووپی BS EN 3، لاشەی ئاگرکوژێنەرەوە سوورە و پارچەیەکی ڕەنگکراو نیشانەی جۆرەکەیە (لە NFPA دا ڕەنگ نیشانەی جۆر نییە؛ لەیبڵەکە (Label) بخوێنەرەوە):",points:["ئاگرکوژێنەرەوەی ئاو (Water): سوور. تەنها بۆ پۆلی A (دار، کاغەز). هەرگیز بۆ کارەبا یان ڕۆن بەکاری مەهێنە!","ئاگرکوژێنەرەوەی CO₂: ڕەش. بۆ پۆلی B و ئامێرە کارەباییەکان. گازێکی زۆر سارد دەردەچێت و لوولەکەی (Horn) زۆر سارد دەبێت؛ دەست لە لوولەکە مەدە، دەستت دەسووتێنێت (سەرمابردن). مەودای بەکارهێنان: ١–٢ مەتر. لە ژوورە بچووکەکاندا دوای بەکارهێنان ژوورەکە جێ بهێڵە.","ئاگرکوژێنەرەوەی تۆزی ABC (Dry Powder): شین. بۆ پۆلەکانی A، B و C (نەک بۆ D و نەک بۆ K/F). بڵاوترین جۆرە. کەموکوڕی: بینین کەم دەکاتەوە و ئامێرەکان پیس دەکات.","ئاگرکوژێنەرەوەی کەف (Foam/AFFF): کرێمی. بۆ پۆلەکانی A و B. کەف لەسەر شلەمەنییەکە بڵاو دەکاتەوە و ئۆکسجین دەبڕێت. بۆ کارەبا بەکاری مەهێنە! تێبینی: کەفی AFFF ماددەی PFAS ی تێدایە و لە زۆر وڵاتدا بە کەفی بێ فلۆر (Fluorine-Free) دەگۆڕدرێت.","ئاگرکوژێنەرەوەی Clean Agent: بۆ پۆلەکانی B و C (هەندێک جۆر بۆ A یش) - بۆ ئامێرە هەستیارەکان، تاقیگە و ژووری سێرڤەرەکان. هیچ پاشماوەیەک بەجێ ناهێڵێت.","ئاگرکوژێنەرەوەی تایبەت (Class D): بۆ کانزا ئاگرگرەکان - تۆزێکی تایبەتی تێدایە (بە گشتی لەیبڵەکەی زەرد یان شینە؛ بەپێی لەیبڵەکە بەکاری بهێنە)."]},{heading:"٣. ڕێکاری P.A.S.S بە درێژی",body:"ئەمە ڕێکاری نێودەوڵەتییە بۆ بەکارهێنانی ئاگرکوژێنەرەوە؛ لە مەودایەکی سەلامەتەوە دەست پێ بکە و ڕێگای دەرچوون لە پشتی خۆتەوە بهێڵە و هەرگیز پشت لە ئاگرەکە مەکە:",points:["P = Pull (ڕابکێشە): سنجاقی سەلامەتی (Safety Pin) ڕابکێشە. ئەم سنجاقە ناهێڵێت ئاگرکوژێنەرەوەکە بە هەڵە کار بکات.","A = Aim (ئاراستە بکە): لوولەی ئاگرکوژێنەرەوەکە بەرەو بنی ئاگرەکە بگرە، نەک بەرەو گڕی سەرەوە!","S = Squeeze (بگوشە): دەسکی ئاگرکوژێنەرەوەکە بە هێز بگوشە بۆ ئەوەی ماددەکە دەربچێت.","S = Sweep (بیجووڵێنە): لوولەکە بە چەپ و ڕاستدا لەسەر بنی ئاگرەکە بجووڵێنە تا ئاگرەکە بە تەواوی دەکوژێتەوە، و چاودێری بکە بۆ ئەوەی دووبارە گڕ نەگرێتەوە."]},{heading:"٤. پشکنین و چاککردنەوەی ئاگرکوژێنەرەوەکان (NFPA 10)",body:"هەموو مانگێک پێویستە ئەم خاڵانە بە پشکنینێکی بینراو بپشکنرێن:",points:["پەستانی ناو ئاگرکوژێنەرەوەکە (Pressure Gauge): پێویستە دەرزیی پێوەرەکە لە ناوچە سەوزەکەدا بێت.","سنجاقی سەلامەتی: پێویستە لە شوێنی خۆیدا بێت و مۆرەکە (Seal) نەشکابێت.","لوولە (Nozzle/Hose): نابێت شکاو یان گیراو بێت.","لاشەی ئاگرکوژێنەرەوەکە: نابێت ژەنگاوی، درزدار یان زیانلێکەوتوو بێت، و پێویستە لە شوێنی خۆیدا بێت و بە ئاسانی دەستی پێ بگات.","چاککردنەوەی ساڵانە (Annual Maintenance) لەلایەن کەسێکی شارەزاوە؛ و تاقیکردنەوەی هایدرۆستاتیکی (Hydrostatic Test) بەپێی ماوە دیاریکراوەکان: هەر ٥ ساڵ جارێک بۆ ئاو، کەف، CO₂ و Wet Chemical، و هەر ١٢ ساڵ جارێک بۆ زۆربەی ئاگرکوژێنەرەوە تۆزییەکان. ئەمە گۆڕین نییە؛ ئاگرکوژێنەرەوە تەنها کاتێک دەگۆڕدرێت کە لە پشکنین یان تاقیکردنەوەدا سەرنەکەوێت؛ بەڵام ئاگرکوژێنەرەوەی یەکجاری (Non-rechargeable) دوای ١٢ ساڵ لە ڕێکەوتی دروستکردنی لادەبرێت."]},{heading:"٥. مەترسییە تایبەتەکان لە زانکۆکاندا",body:"زانکۆکان شوێنی هەستیارن لەبەر ئەمانە:",points:["تاقیگە کیمیاییەکان: سۆڵڤێنت و ئەلکهول (پۆلی B)، و هەندێک کانزای چالاک (پۆلی D).","ژووری سێرڤەر و IT: ئامێری بەستراو بە کارەباوە (پۆلی C لە NFPA دا): Clean Agent یان CO₂.","چێشتخانەکانی زانکۆ: ڕۆنی چێشتلێنان (پۆلی K لە NFPA دا / F لە EN 2 دا).","کتێبخانە و ئەرشیف: کاغەز و دار (پۆلی A).","شوێنی دانان: ئاگرکوژێنەرەوەکان لە نزیک دەرگا و ڕاڕەوەکاندا دابنێ؛ بەپێی NFPA 10، مەودای ڕۆیشتن بۆ گەیشتن بە ئاگرکوژێنەرەوەیەک لە شوێنەکانی پۆلی A دا نابێت لە ٢٣ مەتر (٧٥ پێ) زیاتر بێت، و لە شوێنەکانی پۆلی B دا کەمترە (٩–١٥ مەتر)."]}],media:[{kind:"video",src:"media/videos/uni_fire_ext.mp4",title:"ئاگرکوژێنەرەوە",description:"ڕێکاری P.A.S.S و جۆرەکانی ئاگرکوژێنەرەوە"}],quiz:[{question:"ئاگرکوژێنەرەوەی CO₂ (ڕەش) بۆ کام لە پۆلەکانی ئاگر (بەپێی NFPA) گونجاوە؟",options:[{text:"A و D",correct:!1},{text:"B و C",correct:!0},{text:"A و K",correct:!1},{text:"D و K",correct:!1}],explanation:"CO₂ بۆ شلەمەنییە ئاگرگرەکان (B) و ئامێرە کارەباییەکان (C) گونجاوە چونکە کارەبا ناگەیەنێت و پاشماوە بەجێ ناهێڵێت."},{question:"لە ڕێکاری P.A.S.S دا، لوولەی ئاگرکوژێنەرەوەکە پێویستە بەرەو کوێ بێت؟",options:[{text:"سەرەوەی گڕەکە",correct:!1},{text:"بنی ئاگرەکە",correct:!0},{text:"دوور لە ئاگرەکە",correct:!1},{text:"سەقف",correct:!1}],explanation:"هەمیشە لوولەکە بەرەو بنی ئاگرەکە ئاراستە بکە، چونکە سووتەمەنییەکە لەوێیە و ئاگرەکە لەوێوە دەکوژێنرێتەوە."},{question:"لە تاقیگەی زانکۆدا ئاگرێکی شلەمەنییەکی کیمیاییی ئاگرگر ڕوویدا؛ کام ئاگرکوژێنەرەوە بەکاردەهێنیت؟",options:[{text:"ئاو (سوور)",correct:!1},{text:"CO₂ یان ABC (ڕەش/شین)",correct:!0},{text:"تۆزی تایبەتی پۆلی D",correct:!1},{text:"Wet Chemical",correct:!1}],explanation:"ئاگری شلەمەنییە ئاگرگرەکان پۆلی B ە: CO₂ یان تۆزی ABC گونجاون. ئەگەر ئاگرەکە گەورە بوو، شوێنەکە جێ بهێڵە و پەیوەندی بکە بە ١١٥."}]}],t={lessons:e};export{t as default,e as lessons};
